DELIMITER $$
--
-- Procedures
--
CREATE PROCEDURE `GetPopularBlogs` (IN `days` INT, IN `limit_count` INT)
BEGIN
    SELECT 
        b.id,
        b.title,
        b.slug,
        b.featured_image,
        b.published_at,
        b.views,
        COUNT(bv.id) as recent_views,
        (b.views * 0.7 + COUNT(bv.id) * 0.3) as popularity_score
    FROM blogs b
    LEFT JOIN blog_views bv ON b.id = bv.blog_id 
        AND bv.viewed_at >= DATE_SUB(NOW(), INTERVAL days DAY)
    WHERE b.status = 'published' 
        AND b.published_at <= NOW()
    GROUP BY b.id
    ORDER BY popularity_score DESC
    LIMIT limit_count;
END$$

DELIMITER ;

