(2, 'CTET September Online Form 2026', 'ctet-september-online-form-2026', 'Apply online for Central Teacher Eligibility Test (CTET) September 2026. CBSE CTET exam for primary & upper primary teachers.', 'CTET September 2026 notification by CBSE. Candidates who wish to teach in Classes 1 to 8 can apply online. Paper I (Classes 1-5) and Paper II (Classes 6-8). Validity: Lifetime.', 1, 1, '2026-06-15', '2026-07-15', '2026-09-20', 1000.00, 500000, 'Minimum 50% in Senior Secondary (or equivalent) for Primary teacher. For Elementary teacher: Graduation with 50% + B.Ed or equivalent. Age: No upper age limit.', '1. Visit official CTET website.<br>2. Register & fill application form.<br>3. Upload scanned photo & signature.<br>4. Pay fee online.<br>5. Submit & print confirmation page.', 'Start of online application: 15 June 2026<br>Last date to apply: 15 July 2026<br>Admit card: September 2026<br>Exam date: 20 September 2026', 'CTET Helpline: 011-22235774<br>Email: ctet@cbse.gov.in', 'https://ctet.nic.in', 'https://ctet.nic.in/brochure2026.pdf', 'https://ctet.nic.in/apply2026', 1, 1, 'CTET September 2026 Online Form | CBSE CTET Notification', 'Apply for CTET September 2026. Check eligibility, exam date (20 Sept 2026), last date (15 July 2026), fee, and apply online at ctet.nic.in.', 65, '2026-05-30 20:32:10', '2026-07-31 02:36:13'),
(4, 'NTA CSIR UGC NET June Online Form 2026', 'nta-csir-ugc-net-june-online-form-2026', 'Apply online for CSIR UGC NET June 2026 for JRF (Junior Research Fellowship) and Lectureship/Assistant Professor. Subjects: Chemical Sciences, Earth Sciences, Life Sciences, Mathematical Sciences, Physical Sciences.', 'CSIR UGC NET June 2026 notification by NTA. Candidates who have completed MSc or equivalent with minimum 55% marks (50% for SC/ST/PwD) can apply. Exam conducted for determining eligibility for JRF and Assistant Professor in Indian universities and colleges. Paper consists of two parts: Part A (General Aptitude) and Part B & C (Subject-specific).', 1, 1, '2026-03-15', '2026-04-15', '2026-06-20', 1200.00, 50000, 'MSc or equivalent degree with minimum 55% marks (50% for SC/ST/PwD/third gender) from a recognized university. Final year students can also apply. Age limit: For JRF: maximum 28 years (relaxation as per govt norms). For Lectureship: No upper age limit.', '1. Visit official CSIR UGC NET website (csirnet.nta.ac.in).<br>2. Register using mobile/email.<br>3. Fill online application form.<br>4. Upload scanned photo, signature, and category certificate (if applicable).<br>5. Pay application fee via debit/credit card, net banking, or UPI.<br>6. Submit form and download confirmation page.', 'Online application start: 15 March 2026<br>Last date for submission: 15 April 2026<br>Last date for fee payment: 16 April 2026<br>Correction window: 18-20 April 2026<br>Admit card release: June 2026<br>Exam date: 20 June 2026 (tentative)<br>Answer key release: July 2026<br>Result declaration: August 2026', 'NTA Helpdesk: 011-40759000<br>Email: csirnet@nta.ac.in<br>CSIR: www.csir.res.in', 'https://csirnet.nta.ac.in', 'https://csirnet.nta.ac.in/information-bulletin-2026.pdf', 'https://csirnet.nta.ac.in/apply-2026', 1, 1, 'NTA CSIR UGC NET June 2026 Online Form | JRF & Lectureship Application', 'Apply online for CSIR UGC NET June 2026 for JRF and Assistant Professor. Check eligibility, exam date (20 June 2026), last date (15 April 2026), fee, and subjects (Chemical, Life, Mathematical Sciences).', 1, '2026-05-30 20:37:35', '2026-07-31 02:36:13'),
(5, 'SWD UP IAS / PCS Free Coaching Online Form 2026', 'swd-up-ias-pcs-free-coaching-online-form-2026', 'Apply online for UP Social Welfare Department free residential coaching scheme for IAS/PCS 2026. SC/ST/OBC candidates with graduation degree can apply. Total 865-890 seats. No application fee.', 'Uttar Pradesh Social Welfare Department (SWD) invites online applications for free residential coaching for IAS/PCS Preliminary Examination 2026. The scheme is designed for SC/ST/OBC candidates who are permanent residents of UP with family income less than ₹6 lakh per annum. Selected candidates will receive free coaching, accommodation, food, library facilities, test series, and guidance from senior IAS/PCS officers at 8 residential centers across Uttar Pradesh. Admission is based on a Joint Entrance Examination to be held on 5 July 2026 [citation:1][citation:5][citation:9].', 1, 2, '2026-05-18', '2026-06-18', '2026-07-05', 0.00, 890, '1. Permanent resident of Uttar Pradesh.<br>2. Must belong to SC/ST/OBC category.<br>3. Graduation degree from a recognized university in any discipline.<br>4. Minimum age 21 years.<br>5. Annual family income not exceeding ₹6 lakh.<br>6. General category candidates are NOT eligible [citation:2][citation:7][citation:8].', '<strong>Step 1:</strong> Visit official website: socialwelfareup.upsdc.gov.in<br>\r\n    <strong>Step 2:</strong> Click on \"SWD Uttar Pradesh 2026 Apply Online\" link<br>\r\n    <strong>Step 3:</strong> Register by entering basic details (mobile/email)<br>\r\n    <strong>Step 4:</strong> Login and fill personal, educational, and category details<br>\r\n    <strong>Step 5:</strong> Upload scanned photo, signature, caste certificate, income certificate, and domicile certificate<br>\r\n    <strong>Step 6:</strong> Review the form carefully and submit<br>\r\n    <strong>Step 7:</strong> Take a printout of the application form for future reference [citation:1][citation:10]', '<strong>Online application start:</strong> 18 May 2026<br>\r\n    <strong>Last date to apply:</strong> 18 June 2026<br>\r\n    <strong>Last date for correction:</strong> 18 June 2026<br>\r\n    <strong>Admit card release:</strong> 25 June 2026<br>\r\n    <strong>Entrance exam date:</strong> 05 July 2026<br>\r\n    <strong>Result declaration:</strong> 28 July 2026<br>\r\n    <strong>Coaching session starts:</strong> 01 August 2026 [citation:1][citation:2][citation:6]', '<strong>Helpline:</strong> 14568<br>\r\n    <strong>Email:</strong> director.sw@dirsamajkalyan.in<br>\r\n    <strong>Official Website:</strong> socialwelfareup.upsdc.gov.in [citation:10]', 'https://socialwelfareup.upsdc.gov.in', 'https://socialwelfareup.upsdc.gov.in/notice/ias-pcs-free-coaching-2026-brochure.pdf', 'https://socialwelfareup.upsdc.gov.in/apply-ias-pcs-coaching-2026', 1, 1, 'SWD UP IAS PCS Free Coaching 2026 - Online Form | सामाजिक कल्याण विभाग उत्तर प्रदेश', 'Apply online for UP SWD Free IAS/PCS Coaching 2026. Eligibility: SC/ST/OBC, graduation, income less than 6 lakh. Last date 18 June 2026. No application fee. 890 seats.', 40, '2026-05-30 20:44:20', '2026-07-31 02:36:13'),
(7, 'Patna University UG Online Form 2026', 'patna-university-ug-online-form-2026', 'Apply online for Patna University UG Admissions 2026 for B.A., B.Sc., B.Com., BBA, BCA, LLB, and other undergraduate courses. Admission through PU CET entrance exam.', 'Patna University invites online applications for undergraduate programs for the academic session 2026-27. Admission is based on the Patna University Common Entrance Test (PU CET) followed by counselling. Participating colleges include Patna College, Science College, B.N. College, Women\'s College, and Magadh Mahila College. Programs offered: B.A. (Honours), B.Sc. (Honours), B.Com. (Honours), BBA, BCA, LLB (5 years integrated), B.Ed., B.P.Ed., B.Lib.Sc., Bachelor of Performing Arts, Bachelor of Fine Arts, and various vocational courses. Reservation policy as per Government of Bihar norms.', 2, 3, '2026-04-01', '2026-05-15', '2026-06-10', 1200.00, 8000, '10+2 (Intermediate) or equivalent examination from any recognized board (BSEB, CBSE, ICSE, etc.). Minimum 45% marks (40% for SC/ST/BC/EBC/PwD) in aggregate. For B.Sc. Honours: 50% marks in relevant subject. For B.Com.: 45% marks with Mathematics. For BBA/BCA: 45% marks. For LLB (5 years): 45% marks (40% for reserved categories). Candidates awaiting 12th results can also apply provisionally.', '1. Visit official Patna University admission portal (puadmission.in).<br>2. Click on \"UG Admission 2026\" and register with email/mobile.<br>3. Fill online application form with personal, educational, and category details.<br>4. Upload scanned recent photograph (10-100 KB) and signature (4-40 KB).<br>5. Upload caste certificate (if applicable) and other relevant documents.<br>6. Pay application fee online via debit card, credit card, net banking, or UPI.<br>7. Submit the form and download/print confirmation page for future reference.<br>8. Download PU CET admit card from the portal before exam date.', '<strong>Online application start:</strong> 01 April 2026<br>\r\n    <strong>Last date to apply:</strong> 15 May 2026<br>\r\n    <strong>Last date for fee payment:</strong> 15 May 2026<br>\r\n    <strong>Correction window:</strong> 16-18 May 2026<br>\r\n    <strong>Admit card release:</strong> 31 May 2026<br>\r\n    <strong>PU CET exam date:</strong> 10-12 June 2026<br>\r\n    <strong>Answer key release:</strong> 20 June 2026<br>\r\n    <strong>Result declaration:</strong> 30 June 2026<br>\r\n    <strong>Counselling starts:</strong> 10 July 2026<br>\r\n    <strong>Academic session begins:</strong> 01 August 2026', '<strong>Patna University Helpline:</strong> 0612-2670001<br>\r\n    <strong>Toll Free:</strong> 1800-345-6789<br>\r\n    <strong>Email:</strong> ugadmission@patnauniversity.ac.in<br>\r\n    <strong>Address:</strong> Patna University, Ashok Rajpath, Patna - 800005, Bihar', 'https://www.patnauniversity.ac.in', 'https://puadmission.in/ug-brochure-2026.pdf', 'https://puadmission.in/ug-apply-2026', 1, 1, 'Patna University UG Admission 2026 Online Form | PU CET Application', 'Apply online for Patna University UG Admissions 2026 for B.A., B.Sc., B.Com., BBA, BCA, LLB. Check eligibility, last date (15 May 2026), PU CET exam date (10 June 2026), application fee, and course list.', 1, '2026-05-30 20:45:48', '2026-07-31 02:36:13'),
(9, 'Delhi University DU PG Online Form 2026', 'delhi-university-du-pg-online-form-2026', 'Apply online for Delhi University PG Admissions 2026 for M.A., M.Sc., M.Com., MBA, LLM, MCA, and other postgraduate courses. Admission through CSAS-PG portal based on CUET PG 2026 scores.', 'Delhi University (DU) invites online applications for postgraduate programs for the academic session 2026-27. Admission will be conducted through the Common Seat Allocation System for PG (CSAS-PG) based on CUET PG 2026 scores. Participating faculties include Arts, Commerce & Business Studies, Sciences, Law, Management, Social Sciences, Education, Music & Fine Arts, Interdisciplinary & Applied Sciences, and East Asian Studies. Over 100+ PG programs are offered across 50+ departments and colleges. Reservation policy as per UGC/Government of India norms including OBC (NCL), SC, ST, EWS, and PwD categories. Candidates can apply for multiple programs through a single application form.', 1, 2, '2026-04-20', '2026-06-05', NULL, 1500.00, 12000, '<strong>Educational Qualification:</strong> Bachelor\'s degree (Honours/Pass) in relevant discipline with minimum 50% marks (45% for OBC/SC/ST/PwD/EWS) from a recognized university. Specific eligibility varies by program. For M.A.: Bachelor\'s in relevant subject. For M.Sc.: B.Sc. in relevant subject with required percentage. For M.Com.: B.Com. or equivalent. For MBA: Bachelor\'s with 50% + CAT/MAT/CMAT score. For LLM: LLB with 50%.<br>\r\n    <strong>Appearing Candidates:</strong> Candidates awaiting final year results can also apply provisionally.<br>\r\n    <strong>Entrance Requirement:</strong> Valid CUET PG 2026 score is mandatory for most programs.', '<strong>Step 1:</strong> Visit official DU CSAS-PG portal (pgadmission.uod.ac.in)<br>\r\n    <strong>Step 2:</strong> Click on \"PG Admission 2026\" and register using email ID and mobile number<br>\r\n    <strong>Step 3:</strong> Fill the online application form with personal, academic, and CUET PG details<br>\r\n    <strong>Step 4:</strong> Upload scanned recent photograph (10-100 KB) and signature (4-40 KB)<br>\r\n    <strong>Step 5:</strong> Upload category/caste certificate (if applicable), EWS certificate, PwD certificate, and other relevant documents<br>\r\n    <strong>Step 6:</strong> Pay application fee online via debit card, credit card, net banking, or UPI<br>\r\n    <strong>Step 7:</strong> Select preferred programs and college/department preferences<br>\r\n    <strong>Step 8:</strong> Submit the form and download/print confirmation page for future reference<br>\r\n    <strong>Step 9:</strong> Participate in subsequent rounds of seat allocation (CSAS-PG)', '<strong>Online registration start:</strong> 20 April 2026<br>\r\n    <strong>Last date to apply:</strong> 05 June 2026<br>\r\n    <strong>Last date for fee payment:</strong> 06 June 2026<br>\r\n    <strong>Correction window:</strong> 08-10 June 2026<br>\r\n    <strong>CSAS-PG application (preference filling) start:</strong> 25 June 2026<br>\r\n    <strong>First merit list/cutoff release:</strong> 10 July 2026<br>\r\n    <strong>Seat allocation round 1:</strong> 15-20 July 2026<br>\r\n    <strong>Seat allocation round 2:</strong> 25-30 July 2026<br>\r\n    <strong>Physical document verification:</strong> 01-05 August 2026<br>\r\n    <strong>Academic session begins:</strong> 10 August 2026', '<strong>DU PG Admission Helpline:</strong> 011-27006900, 011-27006800<br>\r\n    <strong>Toll Free:</strong> 1800-111-999<br>\r\n    <strong>Email (General):</strong> pgadmission@uod.ac.in<br>\r\n    <strong>Email (Technical):</strong> support@pgadmission.uod.ac.in<br>\r\n    <strong>Address:</strong> Admission Branch, University of Delhi, Delhi - 110007<br>\r\n    <strong>Website:</strong> admission.uod.ac.in | du.ac.in', 'https://admission.uod.ac.in', 'https://admission.uod.ac.in/pg-brochure-2026.pdf', 'https://pgadmission.uod.ac.in/apply', 1, 1, 'Delhi University DU PG Admission 2026 Online Form | CSAS-PG CUET PG Based', 'Apply online for DU PG Admissions 2026 for M.A., M.Sc., M.Com., MBA, LLM, MCA. Check eligibility, last date (05 June 2026), application fee (₹1500), and program list. Register on CSAS-PG portal.', 31, '2026-05-30 20:46:56', '2026-07-31 02:36:13'),
(10, 'DU UG Admission Form 2026 (CSAS Portal)', 'du-ug-admission-form-2026-csas-portal', 'University of Delhi (DU) has launched the Common Seat Allocation System (CSAS UG 2026) for Undergraduate Course Admissions.', 'Delhi University CSAS UG 2026 Online Application Form Released.\n\nCandidates qualified in CUET UG 2026 can register on the official DU CSAS portal.', 1, 46, '2026-07-01', '2026-08-25', '2026-08-30', 250.00, 70000, 'Passed 10+2 (Intermediate) with minimum 50% marks & CUET UG 2026 score.', 'Online registration at ugadmission.uod.ac.in, fill preferences, document verification.', NULL, NULL, 'https://du.ac.in', NULL, 'https://ugadmission.uod.ac.in', 1, 1, NULL, NULL, 1, '2026-07-31 01:55:35', '2026-07-31 02:36:13'),
(11, 'BHU CUET UG & PG Admission Online Form 2026', 'bhu-cuet-ug-pg-admission-online-form-2026', 'Banaras Hindu University (BHU) Counseling and Registration for UG / PG Courses Admission 2026.', 'BHU Admission 2026 Registration Open for Undergraduate and Postgraduate programs.', 1, 46, '2026-07-05', '2026-08-20', '2026-08-28', 300.00, 12000, '10+2 passed for UG courses / Graduation for PG courses.', 'Register on BHU Student Counseling Portal.', NULL, NULL, 'https://bhuonline.in', NULL, 'https://bhuonline.in', 1, 1, NULL, NULL, 1, '2026-07-31 01:55:35', '2026-07-31 02:36:13'),
(12, 'JEECUP UP Polytechnic Diploma Admission 2026', 'jeecup-up-polytechnic-diploma-admission-2026', 'Joint Entrance Examination Council Uttar Pradesh (JEECUP) Diploma Engineering & Pharmacy Admission 2026.', 'JEECUP UP Polytechnic 2026 Counseling & Online Registration for Diploma Seats.', 1, 46, '2026-07-10', '2026-08-28', '2026-09-05', 350.00, 150000, 'Class 10th (High School) passed with minimum 35% marks.', 'Apply online at jeecup.admissions.nic.in.', NULL, NULL, 'https://jeecup.admissions.nic.in', NULL, 'https://jeecup.admissions.nic.in', 1, 1, NULL, NULL, 1, '2026-07-31 01:55:35', '2026-07-31 02:36:13'),
(13, 'IGNOU July Session Admission Online Form 2026', 'ignou-july-session-admission-online-form-2026', 'Indira Gandhi National Open University (IGNOU) Fresh Admission for July 2026 Cycle.', 'IGNOU July 2026 Session Open Distance Learning (ODL) and Online Program Fresh Admission Open.', 1, 46, '2026-07-01', '2026-08-31', NULL, 300.00, NULL, '10+2 passed for UG / Bachelor Degree for PG.', 'Online submission via ignouadmission.samarth.edu.in.', NULL, NULL, 'https://ignou.ac.in', NULL, 'https://ignouadmission.samarth.edu.in', 1, 1, NULL, NULL, 1, '2026-07-31 01:55:35', '2026-07-31 02:36:13');

