(2, 16, 'SSC CHSL Tier-II Admit Card 2026 – Out', NULL, 'ssc-chsl-tier-ii-admit-card-2026-out', 'Candidates Can Also Check Tier-II Admit Card using their Enrollment Number, Registration Number, or Date of Birth by logging into the portal.', NULL, '2026-04-10', '2026-04-15', NULL, 'https://ssc.gov.in/', 'https://ssc.gov.in/login', 'admit-cards/1775645980_ssc-chsl-tier-ii-admit-card-2026-out.pdf', NULL, NULL, NULL, 0, 0, 2, 344, NULL, 'Candidates Can Also Check Tier-II Admit Card using their Enrollment Number, Registration Number, or Date of Birth by logging into the portal.', NULL, '2026-04-08 05:29:40', '2026-07-31 01:29:52'),
(3, 18, 'SSC GD Constable Exam Slot Booking 2026', NULL, 'ssc-gd-constable-exam-slot-booking-2026', 'The Staff Selection Commission (SSC) has introduced a preference-based scheduling system for the SSC GD Constable 2026 exam, moving away from the earlier \"no slot selection\" policy . Instead of choosing a specific date or shift, you will now select your preferred exam week from four available windows.', 'SSC GD 2026 Exam Schedule & Slot Selection Details\r\nThe key dates and process for the exam and slot selection are as follows:\r\nSlot Booking : 11 - 15 April 2026  \r\n\r\nEvent	Details\r\nExam Period	April 27, 2026 – May 30, 2026 \r\nSlot Selection Period	April 11, 2026 (3:00 PM) – April 15, 2026 (5:00 PM) \r\nMode of Selection	Preference-based for exam weeks, not specific dates/shifts \r\nOfficial Website	ssc.gov.in \r\nHere are the four available exam weeks:\r\n\r\nWeek 1: April 27, 2026 – May 2, 2026\r\n\r\nWeek 2: May 4, 2026 – May 9, 2026\r\n\r\nWeek 3: May 18, 2026 – May 23, 2026\r\n\r\nWeek 4: May 25, 2026 – May 30, 2026\r\n\r\n✅ How to Submit Your Exam Week Preference\r\nThe window to submit your preference is active now. To complete the process:\r\n\r\nVisit the Official Website: Go to ssc.gov.in and click on the \"Login\" or \"Candidate Login\" button .\r\n\r\nLog In: Enter your Registration Number and Password to access your dashboard.\r\n\r\nFind the Slot Selection Link: Look for and click on the link that says \"SSC GD Constable Exam Slot Selection 2026\" or similar .\r\n\r\nSubmit Your Preferences: You will be asked to rank all four exam weeks in order of preference. Carefully select your most preferred week first, then your second choice, and so on .\r\n\r\nReview and Submit: Confirm your choices before final submission. You should download a confirmation page for your records', '2026-04-23', '2026-04-27', NULL, 'https://ssc.gov.in/', 'https://ssc.gov.in/login', 'admit-cards/1775911128_ssc-gd-constable-exam-slot-booking-2026.pdf', NULL, 'Do Not Delay: The window is open for a limited time (until April 15, 2026). Complete your preference selection well before the deadline to avoid last-minute technical issues.\r\n\r\nNo Specific Slot Booking: This process is different from a \"self slot booking\" system. You are selecting a week, not a specific date, shift, or time for your exam . Your exact exam date and shift within your allotted week will be communicated later on your admit card.', NULL, 1, 0, 0, 432, NULL, 'SSC GD 2026 Exam Schedule & Slot Selection Details', NULL, '2026-04-11 07:08:48', '2026-07-31 01:29:52'),
(4, 1, 'Bihar CET B.Ed Admit Card 2026', '2026-04-15', 'bihar-cet-bed-admit-card-2026', 'Bihar CET B.Ed 2026 admit card has been released. Download your entrance exam hall ticket from the official website.', '<p>The Bihar Combined Entrance Competitive Examination Board (BCECEB) has released the admit card for Bihar CET B.Ed 2026. Candidates appearing for the Bachelor of Education entrance exam can download their hall ticket from the official website. The admit card contains candidate details, exam date, time, and venue information. It is mandatory to carry a printed copy of the admit card along with a valid photo ID to the examination center.</p>', '2026-04-20', '2026-05-10', 'Various centers across Bihar (Patna, Gaya, Bhagalpur, Muzaffarpur, Darbhanga, Purnea, etc.)', 'https://bceceboard.bihar.gov.in', 'https://bceceboard.bihar.gov.in/downloads/cet-bed-2026-admit-card', 'uploads/admit_cards/bihar_cet_bed_2026_admit_card.pdf', NULL, '<ul><li>Reach the exam center at least 1 hour before the exam time.</li><li>Carry a printed copy of the admit card.</li><li>Carry a valid photo ID proof (Aadhar Card/PAN Card/Driving License/Voter ID/Passport).</li><li>No electronic devices including mobile phones, calculators, or smartwatches are allowed.</li><li>Use only black/blue ballpoint pen for filling the OMR sheet.</li><li>Follow all COVID-19 guidelines if applicable.</li></ul>', '<ul><li>Printed copy of Bihar CET B.Ed 2026 Admit Card</li><li>Original valid Photo ID proof</li><li>Passport size photograph (same as uploaded in application form)</li><li>PwD certificate (if applicable)</li></ul>', 1, 1, 0, 212, 'Bihar CET B.Ed Admit Card 2026 - Download Hall Ticket | BCECEB', 'Download Bihar CET B.Ed 2026 admit card from official BCECEB website. Check exam date, venue, instructions and required documents for B.Ed entrance exam.', 'Bihar CET B.Ed Admit Card 2026, Bihar B.Ed Hall Ticket, BCECEB Admit Card, Bihar CET B.Ed Exam Date 2026, Bihar B.Ed Entrance Exam', '2026-05-30 20:04:38', '2026-07-31 02:41:09'),
(5, 2, 'UP CNET Admit Card 2026 Out', '2026-05-30', 'up-cnet-admit-card-2026', 'UP CNET 2026 admit card has been officially released by ABVMU. Download your B.Sc Nursing hall ticket now.', '<p>The Atal Bihari Vajpayee Medical University (ABVMU) has officially released the admit card for the Uttar Pradesh Common Nursing Entrance Test (UP CNET) 2026 on May 30, 2026 [citation:4][citation:7]. Candidates who have registered for the B.Sc Nursing, Post Basic B.Sc Nursing, and M.Sc Nursing courses can now download their hall tickets from the official website [citation:6].</p>\r\n\r\n<p>The UP CNET 2026 examination is scheduled to be held on June 6, 2026, in a single shift from 11:00 AM to 1:20 PM across various centers in Uttar Pradesh [citation:6][citation:10]. The exam will be conducted in offline mode (pen and paper) using an OMR sheet [citation:6].</p>\r\n\r\n<p>The admit card is a mandatory document for entry to the examination hall. Candidates must carefully verify all details printed on the admit card, including their name, photograph, signature, exam center address, and reporting time. In case of any discrepancy, candidates should immediately contact the university authorities [citation:10].</p>', '2026-05-30', '2026-06-06', 'Various exam centers across Uttar Pradesh (Lucknow, Noida, Varanasi, Agra, etc.)', 'https://abvmucet26.co.in', 'https://abvmucet26.co.in/entrance2026/login?form=2', 'uploads/admit_cards/up_cnet_2026_admit_card.pdf', NULL, '<ul>\r\n<li>Reach the exam center at least 1 hour before the exam time (reporting time is mentioned on the admit card).</li>\r\n<li>Carry a clear printed copy (preferably color) of the UP CNET 2026 admit card on A4 size paper.</li>\r\n<li>Carry at least one valid, original photo ID proof (Aadhar Card, PAN Card, Voter ID, Driving License, or Passport). Xerox copies will not be accepted.</li>\r\n<li>Carry two recent passport-size photographs (same as uploaded on the application form).</li>\r\n<li>Mobile phones, calculators, smartwatches, Bluetooth devices, or any other electronic gadgets are strictly prohibited inside the examination hall.</li>\r\n<li>Candidates must use only a black/blue ballpoint pen to mark answers on the OMR sheet.</li>\r\n<li>Do not forget to get your signature and left thumb impression attested by the invigilator in the designated columns on the admit card.</li>\r\n</ul>', '<ul>\r\n<li>Printed copy of UP CNET 2026 Admit Card.</li>\r\n<li>Original valid photo ID proof (Aadhar Card, Voter ID, Driving License, etc.).</li>\r\n<li>PwD certificate (if applicable under the PwD category).</li>\r\n</ul>', 1, 1, 0, 218, 'UP CNET Admit Card 2026 Out - Download B.Sc Nursing Hall Ticket | ABVMU', 'UP CNET Admit Card 2026 has been released on May 30 by ABVMU. Download your B.Sc Nursing entrance exam hall ticket from the official website abvmucet26.co.in. Check exam date, venue, and instructions.', 'UP CNET Admit Card 2026, UP BSc Nursing Admit Card, UP CNET Hall Ticket 2026, ABVMU Admit Card, UP CNET Exam Date 2026, UP CNET Download Link', '2026-05-30 20:06:05', '2026-07-31 01:29:52'),
(6, 3, 'SSC GD Constable Admit Card 2026 Out', '2026-04-25', 'ssc-gd-constable-admit-card-2026', 'SSC GD Constable 2026 admit card has been released region-wise. Download your CAPFs, Assam Rifles, and SSF exam hall ticket now.', '<p>The Staff Selection Commission (SSC) has released the admit card for the Constable (General Duty) Recruitment Examination 2026 on its official website. The admit card is being issued in a phased manner, typically 2–3 days before each candidate\'s scheduled exam date [citation:3][citation:8]. The SSC GD Constable Computer Based Test (CBT) is scheduled to be conducted in multiple phases across the country [citation:10].</p>\r\n\r\n<p>The recruitment drive aims to fill a total of <strong>25,487 vacancies</strong> for Constable (GD) posts in various Central Armed Police Forces (CAPFs), including the Border Security Force (BSF), Central Industrial Security Force (CISF), Central Reserve Police Force (CRPF), Indo-Tibetan Border Police (ITBP), Sashastra Seema Bal (SSB), Secretariat Security Force (SSF), and Rifleman (GD) in Assam Rifles [citation:3][citation:8].</p>\r\n\r\n<p><strong>Exam Schedule Overview:</strong> The SSC GD 2026 examination is being conducted in four windows [citation:7][citation:8]:</p>\r\n<ul>\r\n<li><strong>Week 1:</strong> April 27, 2026 to May 2, 2026</li>\r\n<li><strong>Week 2:</strong> May 4, 2026 to May 9, 2026</li>\r\n<li><strong>Week 3:</strong> May 18, 2026 to May 23, 2026</li>\r\n<li><strong>Week 4:</strong> May 25, 2026 to May 30, 2026</li>\r\n</ul>\r\n\r\n<p><strong>Important Update:</strong> The exam scheduled for May 28, 2026 has been <strong>preponed to May 27, 2026</strong> due to the Id-u-Zuha (Bakrid) holiday. Candidates are advised to check their admit cards regularly for updates [citation:10].</p>\r\n\r\n<p>The exam city intimation slip was released earlier on <strong>April 19, 2026</strong> to help candidates plan their travel arrangements. However, SSC has clarified that the city slip is not a substitute for the admit card, and candidates will not be allowed to enter the examination hall without the official hall ticket [citation:4][citation:7].</p>\r\n\r\n<p>Candidates must carefully verify all details printed on the admit card, including their name, registration number, photograph, signature, exam date, shift timing, reporting time, and examination centre address. In case of any discrepancy, candidates should immediately contact the concerned SSC regional office [citation:4].</p>', '2026-04-25', '2026-04-27', 'Various exam centers across India (as per regional SSC allocation)', 'https://ssc.gov.in', 'https://ssc.gov.in/admit-card/ssc-gd-constable-2026', 'uploads/admit_cards/ssc_gd_constable_2026_admit_card.pdf', NULL, '<ul>\r\n<li>Candidates must reach the exam center at least 1 hour before the reporting time mentioned on the admit card.</li>\r\n<li>Carry a clear printed copy (preferably on A4 size paper) of the SSC GD Constable 2026 admit card.</li>\r\n<li>Carry at least one valid, original photo ID proof (Aadhaar Card, PAN Card, Voter ID, Driving License, or Passport). Photocopies will not be accepted.</li>\r\n<li>Carry two recent passport-size photographs (same as uploaded in the application form) [citation:3][citation:9].</li>\r\n<li>Mobile phones, calculators, smartwatches, Bluetooth devices, or any other electronic gadgets are strictly prohibited inside the examination hall.</li>\r\n<li>Candidates must ensure that their photograph and signature are clearly visible on the admit card.</li>\r\n<li>Do not forget to get the invigilator\'s signature in the designated column on the admit card.</li>\r\n<li>If any discrepancy is found in the admit card details, contact the SSC regional office immediately before the exam date [citation:4].</li>\r\n<li>Candidates must follow all COVID-19 guidelines and examination rules as specified by SSC.</li>\r\n</ul>', '<ul>\r\n<li>Printed copy of SSC GD Constable 2026 Admit Card (mandatory)</li>\r\n<li>Original valid photo ID proof (Aadhaar Card, Voter ID, PAN Card, Driving License, or Passport)</li>\r\n<li>Two recent passport-size photographs (same as in application form) [citation:3]</li>\r\n<li>PwD certificate (if applicable under the PwD category)</li>\r\n<li>No pen/pencil/paper is allowed inside the exam hall (except for the admit card and ID proof)</li>\r\n</ul>', 0, 1, 0, 158, 'SSC GD Constable Admit Card 2026 Out - Download CAPFs Hall Ticket | ssc.gov.in', 'SSC GD Constable Admit Card 2026 has been released region-wise by Staff Selection Commission. Download your CAPFs, Assam Rifles, and SSF exam hall ticket from ssc.gov.in. Check exam date (April 27 - May 30, 2026), venue, and important instructions.', 'SSC GD Admit Card 2026, SSC GD Constable Hall Ticket 2026, SSC GD Exam Date 2026, SSC GD Constable Admit Card Download, SSC GD Constable 2026, SSC GD CAPFs Admit Card, ssc.gov.in admit card', '2026-05-30 20:08:17', '2026-07-31 01:29:52'),
(7, 4, 'RPSC School Lecturer PGT Admit Card 2026 Out', '2026-05-28', 'rpsc-school-lecturer-pgt-admit-card-2026', 'RPSC 1st Grade Teacher admit card 2026 has been released. Download your School Lecturer (PGT) hall ticket for the exam scheduled from May 31 to June 11, 2026.', '<p>The Rajasthan Public Service Commission (RPSC) has officially released the admit card for the School Lecturer (1st Grade Teacher/PGT) Competitive Examination 2026 on <strong>May 28, 2026</strong> [citation:2][citation:4][citation:5]. Candidates who have applied for the recruitment can now download their hall tickets from the official RPSC websites.</p>\r\n\r\n<p>The recruitment drive aims to fill a total of <strong>3,225 posts</strong> of School Lecturer (PGT) in various subjects, with an additional 121 vacancies for Special Education [citation:1][citation:2][citation:3]. The written examination is scheduled to be conducted across Rajasthan from <strong>May 31, 2026 to June 11, 2026</strong> in two shifts per day [citation:2][citation:3][citation:9].</p>\r\n\r\n<p><strong>Exam Schedule Overview:</strong> The RPSC 1st Grade Teacher exam is subject-wise, divided into Groups A, B, C, and D [citation:3][citation:9]:</p>\r\n<ul>\r\n<li><strong>May 31, 2026:</strong> General Awareness & Hindi</li>\r\n<li><strong>June 1, 2026:</strong> History & English</li>\r\n<li><strong>June 2, 2026:</strong> Commerce & Chemistry</li>\r\n<li><strong>June 3, 2026:</strong> General Awareness & Political Science</li>\r\n<li><strong>June 4, 2026:</strong> Geography & Biology</li>\r\n<li><strong>June 5, 2026:</strong> Sanskrit & Physics/Maths</li>\r\n<li><strong>June 6, 2026:</strong> Sociology & Economics/Music</li>\r\n<li><strong>June 7, 2026:</strong> Drawing & Urdu/Punjabi</li>\r\n<li><strong>June 10, 2026:</strong> Group C (General Studies & Sports Subjects)</li>\r\n<li><strong>June 11, 2026:</strong> Group D (Physical Education)</li>\r\n</ul>\r\n\r\n<p>The admit card contains essential information including candidate details, roll number, exam date, shift timing, reporting time, and examination centre address. Candidates must carefully verify all details on the admit card and report any discrepancies to the RPSC immediately [citation:2][citation:7].</p>\r\n\r\n<p>The exam city intimation slip was released earlier on <strong>May 24, 2026</strong> to help candidates plan their travel arrangements [citation:6].</p>', '2026-05-28', '2026-05-31', 'Various exam centers across Rajasthan (Ajmer, Jaipur, Jodhpur, Udaipur, Kota, etc.)', 'https://rpsc.rajasthan.gov.in', 'https://rpsc.rajasthan.gov.in/admit-card/school-lecturer-2026', 'uploads/admit_cards/rpsc_school_lecturer_2026_admit_card.pdf', NULL, '<ul>\r\n<li>Candidates must reach the exam center at least 60 minutes before the reporting time mentioned on the admit card [citation:7].</li>\r\n<li>Carry a clear printed copy (preferably on A4 size paper) of the RPSC School Lecturer Admit Card 2026.</li>\r\n<li>Carry at least one valid, original photo ID proof (Aadhaar Card, Voter ID, PAN Card, Driving License, or Passport). Photocopies will not be accepted [citation:7].</li>\r\n<li>Carry two recent passport-size photographs (same as uploaded in the application form).</li>\r\n<li>Use only transparent blue/black ballpoint pen for marking answers on the OMR sheet [citation:7].</li>\r\n<li>Mobile phones, smartphones, smartwatches, calculators, and any other electronic gadgets are strictly prohibited inside the examination hall [citation:7][citation:10].</li>\r\n<li>Books, notes, study materials, and bags are not allowed inside the exam center.</li>\r\n<li>No candidate will be allowed to enter the examination hall without a valid admit card and photo ID proof [citation:2][citation:5].</li>\r\n<li>Entry closes strictly before the exam starts; latecomers will not be permitted.</li>\r\n<li>In case of any discrepancy in the admit card, candidates should immediately contact the RPSC helpdesk before the exam date [citation:2].</li>\r\n</ul>', '<ul>\r\n<li>Printed copy of RPSC School Lecturer Admit Card 2026 (mandatory) [citation:5]</li>\r\n<li>Original valid photo ID proof (Aadhaar Card, Voter ID, PAN Card, Driving License, or Passport) [citation:7]</li>\r\n<li>Two recent passport-size photographs (same as in application form) [citation:7]</li>\r\n<li>Transparent blue/black ballpoint pen</li>\r\n<li>PwD certificate (if applicable under the PwD category)</li>\r\n</ul>', 1, 1, 0, 221, 'RPSC School Lecturer PGT Admit Card 2026 Out - Download 1st Grade Teacher Hall Ticket | rpsc.rajasthan.gov.in', 'RPSC School Lecturer (1st Grade Teacher/PGT) Admit Card 2026 has been released on May 28, 2026. Download your hall ticket from rpsc.rajasthan.gov.in. Exam from May 31 to June 11, 2026. Check subject-wise schedule, exam center, and important instructions.', 'RPSC School Lecturer Admit Card 2026, RPSC 1st Grade Teacher Admit Card, RPSC PGT Hall Ticket 2026, RPSC School Lecturer Exam Date 2026, RPSC 1st Grade Admit Card Download, rpsc.rajasthan.gov.in admit card, RPSC School Lecturer 2026', '2026-05-30 20:10:19', '2026-07-31 01:29:52'),
(13, 40, 'UP Police Constable Recruitment 2025 Exam City and Admit Card Details Released', '2026-05-28', 'up-police-constable-recruitment-2025-exam-city-and-admit-card-details-released', 'UP Police Constable Recruitment 2025 exam city details have been released for 32,679 posts. Check your allotted exam city for the written test scheduled on June 8, 9 & 10, 2026.', 'The Uttar Pradesh Police Recruitment and Promotion Board (UPPRPB) has released the exam city details (City Intimation Slip) for the UP Police Constable Recruitment 2025. Candidates who have applied for the 32,679 vacancies of Constable (Civil Police) and equivalent posts can now check their allotted exam city on the official website.\r\n\r\nThe written examination is scheduled to be conducted on  June 8, 9, and 10, 2026 across 1,183 examination centers</strong> in Uttar Pradesh. More than 28 lakh candidates are expected to appear for this recruitment drive.\r\n\r\nWhat is Exam City Slip?\r\nThe Exam City Slip (City Intimation Slip) is a preliminary document released before the main admit card. It informs candidates about the <strong>city or region where their examination center is located. This helps candidates plan their travel and accommodation in advance. The full exam centre address will be mentioned on the main admit card, which will be released separately (expected 7-10 days before the exam).\r\n\r\nImportant Security Measures:\r\nThe UPPRPB has implemented strict security protocols for the examination:\r\n• 100% Aadhaar verification and e-KYC authentication using iris-based biometric systems\r\n• Separate frisking arrangements for women candidates by female police personnel\r\n• Prohibited items: Mobile phones, smartwatches, Meta smart glasses, Bluetooth devices, and other electronic gadgets', '2026-06-05', '2026-06-08', NULL, 'https://uppbpb.gov.in', 'https://uppbpb.gov.in', 'admit-cards/1780428786_up-police-constable-recruitment-2025-exam-city-details-released.pdf', 'admit-cards/1780428786_up-police-constable-recruitment-2025-exam-city-details-released.pdf', 'Aadhaar Verification is Mandatory: All candidates will undergo 100% e-KYC authentication using iris-based biometric systems at the examination centre.\r\nElectronic Items Strictly Prohibited: Mobile phones, smartphones, smartwatches, Meta smart glasses, Bluetooth devices, calculators, and any other electronic gadgets are NOT allowed inside the exam hall.\r\n<li><strong>Dress Code:</strong> Candidates are advised to avoid wearing shoes and socks. As far as possible, arrive in slippers to facilitate smooth security screening.</li>\r\n<li><strong>Religious Symbols Allowed:</strong> Candidates will NOT be required to remove or cut religious symbols (e.g., sacred threads, mangalsutras) during frisking.</li>\r\n<li><strong>Separate Arrangement for Women:</strong> Frisking and verification of women candidates will be carried out exclusively by female police personnel inside designated enclosures.</li>\r\n<li>Reach the exam center at least 1 hour before the reporting time mentioned on the admit card.</li>\r\n<li>Candidates must carry a printed copy of the admit card (to be released later) along with valid photo ID proof.</li>\r\nNo candidate will be allowed to enter the examination hall without a valid admit card and photo ID proof.\r\nEntry closes strictly before the exam starts; latecomers will not be permitted.\r\nUse only blue or black ballpoint pen for marking answers on the OMR sheet.', NULL, 1, 1, 0, 275, 'UP Police Constable Recruitment 2025 Exam City Details - Check City Intimation Slip for 32,679 Posts | UPPRPB', 'UP Police Constable Recruitment 2025 exam city details released by UPPRPB. Check your allotted exam city for 32,679 Constable posts. Written exam on June 8, 9 & 10, 2026. Download city intimation slip from uppbpb.gov.in.', NULL, '2026-06-02 19:24:46', '2026-07-31 01:29:52'),
(15, 45, 'SSC CGL Tier I Exam Admit Card 2026 Out', '2026-07-28', 'ssc-cgl-tier-i-exam-admit-card-2026-out', 'Staff Selection Commission (SSC) has uploaded region-wise Admit Card and City Intimation Slip for CGL Tier-I Examination 2026.', 'SSC CGL Tier-I Admit Card 2026 Released.\n\nCandidates can download their admit card by entering Registration ID / Roll Number and Date of Birth.', '2026-07-28', '2026-08-10', 'Various Exam Centers across India', 'https://ssc.gov.in', 'https://ssc.gov.in/admit-card', NULL, NULL, 'Bring original photo ID proof (Aadhaar Card, Voter ID, or Passport) along with two passport size photographs.', 'Printed Admit Card, Original Photo ID, Ball Point Pen', 1, 0, 0, 4, NULL, NULL, NULL, '2026-07-31 01:28:01', '2026-07-31 01:35:16'),
(16, 44, 'UPSC IAS Prelims Exam Hall Ticket 2026 Download', '2026-07-30', 'upsc-ias-prelims-exam-hall-ticket-2026-download', 'Union Public Service Commission (UPSC) has issued e-Admit Cards for Civil Services (Preliminary) Examination 2026.', 'UPSC Civil Services Prelims 2026 Hall Ticket Available Now.\n\ne-Admit Card can be downloaded from upsconline.nic.in.', '2026-07-30', '2026-08-18', 'All India State Headquarters & District Centers', 'https://upsc.gov.in', 'https://upsconline.nic.in/eadmitcard', NULL, NULL, 'Check all details on e-Admit card carefully. In case of any discrepancy, contact UPSC office immediately.', 'e-Admit Card Printout, Government Photo ID Card', 1, 0, 0, 10, NULL, NULL, NULL, '2026-07-31 01:28:01', '2026-07-31 01:40:58'),
(17, 46, 'RRB NTPC CBT-1 Hall Ticket 2026 Released', '2026-07-29', 'rrb-ntpc-cbt-1-hall-ticket-2026-released', 'Railway Recruitment Boards (RRBs) have made live the CBT-1 Exam City & Admit Card download links.', 'RRB NTPC 2026 CBT-1 Examination Call Letter Download Link Active.', '2026-07-29', '2026-08-15', 'Designated Computer Testing Centers', 'https://indianrailways.gov.in', 'https://rrbapply.gov.in', NULL, NULL, 'Reach exam venue 90 minutes before reporting time.', 'RRB Call Letter, Aadhaar Card / E-Aadhaar', 1, 0, 0, 2, NULL, NULL, NULL, '2026-07-31 01:28:01', '2026-07-31 01:29:52'),
(18, 48, 'UP Police Sub Inspector SI Physical PET Test Admit Card 2026', '2026-07-26', 'up-police-sub-inspector-si-physical-pet-test-admit-card-2026', 'UPPRPB has released the Physical Efficiency Test (PET) hall tickets for UP Police SI Recruitment 2026.', 'UP Police Sub Inspector SI PST / PET Examination Call Letter Released.', '2026-07-26', '2026-08-08', 'UP Police Reserve Lines & Stadiums across UP', 'https://uppbpb.gov.in', 'https://uppbpb.gov.in/si-pet-admit-card', NULL, NULL, 'Physical standards and running test instructions attached with admit card.', 'Printed Hall Ticket, Caste Certificate, Medical Fitness Certificate', 1, 0, 0, 2, NULL, NULL, NULL, '2026-07-31 01:28:01', '2026-07-31 01:29:52'),
(19, 47, 'IBPS PO XV Preliminary Examination Admit Card 2026', '2026-07-27', 'ibps-po-xv-preliminary-examination-admit-card-2026', 'Institute of Banking Personnel Selection (IBPS) has activated online call letter for PO XV Prelims.', 'IBPS PO / MT XV Online Preliminary Exam Call Letter Available for Download.', '2026-07-27', '2026-08-12', 'Authorized Online Examination Venues', 'https://ibps.in', 'https://ibps.in/po-xv-admitcard', NULL, NULL, 'Affix recent passport size photograph on call letter identical to registration photo.', 'IBPS Call Letter, Original ID + Photocopy of ID', 1, 0, 0, 2, NULL, NULL, NULL, '2026-07-31 01:28:01', '2026-07-31 01:29:52'),
(20, 49, 'Bihar Police Constable Written Exam Admit Card 2026', '2026-07-25', 'bihar-police-constable-written-exam-admit-card-2026', 'CSBC Bihar Police Constable Written Exam e-Admit Card & Roll Number List Released.', 'Bihar CSBC Constable Exam Hall Ticket 2026.', '2026-07-25', '2026-08-09', 'District Examination Centers in Bihar', 'https://csbc.bih.nic.in', 'https://csbc.bih.nic.in', NULL, NULL, 'Mobile phones and electronic gadgets are strictly prohibited.', 'e-Admit Card, Original Photo ID', 1, 0, 0, 2, NULL, NULL, NULL, '2026-07-31 01:28:01', '2026-07-31 01:29:52'),
(21, 52, 'UP Police Constable 2026 Admit Card', NULL, 'up-police-constable-2026-admit-card-1785485042', NULL, NULL, '2026-07-31', '2026-08-10', NULL, 'https://uppbpb.gov.in', 'https://uppbpb.gov.in/admitcard', NULL, NULL, NULL, NULL, 1, 0, 0, 0, NULL, NULL, NULL, '2026-07-31 02:34:02', '2026-07-31 02:34:02');

