INSERT INTO `answer_keys` (`id`, `job_id`, `title`, `slug`, `short_description`, `description`, `answer_key_date`, `exam_name`, `exam_date`, `official_website`, `download_link`, `answer_key_url`, `objection_link`, `answer_key_file`, `instructions`, `subjects`, `total_questions`, `total_marks`, `correct_marks`, `negative_marks`, `is_active`, `is_featured`, `download_count`, `views`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) VALUES
(1, 12, 'UPSSSC Stenographer Recruitment 2023 Revised Answer Key 2024 for 277 Post', 'upsssc-stenographer-recruitment-2023-revised-answer-key-2024-for-277-post', 'Uttar Pradesh Subordinate Service Selection Commission (UPSSSC)has released the Stenographer (Steno Hindi) recruitment advertisement for 277 posts. Those candidates who are interested in this UPSSSC Stenographer recruitment can Revised Answer Key 2024. Read the notification for recruitment eligibility, post information, selection procedure, age limit, pay scale and all other information.', 'There are 02 types to apply online for UPSSSC Stenographer (Steno) Recruitment Advt No. 09-Exam/2023 Recruitment 2023.\r\nFirst: In this, the candidate will have to login with his personal information, the information that has to be given is: PET Registration Number, Date of Birth, Gender, Domicile and Category.\r\nSecond : In this, the candidate will have to login through his OTP, the information that has to be given is: UPSSSC PET 2022 Registration Number and OTP Password.\r\nAfter login, the complete information of the candidate, his photo and signature will also be visible, the candidate will have to fill the information related to the post he is asking for and the application fee: Rs.25/- will have to be paid.', '2026-04-01', 'UPSSSC Stenographer Recruitment 2023', NULL, 'https://upsssc.gov.in/Default.aspx', 'https://upsssc.gov.in/ResultsDire.aspx', NULL, NULL, 'answer-keys/1775140258_upsssc-stenographer-recruitment-2023-revised-answer-key-2024-for-277-post.pdf', NULL, NULL, NULL, NULL, 1.00, 0.25, 1, 0, 0, 473, 'UPSSSC Stenographer Recruitment 2023 Revised Answer Key 2024 for 277 Post', 'UPSSSC Stenographer Recruitment 2023 Revised Answer Key 2024 for 277 Post', 'UPSSSC Stenographer Recruitment 2023 Revised Answer Key 2024 for 277 Post', '2026-04-02 09:01:08', '2026-07-31 02:41:09'),
(2, 14, 'RRB NTPC Graduate Level CBT-I Answer Key 2026 – Declared', 'rrb-ntpc-graduate-level-cbt-i-answer-key-2026-declared', 'The RRB NTPC Graduate Level CBT-I Answer Key for CEN No. 06/2025 has been officially released. You can now download the provisional answer key and your response sheet to calculate your probable score.', 'How to Download the Answer Key\r\nFollow these steps to access your response sheet and the official answer key:\r\n\r\nVisit the Portal: Go to the official answer key portal at rrb.digialm.com or your respective regional RRB website .\r\n\r\nFind the Link: Click on the link that says \"CEN 06/2025 (NTPC-Graduate): CBT-I Answer Keys & Objection Tracker\" .\r\n\r\nLog in: Enter your Registration Number and Date of Birth/Password as provided during the application process .\r\n\r\nView and Download: Your recorded responses and the provisional answer key will be displayed on the screen. Download and save the PDF file for future reference', '2026-04-06', 'RRB NTPC Graduate Level CBT-I 2025', '2026-03-16', 'https://rrb.digialm.com/', 'https://rrb.digialm.com/EForms/loginAction.do?subAction=ViewLoginPage&formId=98228&orgId=33128', NULL, NULL, 'answer-keys/1775499365_rrb-ntpc-graduate-level-cbt-i-answer-key-2026-declared.pdf', NULL, NULL, NULL, NULL, 1.00, 0.25, 1, 0, 1, 276, NULL, NULL, NULL, '2026-04-06 12:46:07', '2026-07-31 01:36:27'),
(3, 1, 'UPSC IAS / IFS Pre Answer Key 2026', 'upsc-ias-ifs-pre-answer-key-2026', 'Official and unofficial answer keys for UPSC Civil Services (IAS) & Indian Forest Service (IFS) Preliminary Exam 2026.', 'The UPSC has released the answer key for the IAS/IFS Preliminary Examination 2026. Candidates can download the official answer key along with the question paper booklet series (A, B, C, D) to calculate their expected scores before the final results.', '2026-06-15', 'UPSC IAS/IFS Preliminary Examination', '2026-06-07', 'https://upsc.gov.in', 'https://upsc.gov.in/sites/default/files/AnswerKey-IAS-IFS-Pre-2026.pdf', NULL, NULL, 'answer_keys/upsc_ias_ifs_pre_2026_answer_key.pdf', '1. Download the answer key PDF.\n2. Match your answers with the given key.\n3. Calculate your expected marks.\n4. Raise objections (if any) by the specified deadline.', 'General Studies I, CSAT (General Studies II)', 100, 200, 1.00, 0.25, 1, 1, 0, 115, 'UPSC IAS/IFS Pre Answer Key 2026 - Download Official & Unofficial Keys', 'Download UPSC IAS/IFS Prelims 2026 Answer Key PDF. Check your expected score, compare responses, and raise objections before the final result.', 'UPSC Answer Key 2026, IAS Prelims Answer Key, IFS Pre Answer Key, UPSC CSAT Answer Key, UPSC Prelims Solutions 2026', '2026-05-30 20:15:39', '2026-07-31 01:36:27'),
(4, 1, 'UPSSSC Lekhpal Answer Key 2026 Out', 'upsssc-lekhpal-answer-key-2026', 'Uttar Pradesh Subordinate Services Selection Commission (UPSSSC) has released the Official Answer Key and Objections Link for Lekhpal Mains 2026.', 'UPSSSC Rajasva Lekhpal Answer Key 2026 Released.\n\nCandidates who appeared in the Revenue Lekhpal exam can download the official set-wise answer key and submit online objections till 05 August 2026.', '2026-07-28', 'UPSSSC Revenue Lekhpal Main Examination 2026', '2026-07-15', 'https://upssschep.gov.in', 'https://upssschep.gov.in/answerkey-lekhpal-2026', 'https://upssschep.gov.in/answerkey-lekhpal-2026', 'https://upssschep.gov.in/objection-lekhpal-2026', 'answer_keys/upsssc_lekhpal_2026_answer_key.pdf', 'Compare your response sheet with official key. Objection fee is Rs 100 per question.', 'General Hindi, Mathematics, General Knowledge, Rural Development, Rural Society', 100, 100, 1.00, 0.25, 1, 0, 0, 101, 'UPSSSC Lekhpal Answer Key 2026 - Download Official PDF', 'Download UPSSSC Lekhpal Answer Key 2026 in PDF format. Check correct answers, calculate your expected score, and submit objections online at upsssc.gov.in.', 'UPSSSC Lekhpal Answer Key, Lekhpal Answer Key 2026, UPSSSC Answer Key, Lekhpal Exam Solution, UP Lekhpal Expected Cut Off 2026', '2026-05-30 20:16:19', '2026-07-31 02:05:08'),
(5, 3, 'IIT JEE Advanced Answer Key 2026', 'iit-jee-advanced-answer-key-2026', 'Official provisional and final answer keys for IIT JEE Advanced 2026. Download subject-wise answer keys for Paper 1 and Paper 2.', 'IIT (Indian Institute of Technology) organizing institute releases the official answer key for JEE Advanced 2026. The answer key is published in two phases - Provisional (allowing candidates to raise objections) and Final (after considering valid challenges). Candidates can calculate their estimated marks using the answer key before the results are declared.', '2026-06-10', 'IIT JEE Advanced 2026', '2026-06-07', 'https://jeeadv.ac.in', 'https://jeeadv.ac.in/answer_key_2026.html', NULL, NULL, 'answer_keys/jee_advanced_2026_answer_key.pdf', '1. Download the provisional answer key for Paper 1 and Paper 2.\n2. Download the candidate response sheet from your login.\n3. Compare your answers with the official key.\n4. Calculate your raw score (Physics, Chemistry, Mathematics separately).\n5. If you find any discrepancy, raise an objection online with supporting references (textbooks/standard formulas) before the deadline.\n6. Check the final answer key after objection resolution.\n7. Final result will be based on the final answer key.', 'Physics, Chemistry, Mathematics', 180, 360, 1.00, 0.25, 1, 1, 0, 103, 'IIT JEE Advanced Answer Key 2026 - Official PDF Download | Paper 1 & 2', 'Download IIT JEE Advanced 2026 official answer key for Paper 1 and Paper 2. Check subject-wise solutions for Physics, Chemistry, Mathematics. Calculate your expected score and raise objections online.', 'JEE Advanced Answer Key 2026, IIT JEE Answer Key, JEE Advanced Paper 1 Solutions, JEE Advanced Paper 2 Solutions, JEE Advanced 2026 Response Sheet, JEE Advanced Cut Off 2026', '2026-05-30 20:17:32', '2026-07-31 01:36:27'),
(6, 4, 'Indian Navy Civilian INCET 01/2025 Answer Key', 'indian-navy-civilian-incet-01-2025-answer-key', 'Provisional answer key for Indian Navy Civilian Entrance Test (INCET) 01/2025. Download answer key PDF, response sheet, and raise objections online.', 'The Indian Navy has released the provisional answer key for the Civilian Entrance Test (INCET) 01/2025 recruitment examination for various Group B and Group C civilian posts including Chargeman, Tradesman Mate, Fireman, Driver, and others under the Ministry of Defence. Candidates can download the answer key, master question paper, and response sheet from the official website. The challenge mechanism portal allows candidates to raise objections against the provisional answer key from May 29 to June 11, 2026. All objections will be reviewed by a panel of subject matter experts, and the final answer key will be published after considering valid challenges. The recruitment drive aims to fill over 1400+ vacancies across multiple civilian posts in the Indian Navy.', '2026-05-29', 'Indian Navy Civilian Entrance Test (INCET) 01/2025', '2025-09-03', 'https://joinindiannavy.gov.in', 'https://joinindiannavy.gov.in/civilian/incet-01-2025/answer-key', NULL, NULL, 'answer_keys/indian_navy_incet_01_2025_answer_key.pdf', '1. Visit the official website joinindiannavy.gov.in\n2. Navigate to Join Navy > Ways to Join > Civilians > INCET-01/2025 section\n3. Download the provisional answer key PDF and master question paper\n4. Download your response sheet using login credentials (Registration ID and Password/DOB)\n5. Compare your answers with the official answer key to calculate expected score\n6. To raise an objection: Log in, click \"Answer Key Challenge\" link, select question number and answer to challenge\n7. Upload supporting documents or proof for each challenge\n8. Pay Rs. 100 per objection (fee refunded for valid objections after bank charge deduction)\n9. Submit objections before the deadline - No offline/email objections accepted\n10. Check the official website for final answer key and result announcements', 'General Awareness, Reasoning, Quantitative Aptitude, English, Technical Subjects (post-specific)', 100, 100, 1.00, 0.25, 1, 1, 0, 101, 'Indian Navy INCET 01/2025 Answer Key 2026 - Download Provisional Answer Key PDF', 'Download Indian Navy Civilian INCET 01/2025 provisional answer key PDF. Check response sheet, calculate expected score, and raise objections online from May 29 to June 11, 2026 at joinindiannavy.gov.in.', 'Indian Navy INCET Answer Key, INCET 01/2025 Answer Key, Indian Navy Civilian Answer Key, INCET Response Sheet, Navy Chargeman Answer Key, INCET Objection Process 2026', '2026-05-30 20:19:14', '2026-07-31 01:36:27'),
(7, 1, 'SSC CGL Tier-I Official Answer Key & Response Sheet 2026', 'ssc-cgl-tier-i-official-answer-key-response-sheet-2026', 'Staff Selection Commission (SSC) has uploaded Tentative Answer Keys along with candidates Response Sheet for CGL 2026.', 'SSC CGL 2026 Tier-1 Tentative Answer Keys and Response Sheet released.', '2026-07-30', 'SSC Combined Graduate Level Tier-I Examination 2026', '2026-07-20', 'https://ssc.gov.in', 'https://ssc.gov.in/challenge-system', 'https://ssc.gov.in/challenge-system-cgl2026', 'https://ssc.gov.in/challenge-system-cgl2026', NULL, 'Log in using User ID (Roll Number) and Password as per Admission Certificate.', NULL, 100, 200, 2.00, 0.50, 1, 0, 0, 6, NULL, NULL, NULL, '2026-07-31 01:40:17', '2026-07-31 02:42:08'),
(8, 1, 'UP Police Constable Written Exam Answer Key 2026', 'up-police-constable-written-exam-answer-key-2026', 'UPPRPB has released the Official Master Answer Key for UP Police Constable Examination 2026.', 'UP Police Constable Exam Answer Key 2026 Available for Download.', '2026-07-26', 'UP Police Constable Direct Recruitment Exam 2026', '2026-07-10', 'https://uppbpb.gov.in', 'https://uppbpb.gov.in/answerkey', 'https://uppbpb.gov.in/answerkey-constable-2026', 'https://uppbpb.gov.in/objections-2026', NULL, 'Raise objections through UPPRPB online objection tracking portal.', NULL, 150, 300, 2.00, 0.50, 1, 0, 0, 0, NULL, NULL, NULL, '2026-07-31 01:40:17', '2026-07-31 02:00:11'),
(9, 1, 'NTA NEET UG Official Answer Key & OMR Sheet 2026', 'nta-neet-ug-official-answer-key-omr-sheet-2026', 'National Testing Agency (NTA) has displayed the Provisional Answer Key and Scanned Images of OMR Answer Sheet for NEET (UG) 2026.', 'NEET UG 2026 Official Provisional Answer Key released by NTA.', '2026-07-25', 'National Eligibility cum Entrance Test (NEET-UG) 2026', '2026-07-05', 'https://neet.nta.nic.in', 'https://neet.nta.nic.in', 'https://neet.nta.nic.in/answerkey-2026', 'https://neet.nta.nic.in/challenge-omr-2026', NULL, 'Provisional answer key challenge fee Rs 200 per question (non-refundable).', NULL, 200, 720, 4.00, 1.00, 1, 0, 0, 0, NULL, NULL, NULL, '2026-07-31 01:40:17', '2026-07-31 02:00:11'),
(11, 52, 'NEET UG 2026 Official Answer Key', 'neet-ug-2026-official-answer-key-1785485042', NULL, NULL, '2026-07-31', NULL, NULL, 'https://neet.nta.nic.in', 'https://neet.nta.nic.in/answerkey', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1.00, 0.25, 1, 0, 0, 0, NULL, NULL, NULL, '2026-07-31 02:34:02', '2026-07-31 02:34:02');

