) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Triggers `blog_views`
--
DELIMITER $$
CREATE TRIGGER `add_daily_analytics` AFTER INSERT ON `blog_views` FOR EACH ROW BEGIN
    INSERT INTO blog_analytics (blog_id, date, views, unique_visitors) 
    VALUES (NEW.blog_id, CURDATE(), 1, 1)
    ON DUPLICATE KEY UPDATE 
        views = views + 1,
        unique_visitors = unique_visitors + 
            (SELECT COUNT(DISTINCT ip_address) 
             FROM blog_views 
             WHERE blog_id = NEW.blog_id 
             AND DATE(viewed_at) = CURDATE());
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `update_blog_view_count` AFTER INSERT ON `blog_views` FOR EACH ROW BEGIN
    UPDATE blogs 
    SET views = views + 1 
    WHERE id = NEW.blog_id;
END
$$
DELIMITER ;

