INSERT INTO `categories` (`id`, `name`, `slug`, `description`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Uttar Pradesh', 'uttar-pradesh', 'The Government of Uttar Pradesh comprises over 50 major administrative and executive departments that work towards the state\'s development, law and order, and public welfare. These include key departments such as Agriculture, Basic Education, Police, Health, Housing, and the Public Works Department (PWD). These departments are overseen by various Cabinet Ministers.', 1, '2026-04-01 06:13:55', '2026-04-01 13:15:04'),
(2, 'Railway', 'railway', 'The Railway Recruitment Board (RRB) is a government organisation under the Ministry of Railways, Government of India. RRB publishes the Railway Jobs to recruit candidates for various Group C and Group D posts in Indian Railways. RRB NTPC, RRB Group D, RRB ALP, RRB JE, RRB Technician, etc., are some exams conducted by the Railway Recruitment Board.', 1, '2026-04-01 13:06:07', '2026-04-01 13:06:07'),
(3, 'SSC', 'ssc', 'SSC Combined Graduate Level Examination (CGLE) is one of the sought-after exams in India conducted by SSC for the recruitment of Grade “B” and “C” category posts in various organisations, departments, and offices under the Government of India.', 1, '2026-04-01 13:09:33', '2026-04-01 13:09:33'),
(4, 'UPSC', 'upsc', 'UPSC (Union Public Service Commission) recruits for top-level Group \'A\' and \'B\' government jobs in India through examinations like Civil Services (CSE), Engineering Services (IES), and Combined Defence Services (CDS). Key posts include IAS, IPS, IFS (Foreign), IRS, and specialized roles in ministries', 1, '2026-04-01 13:11:06', '2026-04-01 13:11:06'),
(5, 'BIHAR', 'bihar', 'Bihar\'s main job opportunities are in government (BPSC, BSSC, police, teachers) and private sectors (hospitality, administration, sales). Openings in 2026 are for civil judge, APO, police constable operator, and non-teaching positions. Key sectors in the state include health, education, mining (gold in Jamui), and the police department.', 1, '2026-04-01 23:09:14', '2026-04-01 23:09:14'),
(6, 'Jobs', 'jobs', NULL, 1, '2026-04-01 23:12:07', '2026-04-01 23:12:07'),
(7, 'Defence Job', 'defence-job', 'Defence jobs in India (2026) offer stable careers in the Indian Army, Navy, Air Force, and Coast Guard, with recruitment for roles like Agniveer, Tradesman, Commissioned Officers, and Civilian staff (MTS, Technical) via UPSC, AFCAT, and specialized rallies.', 1, '2026-04-02 00:34:22', '2026-04-02 00:34:22'),
(8, 'Delhi', 'delhi', NULL, 1, '2026-04-02 08:16:27', '2026-04-02 08:16:27'),
(9, 'Other', 'other', 'Other Categories like, NCL NPCL, BPCL, HAL, ISRO, DRDO', 1, '2026-04-18 23:53:38', '2026-04-18 23:53:38'),
