(5, 'BPSC Exam Calendar 2026', 'bpsc-exam-calendar-2026-1775931989', NULL, 'Bihar Public Service Commission BPSC, As per the latest official update, the Bihar Public Service Commission (BPSC) has released the Exam Calendar for 2025–2026.', NULL, 'notice', 'Exam Calendar', 'documents/notice/1775931989_bpsc-exam-calendar-2026.pdf', 'Examination-Calendar-02.02.2026.pdf', '141443', 'application/pdf', '2026-02-02', NULL, 1, 1, 205, 194, 'BPSC', 'BPSC', 'hindi', 0, '2026-04-11 12:56:29', '2026-07-28 01:42:20', NULL),
(6, 'Railway RRB NTPC 10+2 UnderGraduate 12th Level', 'railway-rrb-ntpc-102-undergraduate-12th-level-1776098906', NULL, 'NOTICE REGARDING TENTATIVE SCHEDULE OF COMPUTER BASED TEST (CBT-I) FOR THE POSTs\r\nOF NON-TECHNICAL POPULAR CATEGORIES (UNDER GRADUATE)', NULL, 'notice', 'Exam Date', 'documents/notice/1776098906_railway-rrb-ntpc-102-undergraduate-12th-level.pdf', 'CEN-07-2025-Tentative-Schedule-Eng-1.pdf', '573985', 'application/pdf', '2026-04-13', NULL, 1, 1, 153, 194, 'Railway', 'Railway', 'english', 0, '2026-04-13 11:18:26', '2026-07-27 15:30:04', NULL),
(7, 'UPSSSC UP Sachivalaya Vidhan Bhavan Guard and Vidhan Bhavan Fireman/Fire Guard Recruitment 2026', 'upsssc-up-sachivalaya-vidhan-bhavan-guard-and-vidhan-bhavan-firemanfire-guard-recruitment-2026-1776581238', NULL, 'UPSSSC Vidhan Bhavan Guard and Vidhan Bhavan Fireman/Fire Guard Vacancy 2026 can Apply Online from 09/06/2026 to 29/06/2026.', NULL, 'syllabus', 'UPSSSC UP Syllabus', 'documents/syllabus/1776581237_upsssc-up-sachivalaya-vidhan-bhavan-guard-and-vidhan-bhavan-firemanfire-guard-recruitment-2026.pdf', 'sarkariresult.com_UP_VidhabBhawan_Guard_Fireman_Syllabus_2026-compressed.pdf', '697106', 'application/pdf', '2026-04-17', NULL, 1, 1, 186, 384, 'UPSSSC UP', 'UPSSSC UP', 'english', 0, '2026-04-19 01:17:18', '2026-07-31 01:25:42', NULL),
(8, 'UPPSC Exam Calendar 2026', 'uppsc-exam-calendar-2026', 'UPPSC/CAL/2026/01', 'Official examination schedule for UPPSC 2026', 'The Uttar Pradesh Public Service Commission (UPPSC) has released the annual exam calendar for the year 2026. This document includes preliminary, main, and interview schedules for all upcoming recruitment examinations including PCS, ACF/RFO, and other state government posts.', 'notice', 'exam-schedule', 'uploads/documents/uppsc/2026/', 'UPPSC_Exam_Calendar_2026.pdf', '2457600', 'application/pdf', '2025-12-15', '2026-12-31', 1, 1, 37, 56, 'UPPSC', 'Secretary, UPPSC', 'en', 10, '2026-05-30 20:22:23', '2026-07-27 15:30:04', NULL),
(9, 'SSC Exam Calendar 2026-27', 'ssc-exam-calendar-2026-27', 'SSC/CAL/2026-27/001', 'Official examination schedule for SSC 2026-27 session', 'The Staff Selection Commission (SSC) has released the annual exam calendar for the academic session 2026-27. This document includes the schedule for all major examinations including CGL, CHSL, MTS, GD Constable, JE, Stenographer, CPO, and other departmental exams along with notification release dates, application deadlines, exam tiers, and result declaration timelines.', 'certificate', 'exam-schedule', 'uploads/documents/ssc/2026/', 'SSC_Exam_Calendar_2026-27.pdf', '3250000', 'application/pdf', '2025-12-20', '2027-12-31', 1, 1, 48, 63, 'SSC', 'Chairman, Staff Selection Commission', 'en', 5, '2026-05-30 20:28:17', '2026-07-27 15:30:04', NULL);

