(1, 'UPSSSC UP Combined Lower Subordinate Services (Graduate Level) Recruitment 2026', 'upsssc-up-combined-lower-subordinate-services-graduate-level-recruitment-2026', 1, 'UPSSSC has announced the Combined Lower Subordinate Services (Graduate Level) Exam 2026 (Advt. No. 07-Exam/2026). Get complete details for 2,285 vacancies including UPSSSC PET score requirement, age limit 18-40 years, and application fee of Rs. 25/-. Apply online from 29 May to 18 June 2026.', '<h2>UPSSSC Lower PCS (Graduate Level) Recruitment 2026</h2>\r\n<p><strong>Uttar Pradesh Subordinate Service Selection Commission (UPSSSC)</strong> has released the official notification for the <strong>UP Combined Lower Subordinate Services (Graduate Level) Examination 2026</strong> (Advt. No. 07-Exam/2026). This is a prestigious recruitment drive for graduate candidates seeking government jobs in Uttar Pradesh.</p>\r\n\r\n<h3>Important Dates</h3>\r\n<ul>\r\n<li><strong>Application Start Date:</strong> 29 May 2026</li>\r\n<li><strong>Last Date to Apply Online:</strong> 18 June 2026</li>\r\n<li><strong>Last Date for Fee Payment:</strong> 18 June 2026</li>\r\n<li><strong>Exam Date:</strong> As per schedule (to be announced)</li>\r\n</ul>\r\n\r\n<h3>Application Fee</h3>\r\n<ul>\r\n<li><strong>General / OBC / EWS:</strong> Rs. 25/-</li>\r\n<li><strong>SC / ST:</strong> Rs. 25/-</li>\r\n<li><strong>Payment Mode:</strong> Online (Debit Card, Credit Card, Net Banking)</li>\r\n</ul>\r\n\r\n<h3>Age Limit (as on 01/07/2026)</h3>\r\n<ul>\r\n<li><strong>Minimum Age:</strong> 18 Years</li>\r\n<li><strong>Maximum Age:</strong> 40 Years</li>\r\n<li><strong>Age Relaxation:</strong> As per UPSSSC rules.</li>\r\n</ul>\r\n\r\n<h3>Eligibility Criteria</h3>\r\n<p>Candidates must possess a valid <strong>UPSSSC PET 2025 Score Card</strong>. Educational qualification includes a Bachelor\'s Degree (Graduation) in any stream from a recognized university. For the Executive Officer post, candidates require Graduation with an \'O\' Level certificate. Please refer to the official notification for post-wise eligibility details.</p>\r\n\r\n<h3>Vacancy Details</h3>\r\n<p><strong>Total Posts:</strong> 2,285</p>\r\n<p><strong>Job Location:</strong> Uttar Pradesh</p>\r\n\r\n<h3>Selection Process</h3>\r\n<p>The selection will be based on the Written Examination (Preliminary & Mains), followed by Document Verification and Medical Examination.</p>\r\n\r\n<h3>How to Apply for UPSSSC Lower PCS 2026</h3>\r\n<p>Candidates can apply online from 29 May 2026 through the official UPSSSC website. Keep your PET scorecard, educational certificates, and photograph ready before applying.</p>\r\n\r\n<p><strong>Important Links:</strong><br />\r\n<a href=\"https://upsssc.gov.in//default.aspx\" target=\"_blank\" rel=\"noopener\">Apply Online</a><br />\r\n<a href=\"notifications/1775045295_upsssc-up-combined-lower-subordinate-services-graduate-level-recruitment-2026.pdf\" target=\"_blank\" rel=\"noopener\">Download Notification PDF</a><br />\r\n<a href=\"https://upsssc.gov.in/\" target=\"_blank\" rel=\"noopener\">Official Website</a></p>\r\n\r\n<p><strong>Tags:</strong> UPSSSC Lower PCS 2026, UP Graduate Level Recruitment, Sarkari Result, UP Govt Jobs 2026</p>', NULL, '2026-05-29', '2026-06-18', '2026-06-18', NULL, NULL, NULL, NULL, '2026-07-01', '₹ 25/-', '₹ 25/-', NULL, 'Online (Debit Card, Credit Card, Net Banking)', 25.00, '18 Years', '40 Years', 'As per UPSSSC rules', '18-40', '2285', 'Uttar Pradesh', 'UPSSSC PET 2025 Score Card, Bachelor Degree in Any Stream from Any Recognized University. For Executive Officer: Graduation with O Level Certificate', NULL, NULL, 'Written Examination (Preliminary & Mains), Document Verification, Medical Examination', 'Apply online through official UPSSSC website from 29 May 2026. Keep PET scorecard, educational certificates, and photograph ready.', 'https://upsssc.gov.in//default.aspx', NULL, NULL, NULL, NULL, NULL, NULL, 'https://upsssc.gov.in/', 'notifications/1775045295_upsssc-up-combined-lower-subordinate-services-graduate-level-recruitment-2026.pdf', NULL, NULL, 'UPSSSC Lower PCS 2026 Recruitment', 'UPSSSC Combined Lower Subordinate Services Graduate Level Recruitment 2026 for 2285 posts', 'UPSSSC, Lower PCS, Graduate Level, UP Government Jobs', 1, 1, 318, '2026-04-01 01:08:20', '2026-07-10 03:09:34'),
(2, 'Patna High Court PHC Technical Assistant TA Recruitment 2026 Apply Online for 53 Post', 'patna-high-court-phc-technical-assistant-ta-recruitment-2026-apply-online-for-53-post', 5, 'Patna High Court (PHC) invites online applications for 53 posts of Technical Assistant (TA). Graduates with BCA, ITI, or Diploma in CS/ECE can apply. The application window is open from 01 April to 30 April 2026. Check eligibility, fee (Rs. 1100/-), and age limit (18-37) before applying.', '<h2>Patna High Court Technical Assistant (TA) Recruitment 2026</h2>\r\n<p>The <strong>Patna High Court (PHC)</strong> has released the official notification for the recruitment of <strong>Technical Assistants (TA)</strong> on a contract basis. This is a golden opportunity for ITI, Diploma, and BCA pass candidates looking for government jobs in the Bihar judiciary.</p>\r\n\r\n<h3>Important Dates</h3>\r\n<ul>\r\n<li><strong>Online Application Start:</strong> 01 April 2026</li>\r\n<li><strong>Last Date to Apply:</strong> 30 April 2026</li>\r\n<li><strong>Last Date for Fee Payment:</strong> 30 April 2026</li>\r\n<li><strong>Admit Card Release:</strong> To be notified</li>\r\n</ul>\r\n\r\n<h3>Application Fee</h3>\r\n<ul>\r\n<li><strong>General / OBC / EWS:</strong> Rs. 1,100/-</li>\r\n<li><strong>SC / ST / PwD:</strong> Rs. 550/- (as per state rules)</li>\r\n<li><strong>Payment Mode:</strong> Online</li>\r\n</ul>\r\n\r\n<h3>Age Limit (as on 01/01/2026)</h3>\r\n<ul>\r\n<li><strong>Minimum Age:</strong> 18 Years</li>\r\n<li><strong>Maximum Age:</strong> 37 Years (Male & Female)</li>\r\n<li><strong>Age Relaxation:</strong> As per Bihar Government norms.</li>\r\n</ul>\r\n\r\n<h3>Eligibility & Qualification</h3>\r\n<p>Candidates must possess <strong>BCA / ITI / Diploma in Computer Science & Engineering / Electronics & Telecommunication / Electronics & Communication</strong> from a recognized institute. At least 1 year of relevant experience is required. Please read the notification for complete technical qualification details.</p>\r\n\r\n<h3>Vacancy Details</h3>\r\n<ul>\r\n<li><strong>Total Posts:</strong> 53</li>\r\n<li><strong>Post Name:</strong> Technical Assistant (TA)</li>\r\n<li><strong>Job Location:</strong> Bihar (Patna High Court & District Courts)</li>\r\n</ul>\r\n\r\n<h3>Selection Process</h3>\r\n<p>Selection will be based on a Written Examination (Objective Type) followed by a Practical/Trade Test and Document Verification.</p>\r\n\r\n<h3>How to Apply</h3>\r\n<p>Eligible candidates can apply online through the official PHC recruitment portal from 01 April to 30 April 2026. Ensure you have scanned copies of your photo, signature, educational certificates, and experience proof ready.</p>\r\n\r\n<p><strong>Important Links:</strong><br />\r\n<a href=\"https://phc-recruitment.com/\" target=\"_blank\" rel=\"noopener\">Apply Online</a><br />\r\n<a href=\"notifications/1775109629_patna-high-court-phc-technical-assistant-ta-recruitment-2026-apply-online-for-53-post.pdf\" target=\"_blank\" rel=\"noopener\">Download Official Notification</a><br />\r\n<a href=\"https://phc-recruitment.com/\" target=\"_blank\" rel=\"noopener\">Official Website</a></p>', NULL, '2026-04-02', '2026-04-30', '2026-04-30', NULL, NULL, NULL, NULL, '2026-01-01', 'Rs. 1,100/-', 'Rs. 550/-', NULL, 'Online', 1100.00, '18 Years', '37 Years', 'As per Bihar Government norms', '18-37', '53', 'Bihar', 'BCA / ITI / Diploma in Computer Science & Engineering / Electronics & Telecommunication / Electronics & Communication', NULL, '1 Year Experience Required', 'Written Examination (Objective Type), Practical/Trade Test, Document Verification', 'Apply online through official PHC recruitment portal from 01 April to 30 April 2026. Keep scanned copies of photo, signature, certificates, and experience proof ready.', 'https://phc-recruitment.com/', NULL, NULL, NULL, NULL, NULL, NULL, 'https://phc-recruitment.com/', 'notifications/1775109629_patna-high-court-phc-technical-assistant-ta-recruitment-2026-apply-online-for-53-post.pdf', NULL, NULL, 'Patna High Court Technical Assistant Recruitment 2026', 'PHC Technical Assistant TA Recruitment 2026 for 53 posts. Apply online from 01 April to 30 April 2026', 'Patna High Court, Technical Assistant, TA, Bihar Jobs', 1, 0, 205, '2026-04-01 19:00:31', '2026-07-12 15:19:45'),
(3, 'Indian Navy MR Musician 02/2026 Apply Online Form | Sarkari Result', 'indian-navy-mr-musician-022026-apply-online-form-sarkari-result', 7, 'Join Indian Navy as Agniveer MR (Musician) under 02/2026 Batch. Apply online from 11 April to 26 April 2026. No application fee. Class 10th pass with 50% marks required. Check age criteria (01/07/2004 to 31/12/2008) and physical standards.', '<h2>Indian Navy MR (Musician) Agniveer 02/2026 Batch Recruitment 2026</h2>\r\n<p>The <strong>Indian Navy</strong> has released the official notification for the <strong>Agniveer MR (Musician) 02/2026 Batch</strong> under the Agnipath Scheme. Unmarried male candidates with a passion for music and a Class 10th qualification can apply online from April 2026.</p>\r\n\r\n<h3>Important Dates</h3>\r\n<ul>\r\n<li><strong>Application Start Date:</strong> 11 April 2026</li>\r\n<li><strong>Last Date to Apply Online:</strong> 26 April 2026</li>\r\n<li><strong>Exam / Rally Date:</strong> Will be informed later</li>\r\n</ul>\r\n\r\n<h3>Application Fee</h3>\r\n<p><strong>NIL (No application fee)</strong> for all candidates as per Indian Navy recruitment rules.</p>\r\n\r\n<h3>Age Limit</h3>\r\n<p>Candidates must be born between <strong>01 July 2004 to 31 December 2008</strong> (Both dates inclusive).</p>\r\n\r\n<h3>Eligibility Criteria</h3>\r\n<ul>\r\n<li><strong>Educational Qualification:</strong> Class 10th (High School) Exam Passed with minimum <strong>50% marks</strong> from a recognized board.</li>\r\n<li><strong>Musical Ability:</strong> Must have proficiency in instrumental music (specific instruments as per Navy requirements).</li>\r\n</ul>\r\n\r\n<h3>Physical Standards (Male)</h3>\r\n<ul>\r\n<li><strong>1.6 KM Run:</strong> Within 6 Minutes 30 Seconds</li>\r\n<li><strong>Squats (Uthak Baithak):</strong> 20 Times</li>\r\n<li><strong>Push-ups:</strong> 12 Times</li>\r\n<li><strong>Bent Knee Sit-ups:</strong> 15 Times</li>\r\n<li><strong>Chest Expansion:</strong> Minimum 5 CMS</li>\r\n</ul>\r\n\r\n<h3>Selection Process</h3>\r\n<p>Candidates will be selected based on Shortlisting, Physical Fitness Test (PFT), Written Examination, and Medical Examination.</p>\r\n\r\n<h3>How to Apply</h3>\r\n<p>Apply online through the official Join Indian Navy website (<a href=\"https://www.joinindiannavy.gov.in/\" target=\"_blank\">joinindiannavy.gov.in</a>) between 11 April and 26 April 2026.</p>\r\n\r\n<p><strong>Important Links:</strong><br />\r\n<a href=\"https://www.joinindiannavy.gov.in/en/account/account/state\" target=\"_blank\" rel=\"noopener\">Apply Online</a><br />\r\n<a href=\"notifications/1775110202_indian-navy-mr-musician-022026-apply-online-form-sarkari-result.pdf\" target=\"_blank\" rel=\"noopener\">Download Notification PDF</a><br />\r\n<a href=\"https://www.joinindiannavy.gov.in/\" target=\"_blank\" rel=\"noopener\">Official Website</a></p>', NULL, '2026-04-11', '2026-04-26', NULL, NULL, NULL, NULL, NULL, NULL, '₹ 0/- (No Fee)', '₹ 0/- (No Fee)', NULL, 'N/A', 0.00, '17.5 Years', '21 Years', 'As per Indian Navy rules', '01/07/2004 to 31/12/2008', NULL, 'All India', 'Class 10th (High School) Exam Passed with minimum 50% marks from a recognized board', NULL, 'Proficiency in instrumental music', 'Shortlisting, Physical Fitness Test (PFT), Written Examination, Medical Examination', 'Apply online through official Join Indian Navy website', 'https://www.joinindiannavy.gov.in/en/account/account/state', NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.joinindiannavy.gov.in/', 'notifications/1775110202_indian-navy-mr-musician-022026-apply-online-form-sarkari-result.pdf', NULL, NULL, 'Indian Navy MR Musician Recruitment 2026', 'Join Indian Navy as Agniveer MR Musician 02/2026 Batch. Apply online from 11 April to 26 April 2026', 'Indian Navy, Agniveer, MR Musician, Navy Recruitment', 1, 1, 220, '2026-04-01 19:10:02', '2026-07-12 15:19:45'),
(4, 'Indian Army Rally Recruitment Agniveer, ARO, ZRO, Agniveer Women, Sepoy Pharma, Soldier Technical 2027 Apply Online Form 2026', 'indian-army-rally-recruitment-agniveer-aro-zro-agniveer-women-sepoy-pharma-soldier-technical-2027-apply-online-form-2026', 7, 'Indian Army Rally Recruitment 2027 for Agniveer (GD, Technical, Tradesman), Soldier Technical, Sepoy Pharma, and JCO Religious Teacher. Apply online from 02 April 2026 to 10 April 2027. Check post-wise eligibility, age limit, and physical standards.', '<h2>Indian Army Rally Recruitment 2026-27 (Agniveer & Other Posts)</h2>\r\n<p>The <strong>Join Indian Army</strong> has announced Rally Recruitment for the year 2027. This drive includes vacancies for <strong>Agniveer (General Duty, Technical, Tradesman), Soldier Technical Nursing Assistant, Sepoy Pharma, and JCO Religious Teacher</strong>. Candidates from all over India can apply online.</p>\r\n\r\n<h3>Important Dates</h3>\r\n<ul>\r\n<li><strong>Online Application Start:</strong> 02 April 2026</li>\r\n<li><strong>Last Date to Apply:</strong> 10 April 2027</li>\r\n<li><strong>Rally Exam Date:</strong> 01 July 2026 onwards (varies by zone)</li>\r\n</ul>\r\n\r\n<h3>Post-Wise Age Limit (as on 01/07/2027)</h3>\r\n<ul>\r\n<li><strong>Agniveer (GD/Technical/Tradesman):</strong> 17.5 to 22 Years (Born: 01/07/2005 to 01/07/2009)</li>\r\n<li><strong>Soldier Technical:</strong> 17.5 to 23 Years (Born: 01/07/2004 to 01/07/2009)</li>\r\n<li><strong>Sepoy Pharma:</strong> 19 to 25 Years (Born: 01/07/2002 to 01/07/2008)</li>\r\n<li><strong>JCO Religious Teacher:</strong> 25 to 34 Years (Born: On/after 01/07/2027)</li>\r\n</ul>\r\n\r\n<h3>Application Fee</h3>\r\n<p><strong>NIL</strong> (No application fee for Indian Army Recruitment).</p>\r\n\r\n<h3>Educational Qualification (Post Wise)</h3>\r\n<ul>\r\n<li><strong>Agniveer GD:</strong> Class 10th Matric with 45% marks and 33% in each subject.</li>\r\n<li><strong>Agniveer Technical:</strong> 10+2 with Science (PCM) with 50% marks.</li>\r\n<li><strong>Soldier Technical Nursing Assistant:</strong> 10+2 with Science (PCB/PCM) with 50% marks.</li>\r\n<li><strong>Sepoy Pharma:</strong> 10+2 + D.Pharma with 55% marks (or B.Pharma with 50%).</li>\r\n<li><strong>JCO Religious Teacher:</strong> Shastri / Acharya / Graduation with relevant religious qualification.</li>\r\n</ul>\r\n\r\n<h3>Physical Standards (Group I)</h3>\r\n<ul>\r\n<li><strong>Height:</strong> 169 CM to 170 CM (varies by region/post)</li>\r\n<li><strong>1.6 KM Run:</strong> 5 Min 30 Sec to 5 Min 45 Sec</li>\r\n<li><strong>Pull Ups:</strong> 10 Times</li>\r\n<li><strong>9 Feet Ditch & Zigzag Balance:</strong> Mandatory</li>\r\n</ul>\r\n\r\n<h3>How to Apply</h3>\r\n<p>Interested candidates must apply online through the official Indian Army website <a href=\"https://joinindianarmy.nic.in\" target=\"_blank\">joinindianarmy.nic.in</a>. No offline application is accepted.</p>\r\n\r\n<p><strong>Important Links:</strong><br />\r\n<a href=\"https://joinindianarmy.nic.in/Authentication.aspx\" target=\"_blank\" rel=\"noopener\">Apply Online (Indian Army)</a><br />\r\n<a href=\"https://joinindianarmy.nic.in/\" target=\"_blank\" rel=\"noopener\">Official Website</a></p>', NULL, '2026-04-02', '2026-04-10', NULL, NULL, '2026-07-01', NULL, NULL, '2027-07-01', '₹ 0/- (No Fee)', '₹ 0/- (No Fee)', NULL, 'N/A', 0.00, '17.5 Years', '22 Years', 'As per Indian Army rules', '17.5 to 22 Years (Post Wise)', NULL, 'All India', 'Class 8th, 10th, 12th Post Wise Eligibility', NULL, NULL, 'Rally, Physical Fitness Test, Written Examination, Medical Examination', 'Apply online through official Indian Army website joinindianarmy.nic.in. No offline application accepted.', 'https://joinindianarmy.nic.in/Authentication.aspx', NULL, NULL, NULL, NULL, NULL, NULL, 'https://joinindianarmy.nic.in/', NULL, NULL, NULL, 'Indian Army Rally Recruitment 2026-27', 'Join Indian Army Rally Recruitment for Agniveer, Soldier Technical, Sepoy Pharma posts. Apply online from 02 April 2026', 'Indian Army, Agniveer, Rally Recruitment, Defence Jobs', 1, 0, 139, '2026-04-01 19:25:48', '2026-07-12 15:19:43'),
(5, 'Central Railway RRC CR Various Trade Apprentices 2026 Apply Online for 51 Post', 'central-railway-rrc-cr-various-trade-apprentices-2026-apply-online-for-51-post', 2, 'Central Railway (RRC CR) invites online applications for 51 Trade Apprentice posts. ITI pass candidates (50% marks) in relevant trades can apply. Application fee Rs. 100/-. Age limit 15-24 years. Last date to apply is 09 April 2026.', '<h2>Central Railway (RRC CR) Trade Apprentices Recruitment 2026</h2>\r\n<p>Railway Recruitment Cell, <strong>Central Railway (RRC CR)</strong> has released notification for engagement of <strong>Trade Apprentices</strong> under the Apprentices Act, 1961. Candidates with ITI certification can apply online for 51 vacancies across various trades.</p>\r\n\r\n<h3>Important Dates</h3>\r\n<ul>\r\n<li><strong>Application Start Date:</strong> 10 March 2026</li>\r\n<li><strong>Last Date to Apply Online:</strong> 09 April 2026</li>\r\n<li><strong>Last Date for Fee Payment:</strong> 09 April 2026</li>\r\n</ul>\r\n\r\n<h3>Application Fee</h3>\r\n<ul>\r\n<li><strong>General / OBC / EWS:</strong> Rs. 100/-</li>\r\n<li><strong>SC / ST / PwD / Women:</strong> NIL (Exempted)</li>\r\n<li><strong>Payment Mode:</strong> Online</li>\r\n</ul>\r\n\r\n<h3>Age Limit (as on 09/04/2026)</h3>\r\n<ul>\r\n<li><strong>Minimum Age:</strong> 15 Years</li>\r\n<li><strong>Maximum Age:</strong> 24 Years</li>\r\n<li><strong>Age Relaxation:</strong> As per Railway rules (SC/ST +5, OBC +3, PwD +10).</li>\r\n</ul>\r\n\r\n<h3>Eligibility</h3>\r\n<p>Candidates must have passed <strong>Class 10th (High School / Matric)</strong> with minimum <strong>50% marks</strong> and possess an <strong>ITI Certificate</strong> in the relevant trade from NCVT/SCVT.</p>\r\n\r\n<h3>Vacancy Details</h3>\r\n<ul>\r\n<li><strong>Total Posts:</strong> 51</li>\r\n<li><strong>Trade:</strong> Various (Fitter, Electrician, Welder, etc. - see notification)</li>\r\n<li><strong>Training Location:</strong> Central Railway zones (Mumbai, Bhusawal, etc.)</li>\r\n</ul>\r\n\r\n<h3>Selection Process</h3>\r\n<p>Selection is based on merit list prepared on the basis of marks in Class 10th and ITI, followed by Document Verification and Medical Examination.</p>\r\n\r\n<p><strong>Important Links:</strong><br />\r\n<a href=\"https://rrccr.etrpindia.com/rrccrapprentice/applicationIndex\" target=\"_blank\" rel=\"noopener\">Apply Online</a><br />\r\n<a href=\"notifications/1775120764_central-railway-rrc-cr-various-trade-apprentices-2026-apply-online-for-51-post.pdf\" target=\"_blank\" rel=\"noopener\">Download Notification PDF</a><br />\r\n<a href=\"https://rrccr.etrpindia.com/\" target=\"_blank\" rel=\"noopener\">Official RRC CR Website</a></p>', NULL, '2026-04-02', '2026-04-09', '2026-04-09', NULL, NULL, NULL, NULL, '2026-04-09', '₹ 100/-', '₹ 0/- (Exempted)', NULL, 'Online', 100.00, '15 Years', '24 Years', 'SC/ST +5, OBC +3, PwD +10 years', '15-24', '51', 'All India', 'Class 10 High School / Matric with 50% Marks, ITI Certificate in Related Trade', NULL, NULL, 'Merit List on Class 10th and ITI marks, Document Verification, Medical Examination', 'Apply online through RRC CR official portal', 'https://rrccr.etrpindia.com/rrccrapprentice/applicationIndex', NULL, NULL, NULL, NULL, NULL, NULL, 'https://rrccr.etrpindia.com/', 'notifications/1775120764_central-railway-rrc-cr-various-trade-apprentices-2026-apply-online-for-51-post.pdf', NULL, NULL, 'Central Railway Apprentices Recruitment 2026', 'Central Railway RRC CR Trade Apprentices Recruitment 2026 for 51 posts. Apply online from 10 March to 09 April 2026', 'Central Railway, Apprentices, Railway Jobs, RRC CR', 1, 0, 133, '2026-04-01 22:03:43', '2026-07-12 15:19:45'),
