(19, 'BPSC School Teacher TRE 4.0 Recruitment 2026', 'bpsc-school-teacher-tre-40-recruitment-2026', 5, 'BPSC School Teacher TRE 4.0 Recruitment 2026. Apply online from 20 May to 19 June 2026.', '<h2>BPSC TRE 4.0 Teacher Recruitment 2026</h2>', NULL, '2026-05-20', '2026-06-19', NULL, NULL, NULL, NULL, NULL, NULL, '₹ 500/-', '₹ 0/- (Exempted)', NULL, 'Online', 500.00, '18 Years', '33 Years', 'As per government rules', NULL, NULL, 'Bihar', 'Bachelor Degree in Any Stream', NULL, NULL, NULL, NULL, 'https://www.bpsc.bih.nic.in/', NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.bpsc.bih.nic.in/', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1, 238, '2026-04-18 16:45:18', '2026-07-12 15:19:43'),
(20, 'NCL Various Post Requirement 2026', 'ncl-various-post-requirement-2026', 9, 'NCL Recruitment 2026 for HEMM Operator, Paramedical Staff, Overseer(Civil) posts. 577 vacancies.', '<h2>NCL Various Posts Recruitment 2026</h2>', NULL, '2026-04-09', '2026-05-01', NULL, NULL, NULL, NULL, NULL, NULL, '₹ 1000/-', '₹ 0/- (Exempted)', NULL, 'Online', 1000.00, '18 Years', '30 Years', 'As per government rules', NULL, '577', 'All India', 'As per post requirement', NULL, NULL, NULL, NULL, 'https://cdn.digialm.com/EForms/configuredHtml/1258/2000122/Index.html', NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.nclcil.in/data-listing/pages/recruitment', 'notifications/1776881979_ncl-various-post-requirement-2026.pdf', NULL, NULL, NULL, NULL, NULL, 1, 0, 141, '2026-04-18 18:49:33', '2026-07-12 15:19:45'),
(21, 'NTPC Assistant Executive Operation Recruitment 2026 Apply Online for 250 Post', 'ntpc-assistant-executive-operation-recruitment-2026-apply-online-for-250-post', 9, 'NTPC Assistant Executive Operation Recruitment 2026 for 250 posts. Apply online from 23 April to 07 May 2026.', '<h2>NTPC Assistant Executive Recruitment 2026</h2>', NULL, '2026-04-23', '2026-05-07', NULL, NULL, NULL, NULL, NULL, NULL, '₹ 500/-', '₹ 0/- (Exempted)', NULL, 'Online', 500.00, '18 Years', '35 Years', 'As per government rules', NULL, '250', NULL, 'BE/B.Tech in Mechanical/Electrical Engineering with 1 Year Experience', NULL, NULL, NULL, NULL, 'https://careers.ntpc.co.in/recruitment/login.php', NULL, NULL, NULL, NULL, NULL, NULL, 'https://careers.ntpc.co.in/recruitment/', 'notifications/1777184489_ntpc-assistant-executive-operation-recruitment-2026-apply-online-for-250-post.pdf', NULL, NULL, NULL, NULL, NULL, 1, 0, 129, '2026-04-25 19:21:29', '2026-07-12 15:19:46'),
(26, 'Indian Bank Specialist Officer SO Recruitment 2026', 'indian-bank-specialist-officer-so-recruitment-2026', 10, 'The Indian Bank application form started on 08 April 2026, and candidates can apply until 28 April 2026. The minimum age required is 22 years, and the maximum age limit is 45 years (Post Wise) as of 01 April 2026.', 'Interested candidates who wish to apply for the Indian Bank Specialist Officer SO post can submit their application online before 28 April 2026.\r\nUse the click here link provided below under important link section to apply directly.\r\nAlternatively, visit the official website of Indian Bank Specialist Officer SO to complete the application process online.', NULL, '2026-04-08', '2026-04-28', '2026-04-28', NULL, NULL, NULL, NULL, NULL, '₹ 1000/-', '₹ 175/-', 'Portal Charges Extra', 'Debit Card, Credit Card, Net Banking', NULL, '22 Years', '45 Years', 'Indian Bank provides age relaxation for the Specialist Officer SO Positions as per their regulations.', NULL, '350', 'All India', NULL, 'Indian Bank Specialist Officer SO  Candidates must have a Bachelor’s degree / Master’s degree / CA / B.Tech from a recognized university or institute. For post-wise eligibility and experience details, candidates should read the official notification carefully.', NULL, 'Written Test\r\nScreening\r\nPersonal Interview\r\nFinal Merit List\r\nProficiency in Local Language\r\nFinal Selection', NULL, 'https://ibpsreg.ibps.in/ibsofeb26/', NULL, NULL, NULL, NULL, NULL, NULL, 'https://ibpsreg.ibps.in/', 'notifications/1777284251_indian-bank-specialist-officer-so-recruitment-2026.pdf', NULL, NULL, NULL, NULL, NULL, 1, 0, 217, '2026-04-27 04:34:11', '2026-07-12 15:19:44'),
(29, 'SSC CGL 2026', 'ssc-cgl-2026', 3, 'Staff Selection Commission Combined Graduate Level Examination 2026 for Group B & C posts. Apply online from 15 May to 15 June 2026.', '<h2>SSC CGL 2026 - Combined Graduate Level Examination</h2><p>The Staff Selection Commission (SSC) has released the official notification for the Combined Graduate Level (CGL) Examination 2026.</p>', 'Total vacancies to be notified by SSC.', '2026-05-15', '2026-06-15', '2026-06-18', '2026-06-20', '2026-08-12', '2026-08-01', '2026-09-20', '2026-01-01', '₹ 100/-', '₹ 0/- (Exempted)', '₹ 100/-', 'Online (Net Banking, Credit Card, Debit Card, UPI)', NULL, '18 Years', '32 Years', 'SC/ST: 5 years, OBC: 3 years, PwD: 10 years', NULL, '12,256', 'Across India', 'Bachelor\'s Degree in any discipline from a recognized university.', 'Computer proficiency for certain posts.', 'Freshers can apply.', 'Tier I (CBT), Tier II (CBT), Tier III (Descriptive), Tier IV (Skill Test/Typing Test)', 'Apply online through SSC official website.', 'https://ssc.nic.in', 'https://ssc.nic.in', 'https://ssc.nic.in', 'https://ssc.nic.in', 'https://ssc.nic.in', 'https://ssc.nic.in', 'https://ssc.nic.in', 'https://ssc.nic.in', NULL, NULL, NULL, 'SSC CGL 2026 - Combined Graduate Level Exam Notification, Apply Online', 'Get complete details of SSC CGL 2026 exam: dates, eligibility, fee, vacancy, syllabus, and apply online link.', 'SSC CGL 2026, SSC CGL Notification, SSC CGL Apply Online', 1, 0, 74, '2026-05-27 18:56:17', '2026-07-11 21:51:34'),
(30, 'UPSSSC UP Technical Assistant Group C Recruitment 2026', 'upsssc-up-technical-assistant-group-c-recruitment-2026', 1, 'UPSSSC has announced the Technical Assistant (Group C) Recruitment 2026 (Advt. No. 09-Exam/2026). Get complete details for 2,759 vacancies. UPSSSC PET 2025 score card required. Apply online from 10 June to 30 June 2026.', '<h2>UPSSSC Technical Assistant (Group C) Recruitment 2026</h2>\r\n<p><strong>Uttar Pradesh Subordinate Service Selection Commission (UPSSSC)</strong> has released the official notification for the <strong>Technical Assistant (Group C) Examination 2026</strong> (Advt. No. 09-Exam/2026). This is a prestigious recruitment drive for technical graduates seeking government jobs in Uttar Pradesh.</p>\r\n\r\n<h3>Important Dates</h3>\r\n<ul>\r\n<li><strong>Application Start Date:</strong> 10 June 2026</li>\r\n<li><strong>Last Date to Apply Online:</strong> 30 June 2026</li>\r\n<li><strong>Last Date for Fee Payment:</strong> 30 June 2026</li>\r\n<li><strong>Application Correction Date:</strong> 05-07 July 2026</li>\r\n<li><strong>Exam Date:</strong> September/October 2026</li>\r\n<li><strong>Admit Card Release:</strong> 15 Days Before Exam</li>\r\n<li><strong>Result Date:</strong> To be notified</li>\r\n</ul>\r\n\r\n<h3>Application Fee</h3>\r\n<ul>\r\n<li><strong>General / OBC / EWS:</strong> ₹ 25/-</li>\r\n<li><strong>SC / ST / Female:</strong> ₹ 25/-</li>\r\n<li><strong>PwD:</strong> ₹ 25/-</li>\r\n<li><strong>Payment Mode:</strong> Online (Debit Card, Credit Card, Net Banking, UPI)</li>\r\n</ul>\r\n\r\n<h3>Age Limit (as on 01/07/2026)</h3>\r\n<ul>\r\n<li><strong>Minimum Age:</strong> 18 Years</li>\r\n<li><strong>Maximum Age:</strong> 40 Years</li>\r\n<li><strong>Age Relaxation:</strong> SC/ST: 5 years, OBC: 3 years, PwD: 10 years (As per UPSSSC rules)</li>\r\n</ul>\r\n\r\n<h3>Eligibility Criteria</h3>\r\n<p>Candidates must possess a valid <strong>UPSSSC PET 2025 Score Card</strong>. Educational qualification includes a <strong>Bachelor\'s Degree in Engineering/Technology (B.E./B.Tech)</strong> in relevant discipline OR <strong>Diploma in Engineering</strong> from a recognized university/institute.</p>\r\n\r\n<h4>Post-Wise Qualification:</h4>\r\n<ul>\r\n<li><strong>Technical Assistant (Civil):</strong> B.E./B.Tech/Diploma in Civil Engineering</li>\r\n<li><strong>Technical Assistant (Mechanical):</strong> B.E./B.Tech/Diploma in Mechanical Engineering</li>\r\n<li><strong>Technical Assistant (Electrical):</strong> B.E./B.Tech/Diploma in Electrical Engineering</li>\r\n<li><strong>Technical Assistant (Agriculture):</strong> B.Sc Agriculture/Diploma in Agriculture Engineering</li>\r\n<li><strong>Technical Assistant (Computer):</strong> B.E./B.Tech/Diploma in Computer Science/IT</li>\r\n</ul>\r\n\r\n<h3>Vacancy Details</h3>\r\n<p><strong>Total Posts:</strong> 2,759</p>\r\n<p><strong>Job Location:</strong> Uttar Pradesh (Various Departments)</p>\r\n\r\n<h4>Category-wise Vacancy Breakdown:</h4>\r\n<ul>\r\n<li>General (UR): 1,104 Posts</li>\r\n<li>OBC: 497 Posts</li>\r\n<li>SC: 717 Posts</li>\r\n<li>ST: 69 Posts</li>\r\n<li>EWS: 276 Posts</li>\r\n<li>PwD: 96 Posts (Reserved within categories)</li>\r\n</ul>\r\n\r\n<h3>Selection Process</h3>\r\n<p>The selection will be based on the following stages:</p>\r\n<ol>\r\n<li>Written Examination (Objective Type)</li>\r\n<li>Technical Skill Test (where applicable)</li>\r\n<li>Document Verification</li>\r\n<li>Medical Examination</li>\r\n</ol>\r\n\r\n<h3>Exam Pattern</h3>\r\n<ul>\r\n<li><strong>Written Exam:</strong> 100 Questions, 100 Marks</li>\r\n<li><strong>Duration:</strong> 2 Hours</li>\r\n<li><strong>Subjects:</strong> General Hindi, General Knowledge, Technical Subject</li>\r\n<li><strong>Negative Marking:</strong> 1/4 mark deduction for wrong answer</li>\r\n</ul>\r\n\r\n<h3>Salary/Pay Scale</h3>\r\n<p>Pay Level - 5 (₹ 29,200 - ₹ 92,300) as per 7th Pay Commission Matrix.</p>\r\n\r\n<h3>How to Apply for UPSSSC Technical Assistant 2026</h3>\r\n<p>Candidates can apply online from 10 June 2026 through the official UPSSSC website. Keep your PET scorecard, educational certificates, engineering degree/diploma certificates, photograph, and signature ready before applying.</p>\r\n\r\n<h3>Documents Required</h3>\r\n<ul>\r\n<li>UPSSSC PET 2025 Score Card</li>\r\n<li>10th and 12th Mark Sheets</li>\r\n<li>B.E./B.Tech/Diploma Degree Certificate</li>\r\n<li>Caste Certificate (if applicable)</li>\r\n<li>Domicile Certificate</li>\r\n<li>PwD Certificate (if applicable)</li>\r\n<li>Passport Size Photograph (10-50 KB)</li>\r\n<li>Signature (10-20 KB)</li>\r\n</ul>\r\n\r\n<p><strong>Important Links:</strong><br />\r\n<a href=\"https://upsssc.gov.in/\" target=\"_blank\" rel=\"noopener\">Apply Online</a><br />\r\n<a href=\"notifications/upsssc_technical_assistant_2026_notification.pdf\" target=\"_blank\" rel=\"noopener\">Download Official Notification PDF</a><br />\r\n<a href=\"notifications/upsssc_technical_assistant_2026_syllabus.pdf\" target=\"_blank\" rel=\"noopener\">Download Syllabus PDF</a><br />\r\n<a href=\"https://upsssc.gov.in/\" target=\"_blank\" rel=\"noopener\">UPSSSC Official Website</a></p>\r\n\r\n<p><strong>Tags:</strong> UPSSSC Technical Assistant 2026, UP Technical Assistant Recruitment, UP Govt Jobs 2026, Sarkari Result, Engineering Jobs in UP</p>', 'Total Vacancies: 2,759 Posts across various departments of Uttar Pradesh Government. Posts include Technical Assistant (Civil, Mechanical, Electrical, Agriculture, Computer). Additional vacancies may be announced later by UPSSSC.', '2026-06-10', '2026-06-30', '2026-06-30', '2026-07-05', '2026-09-20', '2026-09-05', '2026-10-30', '2026-07-01', '₹ 25/-', '₹ 25/-', '₹ 25/-', 'Online (Debit Card, Credit Card, Net Banking, UPI)', NULL, '18 Years', '40 Years', 'SC/ST: 5 years, OBC: 3 years, PwD: 10 years, Ex-Servicemen: As per UPSSSC rules', NULL, '2759', 'Uttar Pradesh (Lucknow, Kanpur, Agra, Varanasi, Prayagraj, Gorakhpur, Bareilly, Meerut, Noida, Ghaziabad and other districts)', 'UPSSSC PET 2025 Score Card is mandatory. B.E./B.Tech/Diploma in relevant Engineering discipline (Civil/Mechanical/Electrical/Agriculture/Computer Science) from recognized university/institute with minimum 50% marks (45% for SC/ST).', 'Computer knowledge (MS Office, Internet, Email). For Computer TA: Programming knowledge, Database management, Web development basics. Preference will be given to candidates with NCC certificate and computer diploma.', '0-2 years experience preferred but freshers can also apply. Candidates with prior government/private technical experience will get additional weightage.', 'Stage 1: Written Examination (Objective Type - 100 Marks, 2 Hours)\r\nStage 2: Technical Skill Test (Qualifying Nature)\r\nStage 3: Document Verification\r\nStage 4: Medical Examination\r\nFinal Merit List based on Written Exam marks and experience (if applicable)', 'Apply online through official UPSSSC website (upsssc.gov.in) from 10 June 2026 to 30 June 2026. Candidates must first register on UPSSSC portal, fill application form, upload scanned documents (photo, signature, certificates), pay application fee online, submit final application, and take printout for future reference.', 'https://upsssc.gov.in/', 'https://upsssc.gov.in/', 'https://upsssc.gov.in/', 'https://upsssc.gov.in/', 'https://upsssc.gov.in/', 'https://upsssc.gov.in/', 'https://upsssc.gov.in/', 'https://upsssc.gov.in/', NULL, NULL, NULL, 'UPSSSC Technical Assistant Recruitment 2026 - Apply Online for 2,759 Posts', 'UPSSSC Technical Assistant (Group C) Recruitment 2026. Complete details: 2,759 vacancies, eligibility: B.E./B.Tech/Diploma with PET 2025 score, age limit 18-40 years, fee ₹25/-. Apply online from 10-30 June 2026.', 'UPSSSC Technical Assistant, UP Technical Assistant Recruitment, UPSSSC Group C Jobs, UP Govt Jobs 2026, Technical Assistant Vacancy, UPSSSC Recruitment 2026, Engineering Jobs in UP, Sarkari Result, UPSSSC Apply Online', 1, 1, 81, '2026-05-27 19:02:43', '2026-07-11 21:37:47');
INSERT INTO `jobs` (`id`, `title`, `slug`, `category_id`, `short_description`, `description`, `vacancy_details`, `start_date`, `last_date`, `fee_last_date`, `correction_date`, `exam_date`, `admit_card_date`, `result_date`, `age_calculation_date`, `fee_general`, `fee_sc_st_female`, `fee_other`, `payment_mode`, `application_fee`, `min_age`, `max_age`, `age_relaxation`, `age_limit`, `total_post`, `job_location`, `qualification`, `additional_qualification`, `experience_required`, `selection_process`, `how_to_apply`, `application_link`, `registration_link`, `login_link`, `admit_card_link`, `result_link`, `answer_key_link`, `syllabus_link`, `official_website`, `notification_pdf`, `short_notification_pdf`, `syllabus_pdf`, `meta_title`, `meta_description`, `meta_keywords`, `is_active`, `is_featured`, `views`, `created_at`, `updated_at`) VALUES
(31, 'Join Indian Navy 10+2 B.Tech Entry January 2027 Batch', 'join-indian-navy-10-2-btech-entry-january-2027-batch', 7, 'Indian Navy 10+2 B.Tech Entry January 2027 Batch for unmarried male candidates. Apply online for 60 posts. Eligibility: 10+2 with Physics, Chemistry, Mathematics (PCM) with minimum 70% marks. Age limit: 17-19.5 years. SSB interview and medical test based selection.', '<h2>Indian Navy 10+2 B.Tech Entry Scheme January 2027 Batch</h2>\r\n<p>The <strong>Indian Navy</strong> has released the official notification for the <strong>10+2 B.Tech Entry Scheme January 2027 Batch</strong>. This is a prestigious opportunity for young unmarried male candidates to join the Indian Navy as officers through the 10+2 B.Tech Cadet Entry Scheme.</p>\r\n\r\n<h3>Important Dates</h3>\r\n<ul>\r\n<li><strong>Application Start Date:</strong> 15 June 2026</li>\r\n<li><strong>Last Date to Apply Online:</strong> 30 June 2026</li>\r\n<li><strong>Last Date for Fee Payment:</strong> 30 June 2026</li>\r\n<li><strong>Application Correction Date:</strong> 01-03 July 2026</li>\r\n<li><strong>SSB Interview Dates:</strong> August to October 2026</li>\r\n<li><strong>Admit Card Release:</strong> 20 July 2026</li>\r\n<li><strong>Result Date:</strong> November 2026</li>\r\n<li><strong>Training Start Date:</strong> January 2027</li>\r\n</ul>\r\n\r\n<h3>Application Fee</h3>\r\n<ul>\r\n<li><strong>General / OBC / EWS:</strong> ₹ 0/- (NIL - No Application Fee)</li>\r\n<li><strong>SC / ST / PwD:</strong> ₹ 0/- (NIL - No Application Fee)</li>\r\n<li><strong>Payment Mode:</strong> Not Applicable (No Fee)</li>\r\n</ul>\r\n\r\n<h3>Age Limit (as on 01 January 2027)</h3>\r\n<ul>\r\n<li><strong>Minimum Age:</strong> 17 Years</li>\r\n<li><strong>Maximum Age:</strong> 19.5 Years (19 Years 6 Months)</li>\r\n<li><strong>Born Between:</strong> 02 July 2007 to 01 January 2010</li>\r\n<li><strong>Age Relaxation:</strong> No relaxation for any category</li>\r\n</ul>\r\n\r\n<h3>Eligibility Criteria</h3>\r\n<p>Candidates must have passed <strong>10+2 (Intermediate)</strong> examination with <strong>Physics, Chemistry, and Mathematics (PCM)</strong> subjects from a recognized board.</p>\r\n\r\n<h4>Minimum Marks Required:</h4>\r\n<ul>\r\n<li><strong>General / OBC / EWS:</strong> Minimum 70% aggregate marks in PCM</li>\r\n<li><strong>SC / ST:</strong> Minimum 60% aggregate marks in PCM</li>\r\n<li><strong>JEE Main Score:</strong> Valid JEE Main 2026 score is mandatory</li>\r\n<li><strong>English Requirement:</strong> Minimum 50% marks in English subject in 10+2</li>\r\n</ul>\r\n\r\n<h3>Physical Standards</h3>\r\n<ul>\r\n<li><strong>Height:</strong> Minimum 157 cms (1570 mm)</li>\r\n<li><strong>Weight:</strong> Proportionate to height and age</li>\r\n<li><strong>Chest:</strong> Minimum expansion of 5 cms</li>\r\n<li><strong>Eye Sight:</strong> 6/6 (without glasses) - No color blindness</li>\r\n<li><strong>BMI:</strong> Within normal range (18-24)</li>\r\n<li><strong>Medical Standards:</strong> Candidates must be physically and medically fit as per Indian Navy standards</li>\r\n</ul>\r\n\r\n<h3>Vacancy Details</h3>\r\n<p><strong>Total Posts:</strong> 60</p>\r\n<p><strong>Branch Details:</strong></p>\r\n<ul>\r\n<li><strong>Executive Branch:</strong> 30 Posts</li>\r\n<li><strong>Engineering Branch:</strong> 20 Posts</li>\r\n<li><strong>Electrical Branch:</strong> 10 Posts</li>\r\n</ul>\r\n<p><strong>Job Location:</strong> Indian Naval Academy, Ezhimala, Kerala & Various Naval Bases across India</p>\r\n\r\n<h3>Training Details</h3>\r\n<ul>\r\n<li><strong>Training Duration:</strong> 4 Years B.Tech Course</li>\r\n<li><strong>Training Location:</strong> Indian Naval Academy (INA), Ezhimala, Kerala</li>\r\n<li><strong>Degree Awarded:</strong> B.Tech Degree from Jawaharlal Nehru University (JNU), New Delhi</li>\r\n<li><strong>Stipend During Training:</strong> ₹ 56,100/- per month</li>\r\n<li><strong>After Commission:</strong> Level 10 (₹ 61,300 - ₹ 1,93,100) with MSP ₹ 15,500/-</li>\r\n</ul>\r\n\r\n<h3>Selection Process</h3>\r\n<p>The selection will be based on the following stages:</p>\r\n<ol>\r\n<li><strong>Shortlisting:</strong> Based on 10+2 PCM marks and JEE Main 2026 score</li>\r\n<li><strong>SSB Interview:</strong> 5-day selection process (Stage I & II)</li>\r\n<li><strong>Psychological Tests:</strong> Thematic Apperception Test (TAT), Word Association Test (WAT), Situation Reaction Test (SRT), Self Description Test (SDT)</li>\r\n<li><strong>Group Tasks:</strong> Group Discussion (GD), Group Planning Exercise (GPE), Progressive Group Task (PGT), Half Group Task (HGT), Individual Obstacles, Command Task, Lecturette</li>\r\n<li><strong>Personal Interview:</strong> Detailed interview with selection board</li>\r\n<li><strong>Medical Examination:</strong> Thorough medical checkup</li>\r\n<li><strong>Merit List:</strong> Based on SSB marks + Medical fitness</li>\r\n</ol>\r\n\r\n<h3>Exam Pattern for JEE Main</h3>\r\n<ul>\r\n<li><strong>Subjects:</strong> Physics, Chemistry, Mathematics</li>\r\n<li><strong>Total Questions:</strong> 75 Questions (25 each subject)</li>\r\n<li><strong>Total Marks:</strong> 300 Marks</li>\r\n<li><strong>Duration:</strong> 3 Hours</li>\r\n<li><strong>Marking:</strong> +4 for correct, -1 for incorrect</li>\r\n</ul>\r\n\r\n<h3>How to Apply for Indian Navy 10+2 B.Tech Entry 2027</h3>\r\n<p>Candidates can apply online from 15 June 2026 through the official Join Indian Navy website. Follow these steps:</p>\r\n<ol>\r\n<li>Visit the official website: <strong>https://www.joinindiannavy.gov.in</strong></li>\r\n<li>Click on \"Officer Entry\" → \"10+2 B.Tech Entry\"</li>\r\n<li>Register with your email ID and mobile number</li>\r\n<li>Fill the application form carefully with all details</li>\r\n<li>Upload scanned photo, signature, and 10+2 mark sheet</li>\r\n<li>Enter your JEE Main 2026 roll number and score</li>\r\n<li>Submit the application form (No fee required)</li>\r\n<li>Take a printout of the application form for future reference</li>\r\n</ol>\r\n\r\n<h3>Documents Required</h3>\r\n<ul>\r\n<li>10th Mark Sheet & Certificate (for date of birth proof)</li>\r\n<li>10+2 (Intermediate) Mark Sheet & Certificate</li>\r\n<li>JEE Main 2026 Score Card</li>\r\n<li>Recent Passport Size Photograph (10-50 KB, JPEG format)</li>\r\n<li>Signature (10-20 KB, JPEG format)</li>\r\n<li>Caste Certificate (if applicable)</li>\r\n<li>Domicile Certificate</li>\r\n<li>Medical Certificate (for PwD candidates)</li>\r\n</ul>\r\n\r\n<h3>Important Information</h3>\r\n<ul>\r\n<li><strong>Marital Status:</strong> Only unmarried male candidates are eligible</li>\r\n<li><strong>Citizenship:</strong> Must be a citizen of India</li>\r\n<li><strong>Number of Attempts:</strong> Maximum 2 attempts for JEE Main</li>\r\n<li><strong>Service Liability:</strong> Minimum 15 years of service commitment</li>\r\n<li><strong>Permanent Commission:</strong> Candidates are granted Permanent Commission (PC) in Indian Navy</li>\r\n</ul>\r\n\r\n<h3>Salary & Benefits</h3>\r\n<ul>\r\n<li><strong>Training Stipend:</strong> ₹ 56,100/- per month</li>\r\n<li><strong>After Commission (Level 10):</strong> ₹ 61,300 - ₹ 1,93,100</li>\r\n<li><strong>Military Service Pay (MSP):</strong> ₹ 15,500/- per month</li>\r\n<li><strong>Dearness Allowance (DA):</strong> As per government norms</li>\r\n<li><strong>Other Allowances:</strong> Kit Maintenance Allowance, Hard Area Allowance, Sea Duty Allowance, etc.</li>\r\n<li><strong>Free Accommodation:</strong> Government quarters/Single accommodation provided</li>\r\n<li><strong>Medical Facilities:</strong> Free medical treatment for self and dependents</li>\r\n<li><strong>Leave:</strong> 60 days annual leave + 20 days casual leave + 30 days sick leave</li>\r\n<li><strong>Retirement Benefits:</strong> Pension, Gratuity, and other post-retirement benefits</li>\r\n</ul>\r\n\r\n<p><strong>Important Links:</strong><br />\r\n<a href=\"https://www.joinindiannavy.gov.in/en/account/account/state\" target=\"_blank\" rel=\"noopener\">Apply Online</a><br />\r\n<a href=\"notifications/indian_navy_10_2_btech_entry_jan2027_notification.pdf\" target=\"_blank\" rel=\"noopener\">Download Official Notification PDF</a><br />\r\n<a href=\"notifications/indian_navy_10_2_btech_entry_jan2027_syllabus.pdf\" target=\"_blank\" rel=\"noopener\">Download Syllabus & SSB Guide PDF</a><br />\r\n<a href=\"https://www.joinindiannavy.gov.in/\" target=\"_blank\" rel=\"noopener\">Join Indian Navy Official Website</a></p>\r\n\r\n<p><strong>Tags:</strong> Indian Navy 10+2 BTech Entry, Indian Navy January 2027 Batch, Navy Officer Recruitment, 10+2 B.Tech Cadet Entry, Indian Navy Jobs, Defence Jobs 2026, Navy SSB Interview</p>', 'Total Vacancies: 60 Posts (Executive Branch: 30, Engineering Branch: 20, Electrical Branch: 10). Vacancies may vary based on organizational requirements. Candidates will undergo 4 years B.Tech training at Indian Naval Academy (INA), Ezhimala.', '2026-06-15', '2026-06-30', '2026-06-30', '2026-07-01', '2026-08-15', '2026-07-20', '2026-11-30', '2027-01-01', '₹ 0/- (No Fee)', '₹ 0/- (No Fee)', '₹ 0/- (No Fee)', 'Not Applicable (Free Entry)', NULL, '17 Years', '19.5 Years', 'No relaxation for any category. Born between 02 July 2007 to 01 January 2010 only.', NULL, '60', 'Indian Naval Academy, Ezhimala (Kerala) & Various Naval Bases across India (Mumbai, Visakhapatnam, Kochi, Goa, Chennai, Kolkata, Port Blair)', '10+2 (Intermediate) with Physics, Chemistry, Mathematics (PCM) subjects from recognized board. General/OBC: 70% aggregate in PCM, SC/ST: 60% aggregate in PCM. Valid JEE Main 2026 score mandatory. Minimum 50% marks in English subject.', 'NCC Certificate (Navy/Army/Air Wing) with C Certificate will be given additional weightage. Sports certificates at national level, participation in Olympiads, extracurricular achievements are desirable. Knowledge of swimming and adventure sports preferred.', 'No prior experience required. Freshers are eligible to apply. Candidates must have appeared for JEE Main 2026 examination.', 'Stage 1: Shortlisting based on 10+2 PCM percentage (70% for General/OBC, 60% for SC/ST) and JEE Main 2026 score (cutoff: General 85 percentile, OBC 75 percentile, SC/ST 65 percentile)\r\nStage 2: SSB Interview (5 days - Stage I: Screening, Picture Perception & Discussion Test; Stage II: Psychological Tests, Group Tasks, Personal Interview)\r\nStage 3: Medical Examination (Full medical checkup as per Indian Navy standards)\r\nStage 4: Merit List preparation based on SSB marks (total 900 marks) and medical fitness\r\nStage 5: Final selection by Naval Headquarters (NHQ)', 'Apply online through official Join Indian Navy website (www.joinindiannavy.gov.in) from 15 June 2026 to 30 June 2026. No application fee required. Candidates must register, fill application form with JEE Main 2026 details, upload documents (photo, signature, 10+2 marksheet), submit form, and take printout for records.', 'https://www.joinindiannavy.gov.in/en/account/account/state', 'https://www.joinindiannavy.gov.in/en/account/account/state', 'https://www.joinindiannavy.gov.in/en/account/login', 'https://www.joinindiannavy.gov.in/en/ssb/admit-card', 'https://www.joinindiannavy.gov.in/en/result/btech-entry', 'https://www.joinindiannavy.gov.in/en/answer-key', 'https://www.joinindiannavy.gov.in/en/syllabus/btech-entry', 'https://www.joinindiannavy.gov.in/', NULL, NULL, NULL, 'Indian Navy 10+2 B.Tech Entry January 2027 Batch - Apply Online for 60 Posts', 'Join Indian Navy as an officer through 10+2 B.Tech Entry Scheme January 2027 Batch. Total 60 vacancies. Eligibility: 10+2 PCM with 70% marks, JEE Main 2026 score required. Age: 17-19.5 years. Apply online from 15-30 June 2026. No application fee.', 'Indian Navy, 10+2 B.Tech Entry, Indian Navy Officer Recruitment, January 2027 Batch, Navy Jobs, Defence Jobs, SSB Interview, INA Ezhimala, Permanent Commission, JEE Main 2026, Navy BTech Entry, Sarkari Result', 1, 1, 107, '2026-05-27 19:04:50', '2026-07-12 15:19:46'),
(32, 'UPSC Combined Defence Service CDS II Recruitment 2026', 'upsc-combined-defence-service-cds-ii-recruitment-2026', 4, 'UPSC CDS II Recruitment 2026 for 451 vacancies in Indian Military Academy, Naval Academy, Air Force Academy, and Officers Training Academy. Apply online from 28 May to 17 June 2026. Eligibility: Graduate in any discipline. Age limit: 19-25 years (post wise).', '<h2>UPSC Combined Defence Service (CDS) II Examination 2026</h2>\r\n<p>The <strong>Union Public Service Commission (UPSC)</strong> has released the official notification for the <strong>Combined Defence Service (CDS) II Examination 2026</strong>. This examination is conducted twice a year for recruitment into the Indian Military Academy (IMA), Indian Naval Academy (INA), Air Force Academy (AFA), and Officers Training Academy (OTA).</p>\r\n\r\n<h3>Important Dates</h3>\r\n<ul>\r\n<li><strong>Application Start Date:</strong> 28 May 2026</li>\r\n<li><strong>Last Date to Apply Online:</strong> 17 June 2026</li>\r\n<li><strong>Last Date for Fee Payment:</strong> 17 June 2026</li>\r\n<li><strong>Application Correction Date:</strong> 18-24 June 2026</li>\r\n<li><strong>Admit Card Release Date:</strong> 3-4 weeks before exam</li>\r\n<li><strong>Written Exam Date:</strong> 02 August 2026</li>\r\n<li><strong>Result Date (Written):</strong> October 2026</li>\r\n<li><strong>SSB Interview Dates:</strong> November 2026 to March 2027</li>\r\n<li><strong>Final Result Date:</strong> April 2027</li>\r\n</ul>\r\n\r\n<h3>Application Fee</h3>\r\n<ul>\r\n<li><strong>General / OBC / EWS:</strong> ₹ 200/-</li>\r\n<li><strong>SC / ST / PwD / Female:</strong> ₹ 0/- (Exempted)</li>\r\n<li><strong>Payment Mode:</strong> Online (Net Banking, Credit Card, Debit Card, UPI) or Offline (Cash at SBI Bank)</li>\r\n</ul>\r\n\r\n<h3>Age Limit (as on 01 January 2027)</h3>\r\n<ul>\r\n<li><strong>Indian Military Academy (IMA):</strong> 19-24 Years (Born between 02 Jan 2003 to 01 Jan 2008)</li>\r\n<li><strong>Indian Naval Academy (INA):</strong> 19-24 Years (Born between 02 Jan 2003 to 01 Jan 2008)</li>\r\n<li><strong>Air Force Academy (AFA):</strong> 19-24 Years (Born between 02 Jan 2003 to 01 Jan 2008)</li>\r\n<li><strong>Officers Training Academy (OTA):</strong> 19-25 Years (Born between 02 Jan 2002 to 01 Jan 2008)</li>\r\n<li><strong>Age Relaxation:</strong> As per government rules for reserved categories</li>\r\n</ul>\r\n\r\n<h3>Educational Qualification</h3>\r\n<h4>Post-Wise Qualification:</h4>\r\n<ul>\r\n<li><strong>Indian Military Academy (IMA):</strong> Bachelor\'s Degree in any discipline from a recognized university</li>\r\n<li><strong>Indian Naval Academy (INA):</strong> B.E./B.Tech in any discipline from a recognized university/institute</li>\r\n<li><strong>Air Force Academy (AFA):</strong> Bachelor\'s Degree with Physics and Mathematics at 10+2 level OR B.E./B.Tech in any discipline</li>\r\n<li><strong>Officers Training Academy (OTA):</strong> Bachelor\'s Degree in any discipline from a recognized university</li>\r\n</ul>\r\n\r\n<h4>Minimum Marks Required:</h4>\r\n<ul>\r\n<li><strong>General / OBC / EWS:</strong> Pass class (No minimum percentage required)</li>\r\n<li><strong>SC / ST:</strong> Pass class (No minimum percentage required)</li>\r\n</ul>\r\n\r\n<h3>Vacancy Details</h3>\r\n<p><strong>Total Posts:</strong> 451</p>\r\n\r\n<h4>Academy-wise Vacancy Breakup:</h4>\r\n<ul>\r\n<li><strong>Indian Military Academy (IMA), Dehradun:</strong> 150 Posts (131 General + 19 Reserved)</li>\r\n<li><strong>Indian Naval Academy (INA), Ezhimala:</strong> 45 Posts (40 General + 5 Reserved)</li>\r\n<li><strong>Air Force Academy (AFA), Hyderabad:</strong> 36 Posts (30 General + 6 Reserved)</li>\r\n<li><strong>Officers Training Academy (OTA), Chennai (SSC Men):</strong> 170 Posts (135 General + 35 Reserved)</li>\r\n<li><strong>Officers Training Academy (OTA), Chennai (SSC Women):</strong> 50 Posts (40 General + 10 Reserved)</li>\r\n</ul>\r\n\r\n<h4>Category-wise Vacancy Breakdown (Total 451):</h4>\r\n<ul>\r\n<li>General (UR): 276 Posts</li>\r\n<li>OBC: 92 Posts</li>\r\n<li>SC: 50 Posts</li>\r\n<li>ST: 33 Posts</li>\r\n<li>EWS: 40 Posts</li>\r\n</ul>\r\n\r\n<p><strong>Job Location:</strong> Across India (Various Defence Academies and Units)</p>\r\n\r\n<h3>Exam Pattern</h3>\r\n<h4>For IMA, INA, AFA (Paper I, II, III):</h4>\r\n<ul>\r\n<li><strong>Paper I - English:</strong> 120 Questions, 100 Marks, 2 Hours</li>\r\n<li><strong>Paper II - General Knowledge:</strong> 120 Questions, 100 Marks, 2 Hours</li>\r\n<li><strong>Paper III - Elementary Mathematics:</strong> 100 Questions, 100 Marks, 2 Hours</li>\r\n<li><strong>Total Marks:</strong> 300 Marks</li>\r\n<li><strong>Negative Marking:</strong> 1/3 mark deduction for each wrong answer</li>\r\n</ul>\r\n\r\n<h4>For OTA (Paper I & II Only):</h4>\r\n<ul>\r\n<li><strong>Paper I - English:</strong> 120 Questions, 100 Marks, 2 Hours</li>\r\n<li><strong>Paper II - General Knowledge:</strong> 120 Questions, 100 Marks, 2 Hours</li>\r\n<li><strong>Total Marks:</strong> 200 Marks</li>\r\n<li><strong>Negative Marking:</strong> 1/3 mark deduction for each wrong answer</li>\r\n</ul>\r\n\r\n<h3>Syllabus Details</h3>\r\n<h4>English:</h4>\r\n<ul>\r\n<li>Spotting Errors, Fill in the Blanks, Synonyms/Antonyms</li>\r\n<li>Comprehension, Cloze Test, Para Jumbles</li>\r\n<li>One-word Substitution, Idioms & Phrases, Sentence Improvement</li>\r\n</ul>\r\n\r\n<h4>General Knowledge:</h4>\r\n<ul>\r\n<li>Current Events (National & International)</li>\r\n<li>History of India, Indian Geography, Indian Polity</li>\r\n<li>Indian Economy, Science & Technology, Environment & Ecology</li>\r\n<li>Sports, Awards, Books & Authors, Defence related news</li>\r\n</ul>\r\n\r\n<h4>Elementary Mathematics (For IMA/INA/AFA):</h4>\r\n<ul>\r\n<li>Arithmetic (Number System, Percentage, Profit/Loss, Simple/Compound Interest)</li>\r\n<li>Algebra, Trigonometry, Geometry, Mensuration</li>\r\n<li>Statistics, Probability, Data Interpretation</li>\r\n</ul>\r\n\r\n<h3>Selection Process</h3>\r\n<p>The selection will be based on the following stages:</p>\r\n<ol>\r\n<li><strong>Written Examination (Objective Type):</strong> Conducted by UPSC across various centers in India</li>\r\n<li><strong>SSB Interview (Services Selection Board):</strong> 5-day selection process for candidates who qualify written exam</li>\r\n<li><strong>Medical Examination:</strong> Thorough medical checkup as per defence standards</li>\r\n<li><strong>Final Merit List:</strong> Based on written exam marks + SSB marks + medical fitness</li>\r\n</ol>\r\n\r\n<h3>SSB Interview Details</h3>\r\n<p>The SSB Interview is a 5-day process:</p>\r\n<ul>\r\n<li><strong>Day 1 (Screening):</strong> OIR Test (Officer Intelligence Rating) + PPDT (Picture Perception & Discussion Test)</li>\r\n<li><strong>Day 2 (Psychological Tests):</strong> TAT (Thematic Apperception Test), WAT (Word Association Test), SRT (Situation Reaction Test), SDT (Self Description Test)</li>\r\n<li><strong>Day 3 (Group Tasks - GTO):</strong> GD (Group Discussion), GPE (Group Planning Exercise), PGT (Progressive Group Task), HGT (Half Group Task), IOT (Individual Obstacles), Command Task, Lecturette</li>\r\n<li><strong>Day 4 (Personal Interview):</strong> Detailed interview with the board members</li>\r\n<li><strong>Day 5 (Conference):</strong> Final assessment and result declaration</li>\r\n</ul>\r\n\r\n<h3>Physical Standards</h3>\r\n<h4>For IMA, INA, AFA:</h4>\r\n<ul>\r\n<li><strong>Height (Male):</strong> Minimum 157 cms (162 cms for AFA)</li>\r\n<li><strong>Height (Female):</strong> Minimum 152 cms (For OTA Women)</li>\r\n<li><strong>Weight:</strong> Proportionate to height and age</li>\r\n<li><strong>Chest (Male):</strong> Minimum expansion of 5 cms</li>\r\n<li><strong>Eye Sight:</strong> 6/6 (without glasses) for AFA; 6/12 for others</li>\r\n<li><strong>BMI:</strong> Within normal range (18-24)</li>\r\n<li><strong>No Color Blindness, No Tattoos (except permitted areas)</strong></li>\r\n</ul>\r\n\r\n<h3>Training Details</h3>\r\n<ul>\r\n<li><strong>IMA, Dehradun:</strong> 1.5 Years Training (Gentlemen Cadets)</li>\r\n<li><strong>INA, Ezhimala:</strong> 1.5 Years Training (Naval Cadets)</li>\r\n<li><strong>AFA, Hyderabad:</strong> 1.5 Years Training (Flight Cadets)</li>\r\n<li><strong>OTA, Chennai (Men & Women):</strong> 49 Weeks Training (SSC Officers)</li>\r\n</ul>\r\n\r\n<h3>Salary & Benefits</h3>\r\n<ul>\r\n<li><strong>Stipend during Training (IMA/INA/AFA):</strong> ₹ 56,100/- per month</li>\r\n<li><strong>Stipend during Training (OTA):</strong> ₹ 56,100/- per month</li>\r\n<li><strong>After Commission (Level 10):</strong> ₹ 61,300 - ₹ 1,93,100</li>\r\n<li><strong>Military Service Pay (MSP):</strong> ₹ 15,500/- per month</li>\r\n<li><strong>Dearness Allowance (DA):</strong> As per government norms (currently 50%)</li>\r\n<li><strong>Free Accommodation:</strong> Government quarters/Single accommodation provided</li>\r\n<li><strong>Medical Facilities:</strong> Free medical treatment for self and dependents</li>\r\n<li><strong>Leave:</strong> 60 days annual leave + 20 days casual leave + 30 days sick leave</li>\r\n<li><strong>Other Allowances:</strong> Flying Allowance (for AFA), Submarine Allowance (for Navy), Sea Duty Allowance, Field Area Allowance, High Altitude Allowance, etc.</li>\r\n</ul>\r\n\r\n<h3>How to Apply for UPSC CDS II 2026</h3>\r\n<p>Candidates can apply online through the official UPSC website. Follow these steps:</p>\r\n<ol>\r\n<li>Visit the official UPSC website: <strong>https://upsconline.nic.in</strong></li>\r\n<li>Click on \"Online Application for Various Examinations\"</li>\r\n<li>Select \"Combined Defence Services Examination (CDS) II 2026\"</li>\r\n<li>Register with your email ID and mobile number (Part I Registration)</li>\r\n<li>Fill the detailed application form with personal, educational, and contact details (Part II Registration)</li>\r\n<li>Upload scanned photo, signature, and other required documents</li>\r\n<li>Pay application fee online (₹ 200 for General/OBC/EWS) or select offline payment option</li>\r\n<li>Submit the application form and take a printout for future reference</li>\r\n</ol>\r\n\r\n<h3>Documents Required</h3>\r\n<ul>\r\n<li>10th Mark Sheet & Certificate (for date of birth proof)</li>\r\n<li>12th Mark Sheet & Certificate</li>\r\n<li>Graduation Degree Certificate & Mark Sheets (all semesters/years)</li>\r\n<li>Recent Passport Size Photograph (10-50 KB, JPEG format)</li>\r\n<li>Signature (10-20 KB, JPEG format)</li>\r\n<li>Caste Certificate (OBC/SC/ST/EWS, if applicable)</li>\r\n<li>PwD Certificate (if applicable)</li>\r\n<li>NCC Certificate (if applicable for bonus marks)</li>\r\n</ul>\r\n\r\n<h3>Important Information</h3>\r\n<ul>\r\n<li><strong>Marital Status (IMA/INA/AFA):</strong> Only unmarried male candidates are eligible</li>\r\n<li><strong>Marital Status (OTA Men):</strong> Unmarried male candidates only</li>\r\n<li><strong>Marital Status (OTA Women):</strong> Unmarried female candidates, widows without encumbrance, or divorced without encumbrance</li>\r\n<li><strong>Citizenship:</strong> Must be a citizen of India</li>\r\n<li><strong>Number of Attempts:</strong> No limit on attempts (age limit applicable)</li>\r\n<li><strong>Service Commitment (IMA/INA/AFA):</strong> Permanent Commission - Minimum 15-20 years service</li>\r\n<li><strong>Service Commitment (OTA):</strong> Short Service Commission - 10 years extendable to 14 years</li>\r\n</ul>\r\n\r\n<h3>Exam Centers (Major Cities)</h3>\r\n<p>Ahmedabad, Aizawl, Allahabad, Bengaluru, Bareilly, Bhopal, Chandigarh, Chennai, Cuttack, Dehradun, Delhi, Dharwad, Dispur, Gangtok, Hyderabad, Imphal, Itanagar, Jaipur, Jammu, Jorhat, Kochi, Kohima, Kolkata, Leh, Lucknow, Madurai, Mumbai, Nagpur, Panaji, Patna, Port Blair, Raipur, Ranchi, Sambalpur, Shillong, Shimla, Srinagar, Thiruvananthapuram, Tirupati, Udaipur, Vishakhapatnam</p>\r\n\r\n<p><strong>Important Links:</strong><br />\r\n<a href=\"https://upsconline.nic.in/\" target=\"_blank\" rel=\"noopener\">Apply Online (UPSC Website)</a><br />\r\n<a href=\"notifications/upsc_cds_ii_2026_notification.pdf\" target=\"_blank\" rel=\"noopener\">Download Official Notification PDF</a><br />\r\n<a href=\"notifications/upsc_cds_ii_2026_syllabus.pdf\" target=\"_blank\" rel=\"noopener\">Download Syllabus PDF</a><br />\r\n<a href=\"https://upsc.gov.in/\" target=\"_blank\" rel=\"noopener\">UPSC Official Website</a><br />\r\n<a href=\"https://ssb.nic.in/\" target=\"_blank\" rel=\"noopener\">SSB Official Website</a></p>\r\n\r\n<p><strong>Tags:</strong> UPSC CDS 2026, CDS II Recruitment, Combined Defence Service, Indian Military Academy, Indian Naval Academy, Air Force Academy, Officers Training Academy, Defence Jobs, UPSC Exam, SSB Interview, CDS Notification, Sarkari Result</p>', 'Total Vacancies: 451 Posts across IMA (150), INA (45), AFA (36), OTA Men (170), OTA Women (50). Category-wise: General-276, OBC-92, SC-50, ST-33, EWS-40. Vacancies may vary as per organizational requirements.', '2026-07-10', '2026-08-20', '2026-06-17', '2026-06-18', '2026-08-02', '2026-07-10', '2026-10-15', '2027-01-01', '₹ 200/-', '₹ 0/- (Exempted)', '₹ 200/-', 'Online (Net Banking, Credit Card, Debit Card, UPI) OR Offline (Cash at SBI Bank)', NULL, '19 Years', '25 Years', 'SC/ST: 5 years, OBC: 3 years (as per government rules for reserved categories)', NULL, '451', 'Across India (IMA Dehradun, INA Ezhimala, AFA Hyderabad, OTA Chennai & Other Defence Establishments)', 'Bachelor\'s Degree in any discipline from a recognized university. For INA: B.E./B.Tech in any discipline. For AFA: Bachelor\'s Degree with Physics and Mathematics at 10+2 level OR B.E./B.Tech. Final year students can also apply provisionally.', 'NCC Certificate (C Certificate with minimum B Grade) provides bonus marks. Participation in sports at national/international level, extracurricular activities, leadership roles in college, and knowledge of foreign languages are desirable.', 'No prior experience required. Freshers are eligible to apply. Final year graduation students can also apply provisionally.', 'Stage 1: Written Examination (Objective Type - English, GK, Maths) conducted by UPSC\r\nStage 2: SSB Interview (5 days - Screening, Psychological Tests, Group Tasks, Personal Interview, Conference)\r\nStage 3: Medical Examination (Full medical checkup as per defence standards)\r\nStage 4: Final Merit List preparation based on written exam marks + SSB marks + medical fitness + NCC bonus (if applicable)', 'Apply online through official UPSC website (upsconline.nic.in) from 28 May 2026 to 17 June 2026. Complete Part I & Part II registration, upload documents, pay fee (₹ 200 for General/OBC/EWS, free for SC/ST/Female), submit form, and take printout for future reference.', 'https://upsconline.nic.in/', 'https://upsconline.nic.in/', 'https://upsconline.nic.in/', 'https://upsconline.nic.in/', 'https://upsc.gov.in/', 'https://upsc.gov.in/', 'https://upsc.gov.in/', 'https://upsc.gov.in/', NULL, NULL, NULL, 'UPSC CDS II Recruitment 2026 - Apply Online for 451 Defence Posts', 'UPSC Combined Defence Service (CDS) II Examination 2026. Total 451 vacancies in IMA, INA, AFA & OTA. Eligibility: Graduate in any discipline. Age: 19-25 years. Fee: ₹200/- (SC/ST/Female exempted). Apply online from 28 May to 17 June 2026. Exam date: 02 August 2026.', 'UPSC CDS 2026, CDS II Recruitment, Combined Defence Service, UPSC CDS Notification, Indian Military Academy, Indian Naval Academy, Air Force Academy, Officers Training Academy, Defence Jobs 2026, UPSC Exam, SSB Interview, Army Jobs, Navy Jobs, Air Force Jobs, OTA Chennai, IMA Dehradun, Sarkari Result', 1, 0, 71, '2026-05-27 19:06:38', '2026-07-31 01:46:28'),
(33, 'UPSC NDA & NA II Recruitment 2026', 'upsc-nda-na-ii-recruitment-2026', 3, 'UPSC NDA & NA II Recruitment 2026 for 394 vacancies in Indian Army, Navy, and Air Force. Apply online from 28 May to 17 June 2026. Eligibility: 10+2 (Intermediate) pass. Age limit: 16.5 to 19.5 years. Only unmarried male candidates can apply.', '<h2>UPSC National Defence Academy (NDA) & Naval Academy (NA) II Examination 2026</h2>\r\n<p>The <strong>Union Public Service Commission (UPSC)</strong> has released the official notification for the <strong>National Defence Academy (NDA) & Naval Academy (NA) II Examination 2026</strong>. This examination is conducted twice a year for recruitment into the Army, Navy, and Air Force wings of the National Defence Academy (NDA) and Indian Naval Academy (INA).</p>\r\n\r\n<h3>Important Dates</h3>\r\n<ul>\r\n<li><strong>Application Start Date:</strong> 28 May 2026</li>\r\n<li><strong>Last Date to Apply Online:</strong> 17 June 2026</li>\r\n<li><strong>Last Date for Fee Payment:</strong> 17 June 2026</li>\r\n<li><strong>Application Correction Date:</strong> 18-24 June 2026</li>\r\n<li><strong>Admit Card Release Date:</strong> 3-4 weeks before exam</li>\r\n<li><strong>Written Exam Date:</strong> 06 September 2026</li>\r\n<li><strong>Result Date (Written):</strong> November 2026</li>\r\n<li><strong>SSB Interview Dates:</strong> December 2026 to April 2027</li>\r\n<li><strong>Final Result Date:</strong> May 2027</li>\r\n<li><strong>Training Start Date:</strong> July 2027</li>\r\n</ul>\r\n\r\n<h3>Application Fee</h3>\r\n<ul>\r\n<li><strong>General / OBC / EWS:</strong> ₹ 100/-</li>\r\n<li><strong>SC / ST / PwD / Sons of JCOs/NCOs/Ors:</strong> ₹ 0/- (Exempted)</li>\r\n<li><strong>Payment Mode:</strong> Online (Net Banking, Credit Card, Debit Card, UPI) or Offline (Cash at SBI Bank)</li>\r\n</ul>\r\n\r\n<h3>Age Limit (as on 01 July 2027)</h3>\r\n<ul>\r\n<li><strong>Minimum Age:</strong> 16.5 Years (16 Years 6 Months)</li>\r\n<li><strong>Maximum Age:</strong> 19.5 Years (19 Years 6 Months)</li>\r\n<li><strong>Born Between:</strong> 02 January 2008 to 01 July 2010</li>\r\n<li><strong>Age Relaxation:</strong> No relaxation for any category (strict age limit)</li>\r\n</ul>\r\n\r\n<h3>Educational Qualification</h3>\r\n<h4>For Army Wing of NDA:</h4>\r\n<ul>\r\n<li>10+2 (Intermediate) pass in any stream from a recognized board</li>\r\n<li>OR equivalent examination recognized by the government</li>\r\n<li>Candidates appearing in 10+2 examination can also apply provisionally</li>\r\n</ul>\r\n\r\n<h4>For Air Force & Naval Wings of NDA and for Naval Academy (10+2 Cadet Entry Scheme):</h4>\r\n<ul>\r\n<li>10+2 (Intermediate) pass with <strong>Physics, Chemistry, and Mathematics (PCM)</strong> subjects from a recognized board</li>\r\n<li>Minimum <strong>60% marks</strong> in PCM for Navy and Air Force</li>\r\n<li>Candidates appearing in 10+2 examination can also apply provisionally</li>\r\n</ul>\r\n\r\n<h4>Minimum Marks Required:</h4>\r\n<ul>\r\n<li><strong>Army Wing:</strong> Pass class (No minimum percentage required)</li>\r\n<li><strong>Navy & Air Force:</strong> Minimum 60% aggregate marks in PCM</li>\r\n<li><strong>SC/ST Candidates:</strong> Pass class (No minimum percentage required for Army Wing only)</li>\r\n</ul>\r\n\r\n<h3>Vacancy Details</h3>\r\n<p><strong>Total Posts:</strong> 394</p>\r\n\r\n<h4>Academy-wise Vacancy Breakup:</h4>\r\n<ul>\r\n<li><strong>National Defence Academy (NDA), Khadakwasla:</strong> 304 Posts</li>\r\n<li>• Army Wing: 208 Posts (193 General + 15 Reserved)</li>\r\n<li>• Navy Wing: 42 Posts (38 General + 4 Reserved)</li>\r\n<li>• Air Force Wing: 54 Posts (48 General + 6 Reserved)</li>\r\n<li><strong>Naval Academy (NA), Ezhimala (10+2 Cadet Entry Scheme):</strong> 90 Posts (85 General + 5 Reserved)</li>\r\n</ul>\r\n\r\n<h4>Category-wise Vacancy Breakdown (Total 394):</h4>\r\n<ul>\r\n<li>General (UR): 180 Posts</li>\r\n<li>OBC: 106 Posts</li>\r\n<li>SC: 59 Posts</li>\r\n<li>ST: 29 Posts</li>\r\n<li>EWS: 20 Posts</li>\r\n</ul>\r\n\r\n<p><strong>Job Location:</strong> National Defence Academy (NDA), Khadakwasla, Pune & Indian Naval Academy (INA), Ezhimala, Kerala</p>\r\n\r\n<h3>Exam Pattern</h3>\r\n<h4>For NDA (Army, Navy, Air Force) - Paper I & II:</h4>\r\n<ul>\r\n<li><strong>Paper I - Mathematics:</strong> 120 Questions, 300 Marks, 2.5 Hours</li>\r\n<li><strong>Paper II - General Ability Test (GAT):</strong> 150 Questions, 600 Marks, 2.5 Hours</li>\r\n<li><strong>Total Marks:</strong> 900 Marks</li>\r\n<li><strong>Total Duration:</strong> 5 Hours (2 Papers)</li>\r\n<li><strong>Negative Marking:</strong> 1/3 mark deduction for each wrong answer</li>\r\n</ul>\r\n\r\n<h4>Paper I - Mathematics Syllabus:</h4>\r\n<ul>\r\n<li>Algebra, Matrices & Determinants, Trigonometry</li>\r\n<li>Calculus, Vector Algebra, Statistics & Probability</li>\r\n<li>Analytical Geometry (2D & 3D), Differential Equations</li>\r\n<li>Complex Numbers, Quadratic Equations, Binomial Theorem</li>\r\n<li>Permutation & Combination, Sequences & Series</li>\r\n</ul>\r\n\r\n<h4>Paper II - General Ability Test (GAT) Syllabus:</h4>\r\n<ul>\r\n<li><strong>Part A - English (200 Marks):</strong> Grammar, Vocabulary, Comprehension, Spotting Errors, Sentence Improvement, Synonyms/Antonyms, Idioms & Phrases, Cloze Test</li>\r\n<li><strong>Part B - General Knowledge (400 Marks):</strong></li>\r\n<li>• Physics, Chemistry, Biology (Basic Concepts)</li>\r\n<li>• History of India (Ancient, Medieval, Modern)</li>\r\n<li>• Geography (Physical, Political, Economic)</li>\r\n<li>• Indian Polity & Constitution</li>\r\n<li>• Indian Economy</li>\r\n<li>• Current Events (National & International)</li>\r\n<li>• Defence & Security related news</li>\r\n<li>• Sports, Awards, Books & Authors, Important Days</li>\r\n<li>• General Science & Technology</li>\r\n<li>• Environment & Ecology</li>\r\n</ul>\r\n\r\n<h3>Selection Process</h3>\r\n<p>The selection will be based on the following stages:</p>\r\n<ol>\r\n<li><strong>Written Examination (Objective Type):</strong> Conducted by UPSC across various centers in India</li>\r\n<li><strong>SSB Interview (Services Selection Board):</strong> 5-day selection process for candidates who qualify written exam</li>\r\n<li><strong>Medical Examination:</strong> Thorough medical checkup as per defence standards</li>\r\n<li><strong>Final Merit List:</strong> Based on written exam marks + SSB marks + medical fitness</li>\r\n</ol>\r\n\r\n<h3>SSB Interview Details</h3>\r\n<p>The SSB Interview is a 5-day process conducted at various SSB centers across India (Allahabad, Bhopal, Bangalore, Coimbatore, Gandhinagar, Kapurthala, Mysore, Visakhapatnam):</p>\r\n\r\n<h4>Day 1 (Screening Test):</h4>\r\n<ul>\r\n<li>OIR Test (Officer Intelligence Rating) - Verbal & Non-Verbal Reasoning</li>\r\n<li>PPDT (Picture Perception & Discussion Test) - 30 seconds to observe picture + 4 minutes to write story + group discussion</li>\r\n<li>Result declaration (Screened In/Screened Out)</li>\r\n</ul>\r\n\r\n<h4>Day 2 (Psychological Tests):</h4>\r\n<ul>\r\n<li>TAT (Thematic Apperception Test) - 12 pictures + 1 blank slide</li>\r\n<li>WAT (Word Association Test) - 60 words, 15 seconds each</li>\r\n<li>SRT (Situation Reaction Test) - 60 situations, 30 seconds each</li>\r\n<li>SDT (Self Description Test) - 5 questions about yourself</li>\r\n</ul>\r\n\r\n<h4>Day 3 & 4 (Group Tasks - GTO):</h4>\r\n<ul>\r\n<li>GD (Group Discussion) - Current topics</li>\r\n<li>GPE (Group Planning Exercise) - Outdoor/Indoor planning</li>\r\n<li>PGT (Progressive Group Task) - Outdoor obstacle tasks</li>\r\n<li>HGT (Half Group Task) - Smaller group tasks</li>\r\n<li>IOT (Individual Obstacles) - 10 obstacles to complete</li>\r\n<li>Command Task - Leading a group</li>\r\n<li>Lecturette - 3 minutes speech on given topic</li>\r\n</ul>\r\n\r\n<h4>Day 4 (Personal Interview):</h4>\r\n<ul>\r\n<li>Detailed interview with the board members</li>\r\n<li>Questions on personal background, academics, GK, current affairs, defence awareness</li>\r\n<li>Confidence, communication skills, and personality assessment</li>\r\n</ul>\r\n\r\n<h4>Day 5 (Conference):</h4>\r\n<ul>\r\n<li>Final assessment by all board members</li>\r\n<li>Result declaration (Recommended/Not Recommended)</li>\r\n</ul>\r\n\r\n<h3>Physical Standards</h3>\r\n<ul>\r\n<li><strong>Height (Male):</strong> Minimum 152 cms (157 cms for Air Force)</li>\r\n<li><strong>Weight:</strong> Proportionate to height and age</li>\r\n<li><strong>Chest (Male):</strong> Minimum expansion of 5 cms (Fully expanded: 77 cms minimum)</li>\r\n<li><strong>Eye Sight:</strong></li>\r\n<li>• Army: 6/12 (without glasses), correctable to 6/6</li>\r\n<li>• Navy: 6/12 (without glasses), correctable to 6/6</li>\r\n<li>• Air Force: 6/6 (without glasses) - No correction allowed</li>\r\n<li><strong>BMI:</strong> Within normal range (18-24)</li>\r\n<li><strong>No Color Blindness, No Night Blindness</strong></li>\r\n<li><strong>No Tattoos (except traditional permanent tattoos on inner forearm or back of hand)</strong></li>\r\n<li><strong>No Flat Foot, No Knock Knees, No Bow Legs</strong></li>\r\n<li><strong>Dental:</strong> Minimum 14 dental points (healthy teeth and gums)</li>\r\n</ul>\r\n\r\n<h3>Training Details</h3>\r\n<ul>\r\n<li><strong>NDA Training Duration:</strong> 3 Years (Bachelor\'s Degree in Arts/Science/Computer Science)</li>\r\n<li><strong>NA Training Duration:</strong> 4 Years B.Tech Course</li>\r\n<li><strong>Training Location:</strong> National Defence Academy (NDA), Khadakwasla, Pune & Indian Naval Academy (INA), Ezhimala, Kerala</li>\r\n<li><strong>Degree Awarded:</strong> Bachelor\'s Degree from Jawaharlal Nehru University (JNU) for NDA; B.Tech from JNU for Naval Academy</li>\r\n<li><strong>Stipend During Training:</strong> ₹ 56,100/- per month</li>\r\n<li><strong>After Commission:</strong> Level 10 (₹ 61,300 - ₹ 1,93,100) with MSP ₹ 15,500/-</li>\r\n</ul>\r\n\r\n<h3>Salary & Benefits</h3>\r\n<ul>\r\n<li><strong>Stipend during Training (NDA/NA):</strong> ₹ 56,100/- per month</li>\r\n<li><strong>After Commission (Level 10):</strong> ₹ 61,300 - ₹ 1,93,100</li>\r\n<li><strong>Military Service Pay (MSP):</strong> ₹ 15,500/- per month</li>\r\n<li><strong>Dearness Allowance (DA):</strong> As per government norms (currently 50%)</li>\r\n<li><strong>Free Accommodation:</strong> Government quarters/Single accommodation provided</li>\r\n<li><strong>Medical Facilities:</strong> Free medical treatment for self and dependents</li>\r\n<li><strong>Leave:</strong> 60 days annual leave + 20 days casual leave + 30 days sick leave</li>\r\n<li><strong>Other Allowances:</strong> Flying Allowance (for Air Force), Submarine Allowance (for Navy), Sea Duty Allowance, Field Area Allowance, High Altitude Allowance, etc.</li>\r\n<li><strong>Retirement Benefits:</strong> Pension, Gratuity, and other post-retirement benefits</li>\r\n</ul>\r\n\r\n<h3>How to Apply for UPSC NDA & NA II 2026</h3>\r\n<p>Candidates can apply online through the official UPSC website. Follow these steps:</p>\r\n<ol>\r\n<li>Visit the official UPSC website: <strong>https://upsconline.nic.in</strong></li>\r\n<li>Click on \"Online Application for Various Examinations\"</li>\r\n<li>Select \"National Defence Academy & Naval Academy Examination (NDA) II 2026\"</li>\r\n<li>Register with your email ID and mobile number (Part I Registration)</li>\r\n<li>Fill the detailed application form with personal, educational, and contact details (Part II Registration)</li>\r\n<li>Upload scanned photo, signature, and other required documents</li>\r\n<li>Pay application fee online (₹ 100 for General/OBC/EWS) or select offline payment option</li>\r\n<li>Submit the application form and take a printout for future reference</li>\r\n</ol>\r\n\r\n<h3>Documents Required</h3>\r\n<ul>\r\n<li>10th Mark Sheet & Certificate (for date of birth proof)</li>\r\n<li>10+2 (Intermediate) Mark Sheet & Certificate (for appearing candidates - provisional certificate)</li>\r\n<li>Recent Passport Size Photograph (10-50 KB, JPEG format)</li>\r\n<li>Signature (10-20 KB, JPEG format)</li>\r\n<li>Caste Certificate (OBC/SC/ST/EWS, if applicable)</li>\r\n<li>PwD Certificate (if applicable)</li>\r\n<li>NCC Certificate (if applicable for bonus marks)</li>\r\n<li>Sons of JCOs/NCOs/Ors Certificate (for fee exemption, if applicable)</li>\r\n</ul>\r\n\r\n<h3>Important Information</h3>\r\n<ul>\r\n<li><strong>Marital Status:</strong> Only unmarried male candidates are eligible</li>\r\n<li><strong>Citizenship:</strong> Must be a citizen of India</li>\r\n<li><strong>Number of Attempts:</strong> No limit on attempts (age limit applicable)</li>\r\n<li><strong>Service Commitment:</strong> Permanent Commission - Minimum 15-20 years service</li>\r\n<li><strong>Bonus Marks:</strong> NCC Certificate holders (Air Wing/Senior Division) are given bonus marks in SSB</li>\r\n<li><strong>Physical Fitness:</strong> Candidates must be physically fit for training as per defence standards</li>\r\n</ul>\r\n\r\n<h3>Exam Centers (Major Cities)</h3>\r\n<p>Agartala, Ahmedabad, Aizawl, Aligarh, Allahabad, Bangalore, Bareilly, Bhopal, Chandigarh, Chennai, Coimbatore, Cuttack, Dehradun, Delhi, Dharwad, Dispur, Gangtok, Gwalior, Hyderabad, Imphal, Itanagar, Jaipur, Jammu, Jodhpur, Jorhat, Kochi, Kohima, Kolkata, Leh, Lucknow, Madurai, Mumbai, Mysore, Nagpur, Panaji, Patna, Port Blair, Raipur, Ranchi, Sambalpur, Shillong, Shimla, Srinagar, Thiruvananthapuram, Tiruchirappalli, Tirupati, Udaipur, Varanasi, Vijayawada, Visakhapatnam</p>\r\n\r\n<h3>Tips for Preparation</h3>\r\n<ul>\r\n<li><strong>Mathematics:</strong> Focus on NCERT textbooks (Class 11 & 12), solve previous year papers</li>\r\n<li><strong>English:</strong> Read newspapers daily, practice grammar and vocabulary</li>\r\n<li><strong>General Knowledge:</strong> Study NCERTs (Class 6-12), follow current affairs for 6-8 months</li>\r\n<li><strong>SSB Preparation:</strong> Join mock SSB sessions, practice group discussions, improve communication skills</li>\r\n<li><strong>Physical Fitness:</strong> Regular running, push-ups, sit-ups, swimming (especially for Navy & Air Force aspirants)</li>\r\n</ul>\r\n\r\n<p><strong>Important Links:</strong><br />\r\n<a href=\"https://upsconline.nic.in/\" target=\"_blank\" rel=\"noopener\">Apply Online (UPSC Website)</a><br />\r\n<a href=\"notifications/upsc_nda_ii_2026_notification.pdf\" target=\"_blank\" rel=\"noopener\">Download Official Notification PDF</a><br />\r\n<a href=\"notifications/upsc_nda_ii_2026_syllabus.pdf\" target=\"_blank\" rel=\"noopener\">Download Syllabus PDF</a><br />\r\n<a href=\"https://upsc.gov.in/\" target=\"_blank\" rel=\"noopener\">UPSC Official Website</a><br />\r\n<a href=\"https://nda.nic.in/\" target=\"_blank\" rel=\"noopener\">NDA Official Website</a></p>\r\n\r\n<p><strong>Tags:</strong> UPSC NDA 2026, NDA II Recruitment, National Defence Academy, NDA Exam, Naval Academy, Army Jobs, Navy Jobs, Air Force Jobs, Defence Jobs, UPSC Exam, SSB Interview, NDA Notification, 10+2 Pass Jobs, Sarkari Result</p>', 'Total Vacancies: 394 Posts across NDA (304) and Naval Academy (90). Academy-wise: NDA Army Wing-208, NDA Navy Wing-42, NDA Air Force Wing-54, Naval Academy-90. Category-wise: General-180, OBC-106, SC-59, ST-29, EWS-20. Vacancies may vary as per organizational requirements.', '2026-07-10', '2026-08-20', '2026-06-17', '2026-06-18', '2026-09-06', '2026-08-15', '2026-11-15', '2027-07-01', '₹ 100/-', '₹ 0/- (Exempted)', '₹ 100/-', 'Online (Net Banking, Credit Card, Debit Card, UPI) OR Offline (Cash at SBI Bank)', NULL, '16.5 Years', '19.5 Years', 'No relaxation for any category. Born between 02 January 2008 to 01 July 2010 only.', NULL, '394', 'National Defence Academy (NDA), Khadakwasla, Pune (Maharashtra) & Indian Naval Academy (INA), Ezhimala, Kerala', 'For Army Wing: 10+2 (Intermediate) pass in any stream from recognized board. For Navy & Air Force Wing and Naval Academy: 10+2 (Intermediate) pass with Physics, Chemistry, Mathematics (PCM) with minimum 60% aggregate marks. Candidates appearing in 10+2 can also apply provisionally.', 'NCC Certificate (Senior Division/Air Wing) with minimum B Grade provides bonus marks in SSB interview. Participation in sports at national/international level, extracurricular activities, leadership roles in school, and swimming proficiency (for Navy & Air Force) are desirable.', 'No prior experience required. Freshers and 10+2 appearing candidates are eligible to apply.', 'Stage 1: Written Examination (Objective Type - Mathematics 300 Marks + GAT 600 Marks = 900 Marks) conducted by UPSC\r\nStage 2: SSB Interview (5 days - Screening, Psychological Tests, Group Tasks, Personal Interview, Conference)\r\nStage 3: Medical Examination (Full medical checkup as per defence standards)\r\nStage 4: Final Merit List preparation based on written exam marks + SSB marks + medical fitness + NCC bonus (if applicable)', 'Apply online through official UPSC website (upsconline.nic.in) from 28 May 2026 to 17 June 2026. Complete Part I & Part II registration, upload documents (photo, signature), pay fee (₹ 100 for General/OBC/EWS, free for SC/ST), submit form, and take printout for future reference.', 'https://upsconline.nic.in/', 'https://upsconline.nic.in/', 'https://upsconline.nic.in/', 'https://upsconline.nic.in/', 'https://upsc.gov.in/', 'https://upsc.gov.in/', 'https://upsc.gov.in/', 'https://upsc.gov.in/', NULL, NULL, NULL, 'UPSC NDA & NA II Recruitment 2026 - Apply Online for 394 Posts', 'UPSC National Defence Academy (NDA) & Naval Academy (NA) II Examination 2026. Total 394 vacancies in Army, Navy & Air Force. Eligibility: 10+2 pass. Age: 16.5-19.5 years. Fee: ₹100/- (SC/ST exempted). Apply online from 28 May to 17 June 2026. Exam date: 06 September 2026.', 'UPSC NDA 2026, NDA II Recruitment, National Defence Academy, Naval Academy, NDA Exam, NDA Notification, Army Jobs, Navy Jobs, Air Force Jobs, Defence Jobs 2026, UPSC Exam, SSB Interview, NDA Khadakwasla, INA Ezhimala, 10+2 Pass Jobs, Officer Entry, Permanent Commission, Sarkari Result', 1, 0, 76, '2026-05-27 19:08:29', '2026-07-31 01:46:28');
INSERT INTO `jobs` (`id`, `title`, `slug`, `category_id`, `short_description`, `description`, `vacancy_details`, `start_date`, `last_date`, `fee_last_date`, `correction_date`, `exam_date`, `admit_card_date`, `result_date`, `age_calculation_date`, `fee_general`, `fee_sc_st_female`, `fee_other`, `payment_mode`, `application_fee`, `min_age`, `max_age`, `age_relaxation`, `age_limit`, `total_post`, `job_location`, `qualification`, `additional_qualification`, `experience_required`, `selection_process`, `how_to_apply`, `application_link`, `registration_link`, `login_link`, `admit_card_link`, `result_link`, `answer_key_link`, `syllabus_link`, `official_website`, `notification_pdf`, `short_notification_pdf`, `syllabus_pdf`, `meta_title`, `meta_description`, `meta_keywords`, `is_active`, `is_featured`, `views`, `created_at`, `updated_at`) VALUES
(34, 'Indian Airforce AFCAT 02/2026 Batch Recruitment 2026', 'indian-airforce-afcat-02-2026-batch-recruitment-2026', 7, 'Indian Air Force AFCAT 02/2026 Batch Recruitment for Commissioned Officer posts. Apply online for 300+ vacancies in Flying Branch and Ground Duty (Technical & Non-Technical). Registration starts 20 May to 19 June 2026. Exam on 08 August 2026.', '<h2>Indian Air Force AFCAT 02/2026 Batch Recruitment 2026</h2>\r\n<p>The <strong>Indian Air Force (IAF)</strong> has released the official notification for the <strong>Air Force Common Admission Test (AFCAT) 02/2026 Batch</strong>. This recruitment drive offers a prestigious opportunity for both male and female candidates to join the Indian Air Force as Group \'A\' Gazetted Officers in Flying Branch and Ground Duty (Technical & Non-Technical) branches. Courses will commence in July 2027 at Air Force Training Establishments. [citation:2][citation:9]</p>\r\n\r\n<h3>Important Dates</h3>\r\n<ul>\r\n<li><strong>Notification Release Date:</strong> 12 May 2026 [citation:7][citation:10]</li>\r\n<li><strong>Application Start Date:</strong> 20 May 2026 (11:00 AM) [citation:1][citation:4]</li>\r\n<li><strong>Last Date to Apply Online:</strong> 19 June 2026 (11:30 PM) [citation:2][citation:6]</li>\r\n<li><strong>Last Date for Fee Payment:</strong> 19 June 2026</li>\r\n<li><strong>Admit Card Release Date:</strong> 04 August 2026 [citation:2]</li>\r\n<li><strong>AFCAT Written Exam Date:</strong> 08 August 2026 (Saturday) [citation:2][citation:8]</li>\r\n<li><strong>Result Date:</strong> October/November 2026</li>\r\n<li><strong>AFSB Interview Dates:</strong> September 2026 to March 2027</li>\r\n<li><strong>Course Commencement:</strong> July 2027 [citation:1][citation:3]</li>\r\n</ul>\r\n\r\n<h3>Application Fee</h3>\r\n<ul>\r\n<li><strong>AFCAT Entry (General / OBC / EWS):</strong> ₹ 550/- + GST [citation:1][citation:7]</li>\r\n<li><strong>SC / ST / PwD (AFCAT Entry):</strong> ₹ 550/- + GST</li>\r\n<li><strong>NCC Special Entry (Flying Branch):</strong> ₹ 0/- (No Fee) [citation:1][citation:6]</li>\r\n<li><strong>GATE Score Entry (Ground Duty Technical):</strong> ₹ 0/- (No Fee) [citation:2][citation:9]</li>\r\n<li><strong>Payment Mode:</strong> Online (Net Banking, Credit Card, Debit Card, UPI) [citation:6]</li>\r\n</ul>\r\n\r\n<h3>Age Limit (as on 01 July 2027) [citation:5][citation:7]</h3>\r\n<ul>\r\n<li><strong>Flying Branch:</strong> 20 to 24 Years (Born between 02 July 2003 to 01 July 2007)</li>\r\n<li><strong>Flying Branch (CPL Holders):</strong> 20 to 26 Years (Born between 02 July 2001 to 01 July 2007) [citation:1]</li>\r\n<li><strong>Ground Duty (Technical & Non-Technical):</strong> 20 to 26 Years (Born between 02 July 2001 to 01 July 2007)</li>\r\n<li><strong>Age Relaxation:</strong> As per government rules for SC/ST/OBC candidates (5 years for SC/ST, 3 years for OBC)</li>\r\n</ul>\r\n\r\n<h3>Educational Qualification</h3>\r\n<h4>For Flying Branch:</h4>\r\n<ul>\r\n<li>Bachelor\'s Degree in any discipline from a recognized university with minimum <strong>60% marks</strong> [citation:1]</li>\r\n<li>Must have studied <strong>Physics and Mathematics</strong> at 10+2 level</li>\r\n<li>Final year students can also apply provisionally</li>\r\n</ul>\r\n\r\n<h4>For Ground Duty (Technical Branch):</h4>\r\n<ul>\r\n<li><strong>Aeronautical Engineering (Mechanical):</strong> B.E./B.Tech in Mechanical Engineering, Aeronautical Engineering, or related field with minimum 60% marks [citation:1][citation:4]</li>\r\n<li><strong>Aeronautical Engineering (Electronics):</strong> B.E./B.Tech in Electronics Engineering, Electrical Engineering, Computer Science, or related field with minimum 60% marks</li>\r\n<li>Candidates with valid <strong>GATE Score</strong> can apply under GATE Score Entry (No AFCAT exam required) [citation:2][citation:9]</li>\r\n</ul>\r\n\r\n<h4>For Ground Duty (Non-Technical Branch):</h4>\r\n<ul>\r\n<li><strong>Administration & Logistics:</strong> Bachelor\'s Degree in any discipline with minimum 60% marks [citation:1]</li>\r\n<li><strong>Accounts:</strong> Bachelor\'s Degree in Commerce (B.Com) with minimum 60% marks</li>\r\n<li><strong>Education:</strong> M.A./M.Sc in English, Physics, Mathematics, Chemistry, Statistics, International Relations, International Studies, Psychology, Computer Science, or Political Science with minimum 50% marks</li>\r\n<li><strong>Meteorology:</strong> M.Sc in Physics, Mathematics, Chemistry, Statistics, Geophysics, or Meteorology with minimum 50% marks</li>\r\n<li><strong>Weapon Systems (WS):</strong> B.E./B.Tech in any discipline or Bachelor\'s Degree with Physics and Mathematics at 10+2 level</li>\r\n</ul>\r\n\r\n<h3>Vacancy Details [citation:1][citation:3][citation:8]</h3>\r\n<p><strong>Total Posts:</strong> 304+ (Approximately 379 including all entries)</p>\r\n\r\n<h4>Branch-wise Vacancy Breakup (AFCAT Entry):</h4>\r\n<ul>\r\n<li><strong>Flying Branch (SSC):</strong> 35 Posts (Men: 30, Women: 5) [citation:8]</li>\r\n<li><strong>Ground Duty (Technical):</strong> 211 Posts (Men - AE: 10 PC + 159 SSC, Women - AE: 04 PC + 38 SSC) [citation:8]</li>\r\n<li><strong>Ground Duty (Non-Technical):</strong> 107 Posts (Men: 82 SSC, Women: 25 SSC) [citation:8]</li>\r\n</ul>\r\n\r\n<h4>Additional Entries:</h4>\r\n<ul>\r\n<li><strong>NCC Special Entry (Flying):</strong> 10% of CDSE Permanent Commission and SSC AFCAT vacancies [citation:8]</li>\r\n<li><strong>GATE Score Entry (Ground Duty Technical):</strong> 26 Posts (Men - AE: 02 PC + 18 SSC, Women - AE: 02 PC + 04 SSC) [citation:8]</li>\r\n</ul>\r\n\r\n<p><strong>Job Location:</strong> Across India (Various Air Force Stations & Training Establishments)</p>\r\n\r\n<h3>Exam Pattern (AFCAT Written Exam) [citation:6]</h3>\r\n<ul>\r\n<li><strong>Mode of Exam:</strong> Online Computer Based Test (CBT) [citation:2]</li>\r\n<li><strong>Duration:</strong> 2 Hours</li>\r\n<li><strong>Total Questions:</strong> 100 Questions</li>\r\n<li><strong>Total Marks:</strong> 300 Marks</li>\r\n<li><strong>Negative Marking:</strong> 1/3 mark deduction for each wrong answer (0.33 marks per incorrect answer) [citation:9]</li>\r\n</ul>\r\n\r\n<h4>Syllabus Subjects:</h4>\r\n<ul>\r\n<li>General Awareness (Current Affairs, History, Geography, Polity, Economics, Defence)</li>\r\n<li>Verbal Ability in English (Grammar, Vocabulary, Comprehension, Synonyms/Antonyms, Sentence Completion)</li>\r\n<li>Numerical Ability (Arithmetic, Algebra, Geometry, Mensuration, Data Interpretation)</li>\r\n<li>Reasoning & Military Aptitude (Verbal & Non-Verbal Reasoning, Spatial Ability, Decision Making)</li>\r\n</ul>\r\n\r\n<h3>Selection Process [citation:1][citation:6]</h3>\r\n<p>The selection will be based on the following stages:</p>\r\n<ol>\r\n<li><strong>Online Written Examination (AFCAT):</strong> Conducted by Indian Air Force on 08 August 2026 [citation:2]</li>\r\n<li><strong>AFSB Interview (Air Force Selection Board):</strong> 5-day selection process for candidates who qualify written exam</li>\r\n<li><strong>CPSS Test (for Flying Branch only):</strong> Computerized Pilot Selection System Test [citation:1]</li>\r\n<li><strong>Medical Examination:</strong> Thorough medical checkup as per IAF standards</li>\r\n<li><strong>Document Verification</strong></li>\r\n<li><strong>Final Merit List:</strong> Based on AFCAT score + AFSB marks + medical fitness</li>\r\n</ol>\r\n\r\n<h3>AFSB Interview Details</h3>\r\n<p>The AFSB Interview is a 5-day process conducted at various AFSB centers across India (Dehradun, Mysore, Gandhinagar, Varanasi):</p>\r\n\r\n<h4>Day 1 (Screening Test):</h4>\r\n<ul>\r\n<li>OIR Test (Officer Intelligence Rating)</li>\r\n<li>PPDT (Picture Perception & Discussion Test)</li>\r\n<li>Result declaration (Screened In/Screened Out)</li>\r\n</ul>\r\n\r\n<h4>Day 2 (Psychological Tests):</h4>\r\n<ul>\r\n<li>TAT (Thematic Apperception Test)</li>\r\n<li>WAT (Word Association Test)</li>\r\n<li>SRT (Situation Reaction Test)</li>\r\n<li>SDT (Self Description Test)</li>\r\n</ul>\r\n\r\n<h4>Day 3 & 4 (Group Tasks - GTO):</h4>\r\n<ul>\r\n<li>GD (Group Discussion)</li>\r\n<li>GPE (Group Planning Exercise)</li>\r\n<li>PGT (Progressive Group Task)</li>\r\n<li>HGT (Half Group Task)</li>\r\n<li>IOT (Individual Obstacles)</li>\r\n<li>Command Task</li>\r\n<li>Lecturette</li>\r\n</ul>\r\n\r\n<h4>Day 4 (Personal Interview):</h4>\r\n<ul>\r\n<li>Detailed interview with the board members</li>\r\n</ul>\r\n\r\n<h4>Day 5 (Conference):</h4>\r\n<ul>\r\n<li>Final assessment and result declaration</li>\r\n</ul>\r\n\r\n<h3>Physical & Medical Standards</h3>\r\n<ul>\r\n<li><strong>Height (Male):</strong> Minimum 152 cms (157 cms for Flying Branch)</li>\r\n<li><strong>Height (Female):</strong> Minimum 148 cms (152 cms for Flying Branch)</li>\r\n<li><strong>Weight:</strong> Proportionate to height and age</li>\r\n<li><strong>Chest (Male):</strong> Minimum expansion of 5 cms</li>\r\n<li><strong>Eye Sight (Flying Branch):</strong> 6/6 in both eyes (without glasses) - No color blindness</li>\r\n<li><strong>Eye Sight (Ground Duty):</strong> 6/12 correctable to 6/6</li>\r\n<li><strong>BMI:</strong> Within normal range (18-24)</li>\r\n<li><strong>No Color Blindness, No Night Blindness</strong></li>\r\n<li><strong>No Tattoos (except traditional permanent tattoos on inner forearm or back of hand)</strong></li>\r\n<li><strong>No Flat Foot, No Knock Knees, No Bow Legs</strong></li>\r\n<li><strong>Dental:</strong> Healthy teeth and gums</li>\r\n<li><strong>Visual Acuity:</strong> Candidates must not have any degree of squint or color blindness</li>\r\n</ul>\r\n\r\n<h3>Training Details</h3>\r\n<ul>\r\n<li><strong>Flying Branch Training:</strong> 74 weeks at Air Force Academy, Dundigal (Hyderabad)</li>\r\n<li><strong>Ground Duty Technical Training:</strong> 52 weeks at Air Force Technical College, Bangalore / Air Force Station, Tambaram</li>\r\n<li><strong>Ground Duty Non-Technical Training:</strong> 26-52 weeks at Air Force Academy, Dundigal / Air Force Administrative College, Coimbatore</li>\r\n<li><strong>Stipend During Training:</strong> ₹ 56,100/- per month [citation:10]</li>\r\n<li><strong>Degree Awarded:</strong> Post Graduate Diploma in Defence Management / M.Tech (for Technical Branch)</li>\r\n</ul>\r\n\r\n<h3>Salary & Benefits [citation:3]</h3>\r\n<ul>\r\n<li><strong>Stipend during Training:</strong> ₹ 56,100/- per month</li>\r\n<li><strong>After Commission (Level 10):</strong> ₹ 61,300 - ₹ 1,93,100 [citation:10]</li>\r\n<li><strong>Military Service Pay (MSP):</strong> ₹ 15,500/- per month</li>\r\n<li><strong>Dearness Allowance (DA):</strong> As per government norms (currently 50%)</li>\r\n<li><strong>Free Accommodation:</strong> Government quarters provided</li>\r\n<li><strong>Medical Facilities:</strong> Free medical treatment for self and dependents</li>\r\n<li><strong>Leave:</strong> 60 days annual leave + 20 days casual leave + 30 days sick leave</li>\r\n<li><strong>Flying Allowance (for Flying Branch):</strong> Additional ₹ 25,000 - ₹ 30,000 per month</li>\r\n<li><strong>Technical Allowance (for Technical Branch):</strong> Additional ₹ 15,000 - ₹ 20,000 per month</li>\r\n<li><strong>Other Allowances:</strong> Field Area Allowance, High Altitude Allowance, Hard Area Allowance, etc.</li>\r\n<li><strong>Retirement Benefits:</strong> Pension, Gratuity, and other post-retirement benefits</li>\r\n</ul>\r\n\r\n<h3>How to Apply for IAF AFCAT 02/2026 [citation:6]</h3>\r\n<p>Candidates can apply online through the official AFCAT website. Follow these steps:</p>\r\n<ol>\r\n<li>Visit the official AFCAT website: <strong>https://afcat.edcil.co.in</strong> [citation:2][citation:4]</li>\r\n<li>Click on \"New Registration\" for AFCAT 02/2026</li>\r\n<li>Register with your email ID and mobile number</li>\r\n<li>Fill the application form with personal, educational, and contact details</li>\r\n<li>Upload scanned photo, signature, and other required documents</li>\r\n<li>Pay application fee online (₹ 550 + GST for AFCAT Entry) or select fee exemption (for NCC/GATE entries) [citation:1]</li>\r\n<li>Submit the application form and take a printout for future reference</li>\r\n<li>Download the AFCAT Admit Card from 04 August 2026 onwards [citation:2]</li>\r\n</ol>\r\n\r\n<h3>Documents Required</h3>\r\n<ul>\r\n<li>10th Mark Sheet & Certificate (for date of birth proof)</li>\r\n<li>12th Mark Sheet & Certificate (with Physics and Mathematics)</li>\r\n<li>Graduation Degree Certificate & Mark Sheets (all semesters/years)</li>\r\n<li>B.E./B.Tech Degree Certificate (for Technical Branch)</li>\r\n<li>GATE Score Card (if applying under GATE Score Entry)</li>\r\n<li>NCC Certificate (for NCC Special Entry)</li>\r\n<li>Recent Passport Size Photograph (10-50 KB, JPEG format)</li>\r\n<li>Signature (10-20 KB, JPEG format)</li>\r\n<li>Caste Certificate (OBC/SC/ST/EWS, if applicable)</li>\r\n<li>PwD Certificate (if applicable)</li>\r\n<li>CPL Certificate (for Flying Branch CPL holders)</li>\r\n</ul>\r\n\r\n<h3>Important Information</h3>\r\n<ul>\r\n<li><strong>Marital Status:</strong> Unmarried candidates only at the time of training commencement [citation:1]</li>\r\n<li><strong>Citizenship:</strong> Must be a citizen of India</li>\r\n<li><strong>Number of Attempts:</strong> No limit on attempts (age limit applicable)</li>\r\n<li><strong>Commission Types:</strong> Permanent Commission (PC) for Men, Short Service Commission (SSC) for Men & Women [citation:2]</li>\r\n<li><strong>SSC Tenure:</strong> 10 years extendable to 14 years for SSC officers</li>\r\n<li><strong>NCC Special Entry Benefits:</strong> Direct AFSB interview without AFCAT exam [citation:1]</li>\r\n<li><strong>Travel Allowance:</strong> First-time AFSB candidates get travel allowance as per rules [citation:9]</li>\r\n</ul>\r\n\r\n<h3>Exam Cities (Major Centers)</h3>\r\n<p>Ahmedabad, Aizawl, Allahabad, Bangalore, Bareilly, Bhopal, Chandigarh, Chennai, Coimbatore, Cuttack, Dehradun, Delhi, Dispur, Gangtok, Guwahati, Gwalior, Hyderabad, Imphal, Itanagar, Jaipur, Jalandhar, Jammu, Jodhpur, Jorhat, Kochi, Kohima, Kolkata, Leh, Lucknow, Madurai, Mumbai, Mysore, Nagpur, Panaji, Patna, Port Blair, Pune, Raipur, Ranchi, Sambalpur, Shillong, Shimla, Srinagar, Thiruvananthapuram, Tiruchirappalli, Tirupati, Udaipur, Varanasi, Vijayawada, Visakhapatnam</p>\r\n\r\n<h3>Tips for Preparation</h3>\r\n<ul>\r\n<li><strong>General Awareness:</strong> Read newspapers daily (The Hindu, Indian Express), focus on defence news, current affairs of last 6-8 months</li>\r\n<li><strong>English:</strong> Practice grammar, vocabulary, reading comprehension, and error spotting</li>\r\n<li><strong>Numerical Ability:</strong> Focus on NCERT Mathematics (Class 10 & 12), practice speed and accuracy</li>\r\n<li><strong>Reasoning:</strong> Practice both verbal and non-verbal reasoning from standard books like R.S. Aggarwal</li>\r\n<li><strong>AFSB Preparation:</strong> Join mock SSB sessions, practice group discussions, improve communication skills</li>\r\n<li><strong>Physical Fitness:</strong> Regular running, push-ups, sit-ups, swimming (especially for Flying Branch aspirants)</li>\r\n</ul>\r\n\r\n<h3>Helpline & Support</h3>\r\n<ul>\r\n<li><strong>AFCAT Helpdesk:</strong> Available on official website</li>\r\n<li><strong>Email:</strong> afcat@cdac.in</li>\r\n<li><strong>Toll-Free Number:</strong> 1800-208-8072 (during working hours)</li>\r\n</ul>\r\n\r\n<p><strong>Important Links:</strong><br />\r\n<a href=\"https://afcat.edcil.co.in\" target=\"_blank\" rel=\"noopener\">Apply Online (AFCAT Official Website)</a><br />\r\n<a href=\"https://afcat.cdac.co.in\" target=\"_blank\" rel=\"noopener\">Alternative AFCAT Website</a><br />\r\n<a href=\"notifications/iaf_afcat_02_2026_notification.pdf\" target=\"_blank\" rel=\"noopener\">Download Official Notification PDF</a><br />\r\n<a href=\"notifications/iaf_afcat_02_2026_syllabus.pdf\" target=\"_blank\" rel=\"noopener\">Download Syllabus PDF</a><br />\r\n<a href=\"https://indianairforce.nic.in\" target=\"_blank\" rel=\"noopener\">Indian Air Force Official Website</a></p>\r\n\r\n<p><strong>Tags:</strong> AFCAT 2026, AFCAT 02/2026, Indian Air Force Recruitment, IAF Jobs, Flying Branch, Ground Duty Technical, Ground Duty Non-Technical, Defence Jobs, Air Force Common Admission Test, AFSB Interview, Air Force Academy, Officer Entry, SSC Commission, Permanent Commission, Sarkari Result</p>', 'Total Vacancies: 304+ (approximately 379 including all entries). Branch-wise: Flying Branch-35 (SSC), Ground Duty Technical-211, Ground Duty Non-Technical-107, GATE Score Entry-26, NCC Special Entry (Flying)-10% of CDSE & AFCAT vacancies. Category-wise and gender-wise vacancies as per official notification. Vacancies may vary based on organizational requirements. [citation:1][citation:3][citation:8]', '2026-07-15', '2026-08-25', '2026-06-19', '2026-06-22', '2026-08-08', '2026-08-04', '2026-10-30', '2027-07-01', '₹ 550/- + GST', '₹ 550/- + GST', '₹ 550/- + GST', 'Online (Net Banking, Credit Card, Debit Card, UPI)', NULL, '20 Years', '26 Years', 'SC/ST: 5 years, OBC: 3 years (as per government rules). CPL holders get additional 2 years for Flying Branch.', NULL, '304', 'Across India (Air Force Stations & Training Establishments in Delhi, Mumbai, Bangalore, Hyderabad, Pune, Kolkata, Chennai, Chandigarh, Guwahati, etc.)', 'Flying Branch: Bachelor\'s degree in any discipline with 60% marks + Physics & Mathematics at 10+2 level. Ground Duty Technical: B.E./B.Tech in relevant Engineering discipline with 60% marks. Ground Duty Non-Technical: Bachelor\'s degree in relevant discipline with 60% marks (varies by specialisation). [citation:1][citation:4]', 'NCC Certificate (Air Wing/Senior Division) with minimum B Grade provides direct AFSB interview without AFCAT exam. GATE Score valid for Technical Branch entry. Sports certificates at national/international level, extracurricular achievements, computer proficiency, and knowledge of foreign languages are desirable. [citation:1][citation:2]', 'No prior experience required. Freshers are eligible to apply. Final year degree students can also apply provisionally.', 'Stage 1: AFCAT Online Written Examination (100 questions, 300 marks, 2 hours) - 08 August 2026 [citation:2]\r\nStage 2: AFSB Interview (5 days - Screening, Psychological Tests, Group Tasks, Personal Interview, Conference)\r\nStage 3: CPSS Test (for Flying Branch candidates only)\r\nStage 4: Medical Examination (Full medical checkup as per IAF standards)\r\nStage 5: Document Verification\r\nStage 6: Final Merit List preparation based on AFCAT score + AFSB marks + medical fitness + NCC bonus (if applicable) [citation:9]', 'Apply online through official AFCAT website (afcat.edcil.co.in) from 20 May 2026 (11:00 AM) to 19 June 2026 (11:30 PM). Complete registration, fill application form with personal, educational, and contact details, upload scanned documents (photo, signature, certificates), pay application fee (₹ 550 + GST for AFCAT Entry, free for NCC/GATE entries), submit form, and take printout for future reference. [citation:6]', 'https://afcat.edcil.co.in', 'https://afcat.edcil.co.in', 'https://afcat.edcil.co.in', 'https://afcat.edcil.co.in', 'https://afcat.edcil.co.in', 'https://afcat.edcil.co.in', 'https://afcat.edcil.co.in', 'https://indianairforce.nic.in', NULL, NULL, NULL, 'IAF AFCAT 02/2026 Recruitment - Apply Online for 300+ Air Force Officer Posts', 'Indian Air Force AFCAT 02/2026 Batch Recruitment for Commissioned Officer posts in Flying Branch & Ground Duty (Technical & Non-Technical). Total 300+ vacancies. Eligibility: Graduation/B.Tech with 60% marks. Age: 20-26 years. Fee: ₹550/- (NCC/GATE entries free). Apply online from 20 May to 19 June 2026. Exam date: 08 August 2026.', 'AFCAT 2026, AFCAT 02/2026, Indian Air Force Recruitment, IAF Jobs, Flying Branch, Ground Duty Technical, Ground Duty Non-Technical, Air Force Common Admission Test, AFSB Interview, Defence Jobs 2026, Air Force Officer Entry, SSC Commission, Permanent Commission, Air Force Academy, CPL Entry, NCC Special Entry, GATE Score Entry, Sarkari Result', 1, 0, 83, '2026-05-27 19:10:47', '2026-07-31 01:46:28'),
(35, 'Railway RRB Technician CEN 02/2026 Recruitment 2026', 'railway-rrb-technician-cen-02-2026-recruitment-2026', 2, 'Railway Recruitment Board (RRB) Technician CEN 02/2026 Recruitment for 6,565 posts of Technician Grade I, II & III. Apply online from 10 June to 09 July 2026. Eligibility: 10th/ITI/Diploma in relevant trade. Age limit: 18-33 years. Exam date: August/September 2026.', '<h2>Railway RRB Technician CEN 02/2026 Recruitment 2026</h2>\r\n<p>The <strong>Railway Recruitment Board (RRB)</strong> has released the official notification for the <strong>Technician Category CEN No. 02/2026</strong>. This recruitment drive aims to fill a total of <strong>6,565 vacancies</strong> for Technician Grade I, Grade II, and Grade III posts across various Railway zones and production units in India. This is a golden opportunity for candidates with ITI, Diploma, or 10+2 (Science) backgrounds to secure a government job in Indian Railways.</p>\r\n\r\n<h3>Important Dates</h3>\r\n<ul>\r\n<li><strong>Notification Release Date:</strong> 27 May 2026</li>\r\n<li><strong>Application Start Date:</strong> 10 June 2026 (10:00 AM)</li>\r\n<li><strong>Last Date to Apply Online:</strong> 09 July 2026 (11:59 PM)</li>\r\n<li><strong>Last Date for Fee Payment (Online):</strong> 09 July 2026</li>\r\n<li><strong>Last Date for Fee Payment (Offline/SBI Challan):</strong> 08 July 2026</li>\r\n<li><strong>Application Correction Date:</strong> 14-23 July 2026</li>\r\n<li><strong>Admit Card Release Date:</strong> 4 weeks before exam</li>\r\n<li><strong>Written Exam Date (CBT):</strong> August/September 2026</li>\r\n<li><strong>Result Date (CBT):</strong> October/November 2026</li>\r\n<li><strong>Skill Test/Document Verification:</strong> December 2026 - January 2027</li>\r\n<li><strong>Final Result Date:</strong> February/March 2027</li>\r\n</ul>\r\n\r\n<h3>Application Fee</h3>\r\n<ul>\r\n<li><strong>General / OBC / EWS:</strong> ₹ 500/- (₹ 400/- refund after CBT)</li>\r\n<li><strong>SC / ST / PwD / Ex-Servicemen / Female / Transgender / Minorities / EBC:</strong> ₹ 250/- (Full refund after CBT)</li>\r\n<li><strong>Payment Mode:</strong> Online (Net Banking, Credit Card, Debit Card, UPI) OR Offline (SBI Challan, Post Office Challan)</li>\r\n</ul>\r\n\r\n<h3>Age Limit (as on 01 July 2026)</h3>\r\n<ul>\r\n<li><strong>Minimum Age:</strong> 18 Years</li>\r\n<li><strong>Maximum Age:</strong> 33 Years</li>\r\n<li><strong>Age Relaxation:</strong></li>\r\n<li>• SC/ST: 5 years (up to 38 years)</li>\r\n<li>• OBC: 3 years (up to 36 years)</li>\r\n<li>• PwD: 10 years (up to 43 years)</li>\r\n<li>• Ex-Servicemen: As per government rules</li>\r\n</ul>\r\n\r\n<h3>Educational Qualification</h3>\r\n<h4>For Technician Grade III:</h4>\r\n<ul>\r\n<li>Matriculation (10th pass) with <strong>ITI</strong> in relevant trade from NCVT/SCVT recognized institute</li>\r\n<li>OR <strong>10+2 (Intermediate)</strong> with Physics, Chemistry, and Mathematics (PCM) with minimum 50% marks</li>\r\n<li>OR <strong>Diploma in Engineering</strong> in relevant discipline from recognized institution</li>\r\n</ul>\r\n\r\n<h4>For Technician Grade II:</h4>\r\n<ul>\r\n<li>Diploma in Engineering in relevant discipline with minimum 60% marks</li>\r\n<li>OR Bachelor\'s Degree in Science (B.Sc) with Physics and Chemistry</li>\r\n</ul>\r\n\r\n<h4>For Technician Grade I:</h4>\r\n<ul>\r\n<li>Bachelor\'s Degree in Engineering (B.E./B.Tech) in relevant discipline</li>\r\n<li>OR Master\'s Degree in Science (M.Sc) in relevant subject</li>\r\n</ul>\r\n\r\n<h4>Relevant Trades/Disciplines:</h4>\r\n<ul>\r\n<li>Mechanical Engineering</li>\r\n<li>Electrical Engineering</li>\r\n<li>Electronics & Communication Engineering</li>\r\n<li>Computer Science & Engineering</li>\r\n<li>Civil Engineering</li>\r\n<li>Instrumentation & Control Engineering</li>\r\n<li>Automobile Engineering</li>\r\n<li>Production Engineering</li>\r\n<li>Metallurgy</li>\r\n<li>Chemical Engineering</li>\r\n</ul>\r\n\r\n<h3>Vacancy Details</h3>\r\n<p><strong>Total Posts:</strong> 6,565</p>\r\n\r\n<h4>Zone-wise Vacancy Distribution:</h4>\r\n<ul>\r\n<li><strong>RRB Ahmedabad:</strong> 320 Posts</li>\r\n<li><strong>RRB Ajmer:</strong> 310 Posts</li>\r\n<li><strong>RRB Bangalore:</strong> 380 Posts</li>\r\n<li><strong>RRB Bhopal:</strong> 290 Posts</li>\r\n<li><strong>RRB Bhubaneswar:</strong> 210 Posts</li>\r\n<li><strong>RRB Bilaspur:</strong> 190 Posts</li>\r\n<li><strong>RRB Chandigarh:</strong> 350 Posts</li>\r\n<li><strong>RRB Chennai:</strong> 420 Posts</li>\r\n<li><strong>RRB Gorakhpur:</strong> 240 Posts</li>\r\n<li><strong>RRB Guwahati:</strong> 220 Posts</li>\r\n<li><strong>RRB Jammu & Srinagar:</strong> 150 Posts</li>\r\n<li><strong>RRB Kolkata:</strong> 410 Posts</li>\r\n<li><strong>RRB Malda:</strong> 170 Posts</li>\r\n<li><strong>RRB Mumbai:</strong> 480 Posts</li>\r\n<li><strong>RRB Muzaffarpur:</strong> 160 Posts</li>\r\n<li><strong>RRB Patna:</strong> 250 Posts</li>\r\n<li><strong>RRB Prayagraj:</strong> 280 Posts</li>\r\n<li><strong>RRB Ranchi:</strong> 190 Posts</li>\r\n<li><strong>RRB Secunderabad:</strong> 400 Posts</li>\r\n<li><strong>RRB Siliguri:</strong> 150 Posts</li>\r\n<li><strong>RRB Thiruvananthapuram:</strong> 195 Posts</li>\r\n</ul>\r\n\r\n<h4>Category-wise Vacancy Breakdown:</h4>\r\n<ul>\r\n<li>General (UR): 2,626 Posts (40%)</li>\r\n<li>OBC: 1,772 Posts (27%)</li>\r\n<li>SC: 984 Posts (15%)</li>\r\n<li>ST: 492 Posts (7.5%)</li>\r\n<li>EWS: 656 Posts (10%)</li>\r\n<li>Ex-Servicemen: 5% of total vacancies (horizontal reservation)</li>\r\n<li>PwD: 4% of total vacancies (horizontal reservation)</li>\r\n</ul>\r\n\r\n<h4>Grade-wise Vacancy:</h4>\r\n<ul>\r\n<li>Technician Grade I: 1,425 Posts</li>\r\n<li>Technician Grade II: 2,890 Posts</li>\r\n<li>Technician Grade III: 2,250 Posts</li>\r\n</ul>\r\n\r\n<p><strong>Job Location:</strong> Across India (All Railway Zones, Production Units, Workshops, and Divisions)</p>\r\n\r\n<h3>Exam Pattern (Computer Based Test - CBT)</h3>\r\n<h4>Exam Structure:</h4>\r\n<ul>\r\n<li><strong>Mode of Exam:</strong> Online Computer Based Test (CBT)</li>\r\n<li><strong>Duration:</strong> 90 Minutes (1.5 Hours)</li>\r\n<li><strong>Total Questions:</strong> 100 Questions</li>\r\n<li><strong>Total Marks:</strong> 100 Marks</li>\r\n<li><strong>Negative Marking:</strong> 1/3 mark deduction for each wrong answer</li>\r\n</ul>\r\n\r\n<h4>Section-wise Distribution:</h4>\r\n<ul>\r\n<li><strong>Mathematics:</strong> 25 Questions (25 Marks)</li>\r\n<li><strong>General Intelligence & Reasoning:</strong> 25 Questions (25 Marks)</li>\r\n<li><strong>General Science & Technical Ability:</strong> 30 Questions (30 Marks)</li>\r\n<li><strong>General Awareness & Current Affairs:</strong> 20 Questions (20 Marks)</li>\r\n</ul>\r\n\r\n<h3>Syllabus Details</h3>\r\n<h4>Mathematics:</h4>\r\n<ul>\r\n<li>Number System, LCM & HCF, Simplification</li>\r\n<li>Percentage, Profit & Loss, Simple & Compound Interest</li>\r\n<li>Ratio & Proportion, Partnership, Mixture & Allegation</li>\r\n<li>Time & Work, Pipes & Cisterns, Time & Distance</li>\r\n<li>Average, Age Problems, Mensuration (2D & 3D)</li>\r\n<li>Algebra, Trigonometry, Geometry</li>\r\n<li>Data Interpretation (Bar Graph, Pie Chart, Line Graph, Table)</li>\r\n</ul>\r\n\r\n<h4>General Intelligence & Reasoning:</h4>\r\n<ul>\r\n<li>Analogies, Classification, Coding-Decoding</li>\r\n<li>Blood Relations, Direction & Distance</li>\r\n<li>Series (Number, Alphabetical, Symbolic)</li>\r\n<li>Venn Diagrams, Syllogism, Logical Reasoning</li>\r\n<li>Statement & Assumptions, Statement & Conclusions</li>\r\n<li>Puzzle, Seating Arrangement</li>\r\n<li>Non-Verbal Reasoning (Mirror Image, Water Image, Paper Cutting, Figure Completion)</li>\r\n</ul>\r\n\r\n<h4>General Science & Technical Ability:</h4>\r\n<ul>\r\n<li><strong>Physics:</strong> Motion, Force, Work & Energy, Light, Sound, Electricity, Magnetism, Modern Physics</li>\r\n<li><strong>Chemistry:</strong> Atomic Structure, Chemical Bonding, Periodic Table, Acids & Bases, Metals & Non-Metals, Organic Chemistry Basics</li>\r\n<li><strong>Biology:</strong> Cell Structure, Human Body Systems, Plant Kingdom, Animal Kingdom, Diseases, Nutrition</li>\r\n<li><strong>Technical Subjects:</strong> Basic Engineering concepts related to Mechanical, Electrical, Electronics, Civil, Computer Science as per trade</li>\r\n</ul>\r\n\r\n<h4>General Awareness & Current Affairs:</h4>\r\n<ul>\r\n<li>Indian History (Ancient, Medieval, Modern)</li>\r\n<li>Indian Geography (Physical, Political, Economic)</li>\r\n<li>Indian Polity & Constitution</li>\r\n<li>Indian Economy (Budget, Five Year Plans, Banking, RBI)</li>\r\n<li>Current Affairs (National & International) - last 6-8 months</li>\r\n<li>Railways related news (Budget, New Projects, Technology)</li>\r\n<li>Sports, Awards, Books & Authors, Important Days</li>\r\n<li>Science & Technology, Environment & Ecology</li>\r\n<li>Static GK (Capitals, Currencies, National Parks, Dams, Rivers)</li>\r\n</ul>\r\n\r\n<h3>Selection Process</h3>\r\n<p>The selection will be based on the following stages:</p>\r\n<ol>\r\n<li><strong>Computer Based Test (CBT):</strong> 100 marks, 90 minutes, objective type questions</li>\r\n<li><strong>Document Verification (DV):</strong> Candidates who qualify CBT are called for DV</li>\r\n<li><strong>Medical Examination:</strong> As per Railway medical standards</li>\r\n<li><strong>Final Merit List:</strong> Based on CBT marks (no interview)</li>\r\n</ol>\r\n\r\n<h4>Post-CBT Process:</h4>\r\n<ul>\r\n<li>CBT results are normalized across all shifts</li>\r\n<li>Shortlisted candidates (3-4 times the vacancies) called for DV</li>\r\n<li>Final selection strictly based on CBT merit and document verification</li>\r\n</ul>\r\n\r\n<h3>Medical Standards</h3>\r\n<ul>\r\n<li><strong>Medical Category:</strong> A-3, B-1, B-2, C-1 (as per post requirement)</li>\r\n<li><strong>Eye Sight:</strong> 6/6, 6/9, 6/12 (varies by medical category)</li>\r\n<li><strong>Color Vision:</strong> CP-I, CP-II, CP-III (as per requirement)</li>\r\n<li><strong>Physical Fitness:</strong> Must be physically fit for workshop/field duties</li>\r\n<li><strong>No Color Blindness (for certain posts)</strong></li>\r\n</ul>\r\n\r\n<h3>Salary & Pay Scale (7th Pay Commission)</h3>\r\n<ul>\r\n<li><strong>Technician Grade III (Level 2):</strong> ₹ 19,900 - ₹ 63,200</li>\r\n<li><strong>Technician Grade II (Level 3):</strong> ₹ 21,700 - ₹ 69,100</li>\r\n<li><strong>Technician Grade I (Level 5):</strong> ₹ 29,200 - ₹ 92,300</li>\r\n</ul>\r\n\r\n<h4>Additional Allowances:</h4>\r\n<ul>\r\n<li>Dearness Allowance (DA): 50% of basic pay (current rate)</li>\r\n<li>House Rent Allowance (HRA): 8-24% of basic pay (depending on city classification)</li>\r\n<li>Transport Allowance (TA): As per rules</li>\r\n<li>Night Duty Allowance: As applicable</li>\r\n<li>Technical Allowance: Additional for technical staff</li>\r\n<li>Medical Facilities: Free medical treatment for self and dependents</li>\r\n<li>Railway Passes: Privilege passes for travel</li>\r\n<li>Leave Travel Concession (LTC): As per rules</li>\r\n<li>Pension & Gratuity: As per New Pension Scheme (NPS)</li>\r\n</ul>\r\n\r\n<h3>How to Apply for RRB Technician 2026</h3>\r\n<p>Candidates can apply online through the official RRB websites. Follow these steps:</p>\r\n<ol>\r\n<li>Visit the official RRB website of your zone: <strong>https://www.rrbapply.gov.in</strong> (Common Application Portal)</li>\r\n<li>Click on \"CEN 02/2026 (Technician) Recruitment\"</li>\r\n<li>Click on \"New Registration\" and register with your mobile number and email ID</li>\r\n<li>Fill the detailed application form with personal, educational, and contact details</li>\r\n<li>Upload scanned photo, signature, and other required documents</li>\r\n<li>Select your preferred RRB zone and exam center</li>\r\n<li>Pay application fee online (₹ 500 for General/OBC, ₹ 250 for SC/ST) or offline via SBI Challan/Post Office</li>\r\n<li>Submit the application form and take a printout for future reference</li>\r\n</ol>\r\n\r\n<h3>Documents Required</h3>\r\n<ul>\r\n<li>10th Mark Sheet & Certificate (for date of birth proof)</li>\r\n<li>12th Mark Sheet & Certificate (if applicable)</li>\r\n<li>ITI Certificate & Mark Sheet (for Technician Grade III)</li>\r\n<li>Diploma Certificate & Mark Sheets (for Technician Grade II & III)</li>\r\n<li>Graduation/Post Graduation Certificates (for Technician Grade I & II)</li>\r\n<li>Caste Certificate (OBC/SC/ST/EWS, if applicable) - OBC certificate must be in Central format</li>\r\n<li>PwD Certificate (if applicable) - issued by competent authority</li>\r\n<li>Ex-Servicemen Certificate (if applicable)</li>\r\n<li>Recent Passport Size Photograph (10-50 KB, JPEG format)</li>\r\n<li>Signature (10-20 KB, JPEG format)</li>\r\n<li>Valid Email ID & Mobile Number</li>\r\n<li>Photo ID Proof (Aadhar, Voter ID, PAN, Driving License, Passport)</li>\r\n</ul>\r\n\r\n<h3>Important Information</h3>\r\n<ul>\r\n<li><strong>Number of Attempts:</strong> No limit on attempts (age limit applicable)</li>\r\n<li><strong>Citizenship:</strong> Must be a citizen of India or subject of Nepal/Bhutan or Tibetan refugee (before 01/01/1962)</li>\r\n<li><strong>RRB Zones:</strong> Choose any RRB zone while applying (one application per candidate)</li>\r\n<li><strong>Exam Centers:</strong> Can choose preferred exam cities within the selected RRB zone</li>\r\n<li><strong>Language Options:</strong> CBT available in 15 languages (Hindi, English, Urdu, Bengali, Marathi, Tamil, Telugu, Kannada, Malayalam, Gujarati, Odia, Punjabi, Assamese, Konkani, Manipuri)</li>\r\n<li><strong>Fee Refund:</strong> Appeared candidates get fee refund (₹ 400 for General/OBC, full ₹ 250 for SC/ST) after CBT</li>\r\n<li><strong>Railway Recruitment:</strong> Selected candidates will undergo training at Railway Training Institutes</li>\r\n</ul>\r\n\r\n<h3>Exam Cities (Major Centers)</h3>\r\n<p>All major cities across India in their respective RRB zones. Each RRB zone has multiple exam centers within its jurisdiction.</p>\r\n\r\n<h3>Preparation Tips</h3>\r\n<ul>\r\n<li><strong>Mathematics:</strong> Focus on NCERT (Class 10-12), practice speed and accuracy</li>\r\n<li><strong>Reasoning:</strong> Practice daily from standard books (R.S. Aggarwal, Kiran Publications)</li>\r\n<li><strong>General Science:</strong> Study NCERT (Class 10-12) for Physics, Chemistry, Biology</li>\r\n<li><strong>Technical Ability:</strong> Revise your ITI/Diploma course concepts</li>\r\n<li><strong>General Awareness:</strong> Read newspapers daily (The Hindu, Indian Express), follow monthly current affairs magazines (Lucent, Pratiyogita Darpan)</li>\r\n<li><strong>Mock Tests:</strong> Practice online mock tests to improve speed and accuracy</li>\r\n<li><strong>Previous Papers:</strong> Solve previous year RRB Technician papers</li>\r\n</ul>\r\n\r\n<h3>Railway Production Units</h3>\r\n<ul>\r\n<li>Chittaranjan Locomotive Works (CLW), Chittaranjan</li>\r\n<li>Diesel Locomotive Works (DLW), Varanasi</li>\r\n<li>Integral Coach Factory (ICF), Chennai</li>\r\n<li>Rail Coach Factory (RCF), Kapurthala</li>\r\n<li>Rail Wheel Factory (RWF), Bangalore</li>\r\n<li>Rail Wheel Plant (RWP), Bela</li>\r\n<li>Rail Spring Karkhana (RSK), Gwalior</li>\r\n</ul>\r\n\r\n<p><strong>Important Links:</strong><br />\r\n<a href=\"https://www.rrbapply.gov.in\" target=\"_blank\" rel=\"noopener\">Apply Online (Common RRB Portal)</a><br />\r\n<a href=\"https://indianrailways.gov.in\" target=\"_blank\" rel=\"noopener\">Indian Railways Official Website</a><br />\r\n<a href=\"notifications/rrb_technician_cen_02_2026_notification.pdf\" target=\"_blank\" rel=\"noopener\">Download Official Notification PDF</a><br />\r\n<a href=\"notifications/rrb_technician_cen_02_2026_syllabus.pdf\" target=\"_blank\" rel=\"noopener\">Download Syllabus PDF</a><br />\r\n<a href=\"https://rrbapply.gov.in/#/auth/landing\" target=\"_blank\" rel=\"noopener\">RRB Application Portal Login</a></p>\r\n\r\n<p><strong>Tags:</strong> RRB Technician 2026, RRB Technician CEN 02/2026, Railway Technician Recruitment, RRB Jobs 2026, Indian Railways Recruitment, Technician Grade I, Technician Grade II, Technician Grade III, Railway Vacancy 2026, ITI Jobs, Diploma Jobs, Railway Exam, Sarkari Result</p>', 'Total Vacancies: 6,565 Posts across all RRB zones. Grade-wise: Technician Grade I-1,425, Technician Grade II-2,890, Technician Grade III-2,250. Zone-wise vacancies: Mumbai-480, Chennai-420, Kolkata-410, Secunderabad-400, Bangalore-380, Chandigarh-350, Ahmedabad-320, Ajmer-310, Bhopal-290, Prayagraj-280, Patna-250, Gorakhpur-240, Guwahati-220, Bhubaneswar-210, Bilaspur-190, Ranchi-190, Thiruvananthapuram-195, Malda-170, Muzaffarpur-160, Jammu & Srinagar-150, Siliguri-150. Category-wise: UR-2,626, OBC-1,772, SC-984, ST-492, EWS-656. Vacancies may vary as per organizational requirements.', '2026-06-10', '2026-07-09', '2026-07-09', '2026-07-14', '2026-08-23', '2026-08-10', '2026-10-15', '2026-07-01', '₹ 500/-', '₹ 250/-', '₹ 500/-', 'Online (Net Banking, Credit Card, Debit Card, UPI) OR Offline (SBI Challan, Post Office Challan)', NULL, '18 Years', '33 Years', 'SC/ST: 5 years, OBC: 3 years, PwD: 10 years, Ex-Servicemen: As per government rules', NULL, '6565', 'Across India (All Railway Zones, Production Units, Workshops, and Divisions in Mumbai, Delhi, Kolkata, Chennai, Bengaluru, Secunderabad, Ahmedabad, Jaipur, Lucknow, Patna, Bhopal, Chandigarh, Guwahati, Bhubaneswar, etc.)', 'Technician Grade III: Matriculation (10th) with ITI in relevant trade OR 10+2 PCM with 50% marks OR Diploma in Engineering. Technician Grade II: Diploma in Engineering with 60% marks OR B.Sc with Physics & Chemistry. Technician Grade I: B.E./B.Tech in relevant discipline OR M.Sc in relevant subject.', 'NCC Certificate, Computer Diploma/Certificate, Additional technical certifications, Knowledge of computer applications, Proficiency in local languages, Sports achievements at national/state level.', 'No prior experience required. Freshers are eligible to apply. Final year ITI/Diploma/Degree students can also apply provisionally.', 'Stage 1: Computer Based Test (CBT) - 100 questions, 100 marks, 90 minutes (Objective type with negative marking)\r\nStage 2: Document Verification (DV) - For candidates who qualify CBT\r\nStage 3: Medical Examination - As per Railway medical standards\r\nStage 4: Final Merit List - Based solely on CBT marks, no interview', 'Apply online through official RRB common application portal (www.rrbapply.gov.in) from 10 June 2026 to 09 July 2026. Register with mobile number and email ID, fill application form, upload scanned documents (photo, signature, certificates), select preferred RRB zone and exam center, pay application fee (₹ 500 for General/OBC, ₹ 250 for SC/ST) online or via offline challan, submit form, and take printout for future reference.', 'https://www.rrbapply.gov.in', 'https://www.rrbapply.gov.in', 'https://www.rrbapply.gov.in/#/auth/landing', 'https://www.rrbapply.gov.in', 'https://www.rrbapply.gov.in', 'https://www.rrbapply.gov.in', 'https://www.rrbapply.gov.in', 'https://indianrailways.gov.in', NULL, NULL, NULL, 'RRB Technician CEN 02/2026 Recruitment - Apply Online for 6,565 Posts', 'Railway RRB Technician CEN 02/2026 Recruitment for 6,565 posts of Technician Grade I, II & III. Eligibility: 10th/ITI/Diploma/B.E. in relevant trade. Age: 18-33 years. Fee: ₹500/- (₹250 for SC/ST). Apply online from 10 June to 09 July 2026. Exam date: August/September 2026.', 'RRB Technician 2026, RRB Technician CEN 02/2026, Railway Technician Recruitment, Indian Railways Jobs, Technician Grade I, Technician Grade II, Technician Grade III, RRB Jobs, Railway Vacancy 2026, ITI Recruitment, Diploma Jobs, B.Tech Jobs, Railway Exam, RRB CBT, Sarkari Result', 1, 1, 131, '2026-05-27 19:26:11', '2026-07-12 15:19:46');
INSERT INTO `jobs` (`id`, `title`, `slug`, `category_id`, `short_description`, `description`, `vacancy_details`, `start_date`, `last_date`, `fee_last_date`, `correction_date`, `exam_date`, `admit_card_date`, `result_date`, `age_calculation_date`, `fee_general`, `fee_sc_st_female`, `fee_other`, `payment_mode`, `application_fee`, `min_age`, `max_age`, `age_relaxation`, `age_limit`, `total_post`, `job_location`, `qualification`, `additional_qualification`, `experience_required`, `selection_process`, `how_to_apply`, `application_link`, `registration_link`, `login_link`, `admit_card_link`, `result_link`, `answer_key_link`, `syllabus_link`, `official_website`, `notification_pdf`, `short_notification_pdf`, `syllabus_pdf`, `meta_title`, `meta_description`, `meta_keywords`, `is_active`, `is_featured`, `views`, `created_at`, `updated_at`) VALUES
(36, 'Bihar BPSC Integrated 72nd Combined (Preliminary) Competitive Exam 2026', 'bihar-bpsc-integrated-72nd-combined-preliminary-competitive-exam-2026', 5, 'BPSC 72nd Integrated Combined Competitive Examination (Preliminary) 2026 for 1,186 vacancies in various Bihar government departments. Apply online from 25 May to 15 June 2026. Eligibility: Bachelor\'s degree in any discipline. Age limit: 20-37 years (Male) & 20-40 years (Female).', '<h3>Bihar BPSC 72nd Integrated Combined Competitive Examination (Preliminary) 2026</h3>\r\n<p>The <strong>Bihar Public Service Commission (BPSC)</strong> has released the official notification for the <strong>72nd Integrated Combined Competitive Examination (CCE) 2026</strong>. This prestigious examination is conducted for recruitment to various Group A and Group B posts in the Bihar government. The preliminary examination will be followed by the main examination and interview.</p>\r\n\r\n<h3>Important Dates</h3>\r\n<ul>\r\n<li><strong>Notification Release Date:</strong> 15 May 2026</li>\r\n<li><strong>Application Start Date:</strong> 25 May 2026 (11:00 AM)</li>\r\n<li><strong>Last Date to Apply Online:</strong> 15 June 2026 (11:59 PM)</li>\r\n<li><strong>Last Date for Fee Payment (Online):</strong> 15 June 2026</li>\r\n<li><strong>Last Date for Fee Payment (Offline Challan):</strong> 13 June 2026</li>\r\n<li><strong>Application Correction Date:</strong> 20-25 June 2026</li>\r\n<li><strong>Admit Card Release (Preliminary):</strong> 1 week before exam</li>\r\n<li><strong>Preliminary Exam Date:</strong> 28 July 2026 (Sunday)</li>\r\n<li><strong>Preliminary Result Date:</strong> September/October 2026</li>\r\n<li><strong>Mains Exam Date:</strong> December 2026/January 2027</li>\r\n<li><strong>Mains Result Date:</strong> March 2027</li>\r\n<li><strong>Interview Dates:</strong> April/May 2027</li>\r\n<li><strong>Final Result Date:</strong> June/July 2027</li>\r\n</ul>\r\n\r\n<h4>Application Fee</h4>\r\n<ul>\r\n<li><strong>General / OBC / EWS:</strong> ₹ 600/-</li>\r\n<li><strong>SC / ST (Bihar Domicile):</strong> ₹ 150/-</li>\r\n<li><strong>Female (Bihar Domicile):</strong> ₹ 150/-</li>\r\n<li><strong>PwD (Bihar Domicile):</strong> ₹ 150/-</li>\r\n<li><strong>Ex-Servicemen:</strong> ₹ 150/-</li>\r\n<li><strong>Payment Mode:</strong> Online (Net Banking, Credit Card, Debit Card, UPI) OR Offline (Bank Challan at any SBI Branch)</li>\r\n</ul>\r\n\r\n<h3>Age Limit (as on 01 August 2026)</h3>\r\n<ul>\r\n<li><strong>Minimum Age:</strong> 20 Years</li>\r\n<li><strong>Maximum Age (Male - General/BC/EBC):</strong> 37 Years</li>\r\n<li><strong>Maximum Age (Male - SC/ST):</strong> 40 Years</li>\r\n<li><strong>Maximum Age (Female):</strong> 40 Years</li>\r\n<li><strong>Age Relaxation:</strong></li>\r\n<li>• SC/ST (Male): 5 years (up to 42 years)</li>\r\n<li>• BC/EBC (Male): 3 years (up to 40 years)</li>\r\n<li>• Female (All categories): 40 years max</li>\r\n<li>• PwD: 10 years (up to 47 years)</li>\r\n<li>• Ex-Servicemen: As per government rules</li>\r\n</ul>\r\n\r\n<h4>Educational Qualification</h4>\r\n<p>Candidates must possess a <strong>Bachelor\'s Degree</strong> in any discipline from a recognized university or institution.</p>\r\n\r\n<h4>Minimum Marks Required:</h4>\r\n<ul>\r\n<li><strong>General / OBC / EWS:</strong> Pass class (No minimum percentage required)</li>\r\n<li><strong>SC / ST:</strong> Pass class (No minimum percentage required)</li>\r\n<li><strong>Final Year Students:</strong> Candidates appearing in final year can also apply provisionally</li>\r\n</ul>\r\n\r\n<h4>Post-wise Additional Qualifications:</h4>\r\n<ul>\r\n<li><strong>District Coordinator (Education Department):</strong> B.Ed degree preferred</li>\r\n<li><strong>Block Panchayat Raj Officer:</strong> Knowledge of Panchayati Raj system</li>\r\n<li><strong>Revenue Officer:</strong> Knowledge of Bihar Land Revenue Code</li>\r\n<li><strong>Police Sub-Inspector:</strong> Physical fitness required</li>\r\n<li><strong>Labor Enforcement Officer:</strong> LLB degree preferred</li>\r\n<li><strong>Block SC/ST Welfare Officer:</strong> Knowledge of social welfare schemes</li>\r\n</ul>\r\n\r\n<h4>Vacancy Details</h4>\r\n<p><strong>Total Posts:</strong> 1,186</p>\r\n\r\n<h4>Department-wise Vacancy Distribution:</h4>\r\n<ul>\r\n<li><strong>General Administration Department:</strong> 234 Posts</li>\r\n<li><strong>Home Department (Police Sub-Inspector):</strong> 185 Posts</li>\r\n<li><strong>Revenue & Land Reforms Department:</strong> 156 Posts</li>\r\n<li><strong>Education Department:</strong> 142 Posts</li>\r\n<li><strong>Panchayati Raj Department:</strong> 118 Posts</li>\r\n<li><strong>Finance Department:</strong> 96 Posts</li>\r\n<li><strong>Health Department:</strong> 72 Posts</li>\r\n<li><strong>Rural Development Department:</strong> 58 Posts</li>\r\n<li><strong>Urban Development & Housing Department:</strong> 45 Posts</li>\r\n<li><strong>Labor Resources Department:</strong> 32 Posts</li>\r\n<li><strong>SC/ST Welfare Department:</strong> 28 Posts</li>\r\n<li><strong>Other Departments:</strong> 20 Posts</li>\r\n</ul>\r\n\r\n<h4>Post-wise Vacancy Breakdown:</h4>\r\n<ul>\r\n<li><strong>Deputy Superintendent of Police (DSP):</strong> 18 Posts</li>\r\n<li><strong>Block Development Officer (BDO):</strong> 42 Posts</li>\r\n<li><strong>Circle Officer (CO):</strong> 65 Posts</li>\r\n<li><strong>Deputy Superintendent of Police (Prohibition):</strong> 12 Posts</li>\r\n<li><strong>Revenue Officer (Land Reforms):</strong> 86 Posts</li>\r\n<li><strong>Block Panchayat Raj Officer (BPRO):</strong> 52 Posts</li>\r\n<li><strong>District Coordinator (Education):</strong> 38 Posts</li>\r\n<li><strong>Assistant Director (Social Security):</strong> 24 Posts</li>\r\n<li><strong>Child Development Project Officer (CDPO):</strong> 18 Posts</li>\r\n<li><strong>Labor Enforcement Officer:</strong> 32 Posts</li>\r\n<li><strong>Block SC/ST Welfare Officer:</strong> 28 Posts</li>\r\n<li><strong>Cooperative Extension Officer:</strong> 35 Posts</li>\r\n<li><strong>Planning Officer (Urban Local Bodies):</strong> 22 Posts</li>\r\n<li><strong>Various Other Posts:</strong> 714 Posts</li>\r\n</ul>\r\n\r\n<h4>Category-wise Vacancy Breakdown:</h4>\r\n<ul>\r\n<li>General (UR): 474 Posts (40%)</li>\r\n<li>OBC: 237 Posts (20%)</li>\r\n<li>EBC (Extremely Backward Class): 190 Posts (16%)</li>\r\n<li>SC: 190 Posts (16%)</li>\r\n<li>ST: 24 Posts (2%)</li>\r\n<li>EWS: 71 Posts (6%)</li>\r\n<li>PwD: 35 Posts (3% - horizontal reservation)</li>\r\n<li>Ex-Servicemen: 5% of vacancies (horizontal reservation)</li>\r\n</ul>\r\n\r\n<p><strong>Job Location:</strong> Bihar (Patna, Gaya, Bhagalpur, Muzaffarpur, Darbhanga, Purnia, Nalanda, Begusarai, Saran, Vaishali, Bhojpur, Rohtas, etc. across all 38 districts)</p>\r\n\r\n<h4>Exam Pattern</h4>\r\n<h4>Preliminary Examination (Screening Test - Objective Type):</h4>\r\n<ul>\r\n<li><strong>Mode of Exam:</strong> Offline (OMR Based)</li>\r\n<li><strong>Duration:</strong> 2 Hours</li>\r\n<li><strong>Total Questions:</strong> 150 Questions</li>\r\n<li><strong>Total Marks:</strong> 150 Marks</li>\r\n<li><strong>Negative Marking:</strong> 1/3 mark deduction for each wrong answer</li>\r\n<li><strong>Qualifying Marks:</strong> General-40%, OBC-36.5%, SC/ST-32%</li>\r\n</ul>\r\n\r\n<h4>Preliminary Exam Syllabus:</h4>\r\n<ul>\r\n<li><strong>General Studies:</strong> 150 Questions (150 Marks)</li>\r\n<li>• General Science & Technology</li>\r\n<li>• Current Events of National & International Importance</li>\r\n<li>• History of India & Bihar</li>\r\n<li>• Geography of India & Bihar</li>\r\n<li>• Indian Polity & Constitution</li>\r\n<li>• Indian Economy & Bihar Economy</li>\r\n<li>• General Mental Ability & Reasoning</li>\r\n<li>• Environment & Ecology</li>\r\n<li>• Disaster Management</li>\r\n<li>• Bihar Specific (Art, Culture, Literature, Music, Dance, Festivals)</li>\r\n</ul>\r\n\r\n<h4>Main Examination (Descriptive Type):</h4>\r\n<ul>\r\n<li><strong>Total Papers:</strong> 4 Papers (Qualifying + Merit Based)</li>\r\n<li><strong>Paper 1 - General Hindi:</strong> 100 Marks (Qualifying - 30% marks required)</li>\r\n<li><strong>Paper 2 - General Essay:</strong> 300 Marks, 3 Hours</li>\r\n<li><strong>Paper 3 - General Studies I:</strong> 300 Marks, 3 Hours</li>\r\n<li><strong>Paper 4 - General Studies II:</strong> 300 Marks, 3 Hours</li>\r\n<li><strong>Total Merit Marks:</strong> 900 Marks</li>\r\n</ul>\r\n\r\n<h4>Main Exam Subjects:</h4>\r\n<p><strong>General Studies I:</strong><br />\r\n- History (Ancient, Medieval, Modern India & Bihar)<br />\r\n- Art & Culture of India & Bihar<br />\r\n- Indian Geography & Bihar Geography<br />\r\n- World Geography</p>\r\n\r\n<p><strong>General Studies II:</strong><br />\r\n- Indian Polity, Constitution & Governance<br />\r\n- Indian Economy & Bihar Economy<br />\r\n- Science & Technology<br />\r\n- Environment & Ecology<br />\r\n- Current Affairs</p>\r\n\r\n<h4>Interview (Personality Test):</h4>\r\n<ul>\r\n<li><strong>Total Marks:</strong> 120 Marks</li>\r\n<li><strong>Duration:</strong> 30-45 Minutes</li>\r\n<li><strong>Areas Assessed:</strong> Leadership, Decision Making, Communication Skills, General Awareness, Bihar Specific Knowledge, Ethical Values</li>\r\n<li><strong>Final Merit:</strong> Main Exam (900 Marks) + Interview (120 Marks) = 1020 Marks</li>\r\n</ul>\r\n\r\n<h4>Physical Standards (For Police Sub-Inspector & DSP Posts):</h4>\r\n<h4>For Male Candidates:</h4>\r\n<ul>\r\n<li><strong>Height (General/OBC/SC):</strong> Minimum 165 cms</li>\r\n<li><strong>Height (ST):</strong> Minimum 160 cms</li>\r\n<li><strong>Chest (General/OBC/SC):</strong> 81-86 cms (Minimum expansion 5 cms)</li>\r\n<li><strong>Chest (ST):</strong> 79-84 cms (Minimum expansion 5 cms)</li>\r\n<li><strong>Weight:</strong> Proportionate to height</li>\r\n<li><strong>Race (1.6 KM):</strong> Within 6 minutes</li>\r\n</ul>\r\n\r\n<h4>For Female Candidates:</h4>\r\n<ul>\r\n<li><strong>Height (General/OBC/SC):</strong> Minimum 155 cms</li>\r\n<li><strong>Height (ST):</strong> Minimum 150 cms</li>\r\n<li><strong>Weight:</strong> Proportionate to height</li>\r\n<li><strong>Race (800 Meters):</strong> Within 4 minutes</li>\r\n</ul>\r\n\r\n<h4>Medical Standards:</h4>\r\n<ul>\r\n<li><strong>Eye Sight:</strong> 6/12 (without glasses), correctable to 6/6</li>\r\n<li><strong>No Color Blindness</strong></li>\r\n<li><strong>No Flat Foot, No Knock Knees</strong></li>\r\n<li><strong>No Tattoos (except traditional permanent tattoos)</strong></li>\r\n</ul>\r\n\r\n<h4>Selection Process</h4>\r\n<p>The selection will be based on the following stages:</p>\r\n<ol>\r\n<li><strong>Preliminary Examination (Objective Type):</strong> Screening test (150 marks, 2 hours)</li>\r\n<li><strong>Main Examination (Descriptive Type):</strong> 4 papers (900 marks)</li>\r\n<li><strong>Physical Efficiency Test (PET):</strong> For Police Sub-Inspector & DSP posts only</li>\r\n<li><strong>Interview (Personality Test):</strong> 120 marks</li>\r\n<li><strong>Document Verification</strong></li>\r\n<li><strong>Medical Examination:</strong> For Police posts only</li>\r\n<li><strong>Final Merit List:</strong> Based on Main Exam + Interview marks</li>\r\n</ol>\r\n\r\n<h4>Salary & Pay Scale (7th Pay Commission)</h4>\r\n<h4>Post-wise Salary Structure:</h4>\r\n<ul>\r\n<li><strong>Deputy Superintendent of Police (DSP):</strong> Level 10 (₹ 56,100 - ₹ 1,77,500)</li>\r\n<li><strong>Block Development Officer (BDO):</strong> Level 9 (₹ 53,100 - ₹ 1,67,800)</li>\r\n<li><strong>Circle Officer (CO):</strong> Level 9 (₹ 53,100 - ₹ 1,67,800)</li>\r\n<li><strong>Revenue Officer:</strong> Level 8 (₹ 47,600 - ₹ 1,51,100)</li>\r\n<li><strong>Block Panchayat Raj Officer (BPRO):</strong> Level 7 (₹ 44,900 - ₹ 1,42,400)</li>\r\n<li><strong>District Coordinator:</strong> Level 7 (₹ 44,900 - ₹ 1,42,400)</li>\r\n<li><strong>Child Development Project Officer (CDPO):</strong> Level 8 (₹ 47,600 - ₹ 1,51,100)</li>\r\n<li><strong>Labor Enforcement Officer:</strong> Level 6 (₹ 35,400 - ₹ 1,12,400)</li>\r\n</ul>\r\n\r\n<h4>Additional Allowances:</h4>\r\n<ul>\r\n<li>Dearness Allowance (DA): 50% of basic pay (current rate)</li>\r\n<li>House Rent Allowance (HRA): 8-24% of basic pay (depending on city)</li>\r\n<li>Transport Allowance (TA): As per rules</li>\r\n<li>Medical Allowance: ₹ 1,000 - ₹ 2,000 per month</li>\r\n<li>Special Allowance: For specific posts (Police, Revenue)</li>\r\n<li>Ration Money Allowance: For Police personnel</li>\r\n<li>Risk Allowance: For field posts</li>\r\n<li>Children Education Allowance: As per rules</li>\r\n</ul>\r\n\r\n<h4>How to Apply for BPSC 72nd CCE 2026</h4>\r\n<p>Candidates can apply online through the official BPSC website. Follow these steps:</p>\r\n<ol>\r\n<li>Visit the official BPSC website: <strong>https://bpsc.bih.nic.in</strong></li>\r\n<li>Click on \"72nd Integrated Combined Competitive Examination 2026\"</li>\r\n<li>Click on \"Apply Online\" and register with your email ID and mobile number</li>\r\n<li>Fill the detailed application form with personal, educational, and contact details</li>\r\n<li>Upload scanned photo, signature, and other required documents</li>\r\n<li>Select preferred district and post preferences</li>\r\n<li>Pay application fee online (₹ 600 for General, ₹ 150 for SC/ST/Female) or via offline challan</li>\r\n<li>Submit the application form and take a printout for future reference</li>\r\n</ol>\r\n\r\n<h4>Documents Required</h4>\r\n<ul>\r\n<li>10th Mark Sheet & Certificate (for date of birth proof)</li>\r\n<li>12th Mark Sheet & Certificate</li>\r\n<li>Bachelor Degree Certificate & All Semester Mark Sheets</li>\r\n<li>Master Degree Certificate (if applicable)</li>\r\n<li>Bihar Domicile Certificate</li>\r\n<li>Caste Certificate (OBC/EBC/SC/ST, if applicable) - Must be in Bihar government format</li>\r\n<li>EWS Certificate (if applicable) - issued by Bihar government</li>\r\n<li>PwD Certificate (if applicable) - 40% or more disability</li>\r\n<li>Ex-Serviceman Certificate (if applicable)</li>\r\n<li>Recent Passport Size Photograph (10-50 KB, JPEG format)</li>\r\n<li>Signature (10-20 KB, JPEG format)</li>\r\n<li>Valid Email ID & Mobile Number (must be active for 2 years)</li>\r\n<li>Aadhar Card (recommended)</li>\r\n</ul>\r\n\r\n<h4>Important Information</h4>\r\n<ul>\r\n<li><strong>Number of Attempts:</strong> No limit on attempts for General (age limit applicable)</li>\r\n<li><strong>Citizenship:</strong> Must be a citizen of India</li>\r\n<li><strong>Domicile:</strong> Bihar domicile required for reserved category benefits</li>\r\n<li><strong>Language:</strong> Knowledge of Hindi in Devanagari script is mandatory</li>\r\n<li><strong>Examination Centers:</strong> All 38 districts of Bihar + Patna, Gaya, Bhagalpur, Muzaffarpur, Darbhanga, Purnia</li>\r\n<li><strong>Bihar Residence:</strong> Candidates must have resided in Bihar for at least 5 years for state quota</li>\r\n</ul>\r\n\r\n<h4>Preliminary Exam Centers (Major Cities in Bihar):</h4>\r\n<p>Patna, Gaya, Bhagalpur, Muzaffarpur, Darbhanga, Purnia, Nalanda (Bihar Sharif), Begusarai, Saran (Chapra), Vaishali (Hajipur), Bhojpur (Arrah), Rohtas (Sasaram), Samastipur, Sitamarhi, Madhubani, Siwan, Gopalganj, Nawada, Aurangabad, Jehanabad, Arwal, Khagaria, Katihar, Saharsa, Supaul, Madhepura, Sheohar, East Champaran (Motihari), West Champaran (Bettiah), Kishanganj, Araria, Banka, Munger, Lakhisarai, Jamui, Sheikhpura, Buxar, Kaimur (Bhabua)</p>\r\n\r\n<h4>Books & Preparation Tips</h4>\r\n<ul>\r\n<li><strong>General Studies:</strong> NCERT (Class 6-12), Lucent General Knowledge</li>\r\n<li><strong>Bihar Specific:</strong> Bihar Samanya Gyan (Bihar General Knowledge), Bihar: Ek Parichay</li>\r\n<li><strong>Indian Polity:</strong> Indian Polity by M. Laxmikanth</li>\r\n<li><strong>Indian Economy:</strong> Indian Economy by Ramesh Singh, Economic Survey of Bihar</li>\r\n<li><strong>History:</strong> History of India by Bipan Chandra, History of Bihar by Dr. R.K. Sinha</li>\r\n<li><strong>Geography:</strong> Geography of India by Majid Hussain</li>\r\n<li><strong>Current Affairs:</strong> Pratiyogita Darpan, The Hindu newspaper, Bihar Current Affairs monthly</li>\r\n<li><strong>Practice:</strong> Previous year BPSC question papers, mock tests</li>\r\n</ul>\r\n\r\n<h4>BPSC 72nd Exam Highlights</h4>\r\n<ul>\r\n<li>Total 1,186 vacancies across 32 departments of Bihar government</li>\r\n<li>Preliminary exam: 28 July 2026</li>\r\n<li>Mains exam: December 2026/January 2027</li>\r\n<li>Application fee: ₹600 for General, ₹150 for SC/ST/Female</li>\r\n<li>Age limit: 20-37 years (Male), 20-40 years (Female)</li>\r\n<li>Educational qualification: Bachelor degree in any discipline</li>\r\n</ul>\r\n\r\n<p><strong>Helpline Numbers:</strong><br />\r\nBPSC Helpline: 0612-2227575<br />\r\nBPSC Toll-Free: 1800-345-6225 (10:00 AM - 5:00 PM, Monday-Friday)<br />\r\nEmail: bpsc.help@gmail.com</p>\r\n\r\n<p><strong>Tags:</strong> BPSC 72nd CCE 2026, Bihar Combined Competitive Exam, BPSC Recruitment 2026, Bihar Government Jobs, BPSC Preliminary Exam, BPSC Mains Exam, District Coordinator, BDO, DSP, Circle Officer, Revenue Officer, BPRO, BPSC Vacancy, Bihar Public Service Commission, Sarkari Result</p>', 'Total Vacancies: 1,186 Posts across 32 departments of Bihar Government. Department-wise: General Administration-234, Home (Police)-185, Revenue-156, Education-142, Panchayati Raj-118, Finance-96, Health-72, Rural Development-58, Urban Development-45, Labor Resources-32, SC/ST Welfare-28, Others-20. Post-wise: DSP-18, BDO-42, CO-65, DSP (Prohibition)-12, Revenue Officer-86, BPRO-52, District Coordinator-38, Assistant Director-24, CDPO-18, Labor Enforcement Officer-32, SC/ST Welfare Officer-28, Cooperative Extension Officer-35, Planning Officer-22, Various Others-714. Category-wise: UR-474, OBC-237, EBC-190, SC-190, ST-24, EWS-71, PwD-35, Ex-Servicemen-5% horizontal.', '2026-05-25', '2026-06-15', '2026-06-15', '2026-06-20', '2026-07-28', '2026-07-21', '2026-09-30', '2026-08-01', '₹ 600/-', '₹ 150/-', '₹ 150/-', 'Online (Net Banking, Credit Card, Debit Card, UPI) OR Offline (Bank Challan at SBI Branch)', NULL, '20 Years', '40 Years', 'SC/ST: 5 years, BC/EBC: 3 years, Female: 40 years max, PwD: 10 years, Ex-Servicemen: As per government rules', NULL, '1186', 'Bihar', 'Bachelor\'s Degree in any discipline from a recognized university or institution. Final year appearing candidates can also apply provisionally. For specific posts: B.Ed (Education Department), LLB (Labor Enforcement Officer), Knowledge of Panchayati Raj (BPRO), Knowledge of Bihar Land Revenue Code (Revenue Officer).', 'Knowledge of Hindi in Devanagari script is mandatory. NCC Certificate, Computer Diploma, MS-CIT, Knowledge of Bihar culture, history, and geography, Proficiency in English, Experience in social work, Participation in sports at national/state level.', 'No prior experience required for most posts. Freshers are eligible to apply. For some specialized posts (District Coordinator, CDPO), 2-3 years experience may be preferred but not mandatory. Final year students can apply provisionally.', 'Stage 1: Preliminary Examination (Objective Type - 150 marks, 2 hours, screening test)\r\nStage 2: Main Examination (Descriptive Type - 900 marks, 4 papers)\r\nStage 3: Physical Efficiency Test (PET) - For Police Sub-Inspector & DSP posts only\r\nStage 4: Interview (Personality Test - 120 marks)\r\nStage 5: Document Verification\r\nStage 6: Medical Examination - For Police posts only\r\nFinal Merit List based on Main Exam (900 marks) + Interview (120 marks) = 1020 marks', 'Apply online through official BPSC website (bpsc.bih.nic.in) from 25 May 2026 to 15 June 2026. Complete registration with email ID and mobile number, fill application form with personal, educational, contact details, upload scanned documents (photo, signature, certificates), select district and post preferences, pay application fee (₹ 600 for General, ₹ 150 for SC/ST/Female) online or via SBI challan, submit form, and take printout for future reference.', 'https://bpsc.bih.nic.in', 'https://bpsc.bih.nic.in/OnlineRegistration.aspx', 'https://bpsc.bih.nic.in/Login.aspx', 'https://bpsc.bih.nic.in/AdmitCard.aspx', 'https://bpsc.bih.nic.in/Result.aspx', 'https://bpsc.bih.nic.in/AnswerKey.aspx', 'https://bpsc.bih.nic.in/Syllabus.aspx', 'https://bpsc.bih.nic.in', 'notifications/1779988611_bihar-bpsc-integrated-72nd-combined-preliminary-competitive-exam-2026.pdf', NULL, NULL, 'BPSC 72nd Combined Competitive Exam 2026 - Apply Online for 1,186 Posts', 'Bihar BPSC 72nd Integrated Combined (Preliminary) Competitive Exam 2026 for 1,186 vacancies in Bihar government. Eligibility: Bachelor\'s degree. Age: 20-37 years (Male), 20-40 years (Female). Fee: ₹600/- (₹150 for SC/ST/Female). Apply online from 25 May to 15 June 2026. Preliminary exam: 28 July 2026.', 'BPSC 72nd CCE 2026, Bihar Combined Competitive Exam, BPSC Recruitment, Bihar Government Jobs, BPSC Preliminary Exam, BPSC Mains Exam, BPSC 72nd Notification, Bihar Public Service Commission, DSP Recruitment, BDO Recruitment, Circle Officer, Revenue Officer, Block Panchayat Raj Officer, BPSC Vacancy 2026, Sarkari Result', 1, 0, 86, '2026-05-27 19:38:16', '2026-07-12 15:19:42'),
(37, 'Bihar Police CSBC Constable (Sipahi) Recruitment 2025 Final Result 2026', 'bihar-police-csbc-constable-sipahi-recruitment-2025-final-result-2026', 5, 'CSBC Bihar Police Constable Final Result 2026 declared on 27 May 2026. Total 19,838 candidates selected for Constable (Sipahi) posts in Bihar Police and Bihar Special Armed Police (BSAP). Check category-wise cutoff, selection list PDF, and joining schedule from 20 June to 19 July 2026.', '<h2>Bihar Police CSBC Constable (Sipahi) Recruitment 2025 Final Result 2026</h2>\r\n<p>The <strong>Central Selection Board of Constables (CSBC), Bihar</strong> has officially declared the <strong>Final Result for Constable (Sipahi) Recruitment 2025</strong> on <strong>27 May 2026</strong>. A total of <strong>19,838 candidates</strong> have been selected for appointment in Bihar Police and Bihar Special Armed Police (BSAP) under Advertisement No. 01/2025.</p>\r\n\r\n<h3>Important Dates</h3>\r\n<ul>\r\n<li><strong>Notification Release Date:</strong> 11 March 2025</li>\r\n<li><strong>Application Start Date:</strong> March 2025</li>\r\n<li><strong>Last Date to Apply Online:</strong> April 2025</li>\r\n<li><strong>Written Exam Dates:</strong> 16 July 2025 to 03 August 2025</li>\r\n<li><strong>PET Exam Dates:</strong> 15 December 2025 to 11 March 2026</li>\r\n<li><strong>Final Result Declaration Date:</strong> 27 May 2026</li>\r\n<li><strong>Joining/Reporting Dates:</strong> 20 June 2026 to 19 July 2026</li>\r\n</ul>\r\n\r\n<h3>Application Fee</h3>\r\n<ul>\r\n<li><strong>General / OBC / EWS:</strong> As per CSBC norms</li>\r\n<li><strong>SC / ST / Female:</strong> As per CSBC norms</li>\r\n<li><strong>Payment Mode:</strong> Online</li>\r\n</ul>\r\n\r\n<h3>Age Limit (as on 01 August 2025)</h3>\r\n<ul>\r\n<li><strong>Minimum Age:</strong> 18 Years</li>\r\n<li><strong>Maximum Age (Male - General):</strong> 25 Years</li>\r\n<li><strong>Maximum Age (Female):</strong> 25 Years</li>\r\n<li><strong>Age Relaxation:</strong> As per Bihar government rules for reserved categories</li>\r\n</ul>\r\n\r\n<h3>Educational Qualification</h3>\r\n<p>Candidates must have passed <strong>10+2 (Intermediate)</strong> examination from a recognized board or equivalent.</p>\r\n\r\n<h3>Vacancy & Selection Details</h3>\r\n<p><strong>Total Posts:</strong> 19,838</p>\r\n<p><strong>Total Applications Received:</strong> 17,06,628</p>\r\n<p><strong>Candidates appeared in Written Exam:</strong> 13,30,121</p>\r\n<p><strong>Candidates shortlisted for PET:</strong> 99,690</p>\r\n<p><strong>Candidates appeared in PET:</strong> 79,932</p>\r\n<p><strong>Final Selected Candidates:</strong> 19,838</p>\r\n\r\n<h4>Department-wise Allocation:</h4>\r\n<ul>\r\n<li><strong>Bihar Police (District Police & Units):</strong> 16,852 Posts</li>\r\n<li><strong>Bihar Special Armed Police (BSAP):</strong> 2,986 Posts</li>\r\n</ul>\r\n\r\n<h4>Gender-wise Selection:</h4>\r\n<ul>\r\n<li><strong>Male:</strong> 12,509 Candidates</li>\r\n<li><strong>Female:</strong> 7,312 Candidates</li>\r\n<li><strong>Transgender:</strong> 17 Candidates</li>\r\n</ul>\r\n\r\n<h4>Special Category Selection:</h4>\r\n<ul>\r\n<li><strong>Homeguard Quota:</strong> 332 Candidates</li>\r\n<li><strong>Freedom Fighter Dependents:</strong> 190 Candidates</li>\r\n</ul>\r\n\r\n<h3>Category-wise Final Selection Breakdown</h3>\r\n<table>\r\n    <tr><th>Category</th><th>Number of Selected Candidates</th></tr>\r\n    <tr><td>General (UR)</td><td>7,935</td></tr>\r\n    <tr><td>EWS</td><td>1,983</td></tr>\r\n    <tr><td>SC</td><td>3,174</td></tr>\r\n    <tr><td>ST</td><td>199</td></tr>\r\n    <tr><td>EBC</td><td>3,571</td></tr>\r\n    <tr><td>BC (Backward Class)</td><td>2,381</td></tr>\r\n    <tr><td>BCW (Backward Class Women)</td><td>595</td></tr>\r\n    <tr style=\"background:#f2f2f2;\"><td><strong>Total</strong></td><td><strong>19,838</strong></td></tr>\r\n</table>\r\n\r\n<h3>Category-wise Final Cutoff Marks</h3>\r\n<table>\r\n    <tr><th>Category</th><th>Male Cutoff</th><th>Female Cutoff</th></tr>\r\n    <tr><td>General (UR)</td><td>76 Marks</td><td>72 Marks</td></tr>\r\n    <tr><td>EWS</td><td>66 Marks</td><td>64 Marks</td></tr>\r\n    <tr><td>SC</td><td>66 Marks</td><td>54 Marks</td></tr>\r\n    <tr><td>ST</td><td>66 Marks</td><td>64 Marks</td></tr>\r\n    <tr><td>EBC</td><td>68 Marks</td><td>62 Marks</td></tr>\r\n    <tr><td>BC</td><td>72 Marks</td><td>68 Marks</td></tr>\r\n    <tr><td>Homeguard</td><td colspan=\"2\">42 Marks</td></tr>\r\n</table>\r\n\r\n<h3>Selection Process</h3>\r\n<p>The selection was based on the following stages:</p>\r\n<ol>\r\n<li><strong>Written Examination (CBT):</strong> Conducted in July-August 2025 (6 phases)</li>\r\n<li><strong>Physical Efficiency Test (PET):</strong> Conducted from 15 December 2025 to 11 March 2026 at Patna</li>\r\n<li><strong>Document Verification (DV)</strong></li>\r\n<li><strong>Medical Examination</strong></li>\r\n<li><strong>Final Merit List</strong></li>\r\n</ol>\r\n\r\n<h3>How to Check Bihar Police Constable Final Result 2026</h3>\r\n<p>Candidates can download the final result PDF from the official CSBC website by following these steps:</p>\r\n<ol>\r\n<li>Visit the official CSBC website: <strong>https://csbc.bihar.gov.in</strong></li>\r\n<li>Click on the link \"Results: Final Selection List of Candidates for the Post of Constable in Bihar Police (Advt. No. 01/2025)\"</li>\r\n<li>The final selection list PDF will open</li>\r\n<li>Use <strong>Ctrl + F</strong> to search for your roll number</li>\r\n<li>If your roll number appears, you have been selected</li>\r\n<li>Download and save the PDF for future reference</li>\r\n</ol>\r\n\r\n<h3>Documents Required for Joining</h3>\r\n<ul>\r\n<li>10th Mark Sheet & Certificate (Date of Birth Proof)</li>\r\n<li>10+2 (Intermediate) Mark Sheet & Certificate</li>\r\n<li>Bihar Domicile Certificate</li>\r\n<li>Caste Certificate (if applicable) - OBC/SC/ST/EBC/BC</li>\r\n<li>Income & Asset Certificate (for EWS candidates)</li>\r\n<li>Homeguard Certificate (if applicable)</li>\r\n<li>Freedom Fighter Dependent Certificate (if applicable)</li>\r\n<li>Character Certificate</li>\r\n<li>Medical Fitness Certificate</li>\r\n<li>Aadhar Card</li>\r\n<li>PAN Card (if available)</li>\r\n<li>Recent Passport Size Photographs</li>\r\n</ul>\r\n\r\n<h3>Joining Schedule</h3>\r\n<p>Selected candidates must report for joining between:</p>\r\n<ul>\r\n<li><strong>Start Date:</strong> 20 June 2026</li>\r\n<li><strong>Last Date:</strong> 19 July 2026</li>\r\n</ul>\r\n<p><strong>Note:</strong> Final joining will be subject to medical examination and character verification. Candidates must report to their allotted district or battalion as mentioned in the selection list PDF.</p>\r\n\r\n<h3>Important Information</h3>\r\n<ul>\r\n<li><strong>Recruitment Advertisement No.:</strong> 01/2025</li>\r\n<li><strong>Conducting Body:</strong> Central Selection Board of Constables (CSBC), Bihar</li>\r\n<li><strong>Post Name:</strong> Constable (Sipahi)</li>\r\n<li><strong>Job Location:</strong> Bihar (All 38 districts)</li>\r\n<li><strong>Service Allocation:</strong> Bihar Police (District Police) & BSAP</li>\r\n<li><strong>Result Declaration Date:</strong> 27 May 2026</li>\r\n<li><strong>Result Status:</strong> FINAL RESULT DECLARED</li>\r\n</ul>\r\n\r\n<h3>Salary & Pay Scale</h3>\r\n<ul>\r\n<li><strong>Pay Level:</strong> Level 3 (as per 7th Pay Commission)</li>\r\n<li><strong>Pay Scale:</strong> ₹ 21,700 - ₹ 69,100</li>\r\n<li><strong>Grade Pay:</strong> ₹ 2,000</li>\r\n<li><strong>Dearness Allowance (DA):</strong> As per government norms</li>\r\n<li><strong>House Rent Allowance (HRA):</strong> As applicable based on posting location</li>\r\n<li><strong>Other Allowances:</strong> Uniform Allowance, Risk Allowance, Ration Money, etc.</li>\r\n</ul>\r\n\r\n<h3>Important Links</h3>\r\n<p>\r\n<a href=\"https://csbc.bihar.gov.in\" target=\"_blank\" rel=\"noopener\">✅ CSBC Official Website</a><br>\r\n<a href=\"https://csbc.bihar.gov.in/Result/Final_Selection_Constable_Advt_01_2025.pdf\" target=\"_blank\" rel=\"noopener\">📥 Download Final Result PDF</a><br>\r\n<a href=\"https://csbc.bihar.gov.in/Notice/Final_Cutoff_Marks_Constable_2026.pdf\" target=\"_blank\" rel=\"noopener\">📊 Download Category-wise Cutoff PDF</a><br>\r\n<a href=\"https://csbc.bihar.gov.in/Notice/Joining_Schedule_Constable_2026.pdf\" target=\"_blank\" rel=\"noopener\">📅 Download Joining Schedule</a><br>\r\n<a href=\"https://csbc.bihar.gov.in/Notice/Medical_Examination_Instructions.pdf\" target=\"_blank\" rel=\"noopener\">🏥 Medical Examination Instructions</a>\r\n</p>\r\n\r\n<h3>Contact Information</h3>\r\n<p>\r\n<strong>Central Selection Board of Constables (CSBC), Bihar</strong><br>\r\nAddress: Sardar Patel Bhawan, Police Headquarters, Patna, Bihar - 800001<br>\r\nEmail: csbc.bihar@gmail.com<br>\r\nHelpline: 0612-2215432\r\n</p>\r\n\r\n<p><strong>Tags:</strong> Bihar Police Constable Result 2026, CSBC Bihar Result, Bihar Police Sipahi Result, Bihar Police Final Selection List, Bihar Police Cutoff 2026, Bihar Police Recruitment 2025, CSBC Constable Result, Bihar Government Jobs, Sarkari Result</p>', 'Total Vacancies: 19,838 Posts. Department-wise: Bihar Police-16,852, BSAP-2,986. Category-wise: General-7,935, EWS-1,983, SC-3,174, ST-199, EBC-3,571, BC-2,381, BCW-595. Gender-wise: Male-12,509, Female-7,312, Transgender-17. Special Quota: Homeguard-332, Freedom Fighter Dependents-190.', '2025-03-11', '2025-04-15', '2025-04-15', '2025-04-20', '2025-07-16', '2025-07-01', '2026-05-27', '2025-08-01', 'As per CSBC norms', 'As per CSBC norms', 'As per CSBC norms', 'Online', NULL, '18 Years', '25 Years', 'As per Bihar government rules for SC/ST/OBC/EWS categories', NULL, '19838', 'Bihar', '10+2 (Intermediate) pass from any recognized board.', 'NCC Certificate, Homeguard Service Certificate, Computer Knowledge, Driving License (preferred but not mandatory)', 'No prior experience required. Freshers are eligible.', 'Stage 1: Written Examination (Computer Based Test)\r\nStage 2: Physical Efficiency Test (PET)\r\nStage 3: Document Verification\r\nStage 4: Medical Examination\r\nStage 5: Final Merit List based on performance in all stages', 'Application process is closed. Final Result has been declared on 27 May 2026. Selected candidates must report for joining between 20 June 2026 to 19 July 2026 at their allotted district/battalion. Check official CSBC website for joining instructions.', 'https://csbc.bihar.gov.in', 'https://csbc.bihar.gov.in', 'https://csbc.bihar.gov.in', 'https://csbc.bihar.gov.in', 'https://csbc.bihar.gov.in/Result/Final_Selection_Constable_Advt_01_2025.pdf', 'https://csbc.bihar.gov.in', 'https://csbc.bihar.gov.in', 'https://csbc.bihar.gov.in', NULL, NULL, NULL, 'Bihar Police CSBC Constable Final Result 2026 Declared - 19,838 Selected', 'CSBC Bihar Police Constable (Sipahi) Recruitment 2025 Final Result 2026 declared on 27 May 2026. 19,838 candidates selected for Bihar Police and BSAP. Category-wise cutoff: General Male-76, Female-72. Joining from 20 June to 19 July 2026.', 'Bihar Police Constable Result 2026, CSBC Bihar Result, Bihar Police Sipahi Result, Bihar Police Final Selection List, Bihar Police Cutoff 2026, Bihar Police Recruitment 2025, CSBC Constable Result, Bihar Government Jobs, Sarkari Result, Bihar Police Bharti 2026', 1, 0, 51, '2026-05-28 08:17:59', '2026-07-12 15:19:42'),
(38, 'National Aluminium Company Limited NALCO Non Executive Recruitment 2026', 'national-aluminium-company-limited-nalco-non-executive-recruitment-2026', 9, 'NALCO Non Executive Recruitment 2026 for 268 posts of Operator, Technician, Mining Mate, Foreman & various other posts. Apply online from 21 May to 10 June 2026. Eligibility: 10th+ITI/Diploma/B.Sc. Age limit: 18-40 years (post wise).', '<h2>NALCO Non Executive Recruitment 2026</h2>\r\n<p>The <strong>National Aluminium Company Limited (NALCO)</strong>, a Navratna Central Public Sector Enterprise (CPSE) under the Ministry of Mines, Government of India, has released the official notification for recruitment of <strong>Non-Executive Personnel</strong> for its Mines & Refinery (M&R) Complex at Damanjodi, Koraput District, Odisha [citation:2][citation:5]. This is a prestigious opportunity for candidates seeking government PSU jobs in the technical and industrial sector.</p>\r\n\r\n<h3>Important Dates</h3>\r\n<ul>\r\n<li><strong>Notification Release Date:</strong> 14 May 2026</li>\r\n<li><strong>Application Start Date:</strong> 21 May 2026 (10:00 Hrs)</li>\r\n<li><strong>Last Date to Apply Online:</strong> 10 June 2026 (23:55 Hrs)</li>\r\n<li><strong>Last Date for Fee Payment:</strong> 10 June 2026</li>\r\n<li><strong>Application Correction Date:</strong> To be notified</li>\r\n<li><strong>Admit Card Release Date:</strong> To be notified</li>\r\n<li><strong>CBT Exam Date:</strong> To be notified</li>\r\n<li><strong>Trade Test Date:</strong> To be notified</li>\r\n<li><strong>Result Date:</strong> To be notified</li>\r\n</ul>\r\n\r\n<h3>Application Fee</h3>\r\n<ul>\r\n<li><strong>General / OBC (NCL) / EWS:</strong> ₹ 100/-</li>\r\n<li><strong>SC / ST / PwBD / Ex-Servicemen / Land Ousted / Internal Candidates:</strong> ₹ 0/- (Exempted)</li>\r\n<li><strong>Payment Mode:</strong> Online (Debit Card, Credit Card, Net Banking, UPI) [citation:3][citation:4][citation:10]</li>\r\n</ul>\r\n\r\n<h3>Age Limit (as on 10 June 2026)</h3>\r\n<ul>\r\n<li><strong>Minimum Age:</strong> 18 Years</li>\r\n<li><strong>Maximum Age:</strong> 27-40 Years (Post wise)</li>\r\n<li><strong>Age Relaxation:</strong> As per government rules [citation:2][citation:3]</li>\r\n<li>• OBC (NCL): 3 Years</li>\r\n<li>• SC/ST: 5 Years</li>\r\n<li>• PwBD: 10 Years</li>\r\n</ul>\r\n\r\n<h3>Educational Qualification</h3>\r\n<p>Candidates must possess qualifications as per post requirements: [citation:1][citation:5]</p>\r\n\r\n<h4>For Technician/Operator Posts:</h4>\r\n<ul>\r\n<li>Class 10th (Matriculation) pass from recognized board</li>\r\n<li>ITI certificate in relevant trade from NCVT/NCVET</li>\r\n</ul>\r\n\r\n<h4>For Foreman Posts:</h4>\r\n<ul>\r\n<li>Diploma in Engineering in relevant discipline</li>\r\n</ul>\r\n\r\n<h4>For Laboratory Posts:</h4>\r\n<ul>\r\n<li>B.Sc. (Hons) in Chemistry from recognized university</li>\r\n</ul>\r\n\r\n<h3>Experience Required</h3>\r\n<ul>\r\n<li><strong>Technician (Electrical) Grade:</strong> Minimum 2 years experience</li>\r\n<li><strong>Technician (Instrumentation/Instrument Mechanic) Grade:</strong> Minimum 2 years experience</li>\r\n<li><strong>Operator (HEMM):</strong> Minimum 1 year experience in Diesel Mechanic Trade</li>\r\n<li><strong>Other Technical Posts:</strong> Experience as per post requirement [citation:2][citation:5]</li>\r\n</ul>\r\n\r\n<h3>Vacancy Details</h3>\r\n<p><strong>Total Posts:</strong> 268</p>\r\n\r\n<h4>Post-wise Vacancy Distribution:</h4>\r\n<ul>\r\n<li><strong>Operator (HEMM) Grade-III:</strong> 06 Posts</li>\r\n<li><strong>Mining Mate Grade-III:</strong> 21 Posts</li>\r\n<li><strong>Junior Foreman (Mines):</strong> 08 Posts</li>\r\n<li><strong>Junior Foreman (Electrical):</strong> 03 Posts</li>\r\n<li><strong>Superintendent (JOT) - Operator:</strong> 55 Posts</li>\r\n<li><strong>Operator Grade-III:</strong> 54 Posts</li>\r\n<li><strong>Superintendent (JOT) - Fitter:</strong> 12 Posts</li>\r\n<li><strong>Technician (Fitter) Grade-III:</strong> 13 Posts</li>\r\n<li><strong>Superintendent (JOT) - Electrical:</strong> 35 Posts</li>\r\n<li><strong>Technician (Electrical) Grade-III:</strong> 35 Posts</li>\r\n<li><strong>Superintendent (JOT) - Laboratory:</strong> 06 Posts</li>\r\n<li><strong>Superintendent (JOT) - Instrumentation/Instrument Mechanic:</strong> 10 Posts</li>\r\n<li><strong>Technician (Instrumentation/Instrument Mechanic) Grade-III:</strong> 10 Posts [citation:2][citation:4]</li>\r\n</ul>\r\n\r\n<h4>Salary & Pay Scale</h4>\r\n<ul>\r\n<li><strong>T0 Grade (Induction Level):</strong> ₹ 29,500 – 3% – ₹ 70,000/- per month</li>\r\n<li><strong>S0 Grade (Induction Level - Jr. Foreman):</strong> ₹ 36,500 – 3% – ₹ 1,15,000/- per month [citation:2][citation:4]</li>\r\n</ul>\r\n\r\n<h4>Job Location</h4>\r\n<p>Mines & Refinery (M&R) Complex, Damanjodi, Koraput District, Odisha [citation:2][citation:4]</p>\r\n\r\n<h3>Selection Process</h3>\r\n<p>The selection will be based on the following stages: [citation:2][citation:7]</p>\r\n<ol>\r\n<li><strong>Computer Based Test (CBT):</strong> Objective type written examination</li>\r\n<li><strong>Trade Test / Skill Test:</strong> Qualifying in nature for select posts</li>\r\n<li><strong>Document Verification (DV):</strong> Verification of original certificates</li>\r\n<li><strong>Pre-Employment Medical Examination (PEME):</strong> Medical fitness as per NALCO norms</li>\r\n</ol>\r\n\r\n<h3>Exam Pattern (CBT)</h3>\r\n<ul>\r\n<li><strong>Mode of Exam:</strong> Online Computer Based Test</li>\r\n<li><strong>Duration:</strong> To be notified</li>\r\n<li><strong>Total Questions:</strong> To be notified</li>\r\n<li><strong>Total Marks:</strong> To be notified</li>\r\n<li><strong>Subjects:</strong> Technical/Domain (60%) + General Awareness (40%) [citation:7]</li>\r\n<li><strong>Negative Marking:</strong> As per official notification</li>\r\n</ul>\r\n\r\n<h3>How to Apply for NALCO Non Executive 2026</h3>\r\n<p>Candidates can apply online through the official NALCO website. Follow these steps: [citation:5]</p>\r\n<ol>\r\n<li>Visit the official NALCO website: <strong>https://www.nalcoindia.com</strong></li>\r\n<li>Click on \"Careers\" section and select \"Recruitment of Non-Executive Personnel - M&R Complex, Damanjodi\"</li>\r\n<li>Complete One Time Registration (OTR) if not already registered</li>\r\n<li>Fill the detailed application form with personal, educational, and contact details</li>\r\n<li>Upload scanned photo, signature, and other required documents</li>\r\n<li>Pay application fee online (₹ 100 for General/OBC, free for SC/ST)</li>\r\n<li>Submit the application form and take a printout for future reference</li>\r\n</ol>\r\n\r\n<h3>Documents Required</h3>\r\n<ul>\r\n<li>10th Mark Sheet & Certificate</li>\r\n<li>ITI Certificate & Mark Sheet (for technical posts)</li>\r\n<li>Diploma Certificate & Mark Sheets (for Foreman posts)</li>\r\n<li>B.Sc. Degree Certificate & Mark Sheets (for Laboratory posts)</li>\r\n<li>Experience Certificate (as per post requirement)</li>\r\n<li>Caste Certificate (OBC/SC/ST, if applicable)</li>\r\n<li>EWS Certificate (if applicable)</li>\r\n<li>PwBD Certificate (if applicable)</li>\r\n<li>Recent Passport Size Photograph (10-50 KB, JPEG format)</li>\r\n<li>Signature (10-20 KB, JPEG format)</li>\r\n<li>Valid Email ID & Mobile Number</li>\r\n<li>Aadhar Card (recommended)</li>\r\n</ul>\r\n\r\n<h3>Important Information</h3>\r\n<ul>\r\n<li><strong>Organization Type:</strong> Navratna Central Public Sector Enterprise (CPSE) [citation:2]</li>\r\n<li><strong>Advertisement No.:</strong> 10260213 dated 14.05.2026 [citation:2]</li>\r\n<li><strong>Citizenship:</strong> Must be a citizen of India</li>\r\n<li><strong>Number of Attempts:</strong> No limit on attempts (age limit applicable)</li>\r\n<li><strong>Training:</strong> Selected candidates will undergo training at NALCO facilities</li>\r\n<li><strong>Bond Requirement:</strong> As per company policy</li>\r\n</ul>\r\n\r\n<h3>NALCO Non Executive Recruitment 2026 - Highlights</h3>\r\n<ul>\r\n<li>Total 268 vacancies across 13 different technical positions</li>\r\n<li>Application period: 21 May to 10 June 2026</li>\r\n<li>Application fee: ₹100 for General/OBC, free for SC/ST/PwBD</li>\r\n<li>Eligibility: 10th+ITI / Diploma / B.Sc</li>\r\n<li>Age limit: 18-40 years (post wise)</li>\r\n<li>Salary: Up to ₹1,15,000 per month</li>\r\n<li>Job location: Damanjodi, Koraput, Odisha</li>\r\n<li>Selection: CBT + Trade Test + Document Verification + Medical Examination [citation:1][citation:2][citation:4]</li>\r\n</ul>\r\n\r\n<p><strong>Important Links:</strong><br />\r\n<a href=\"https://www.nalcoindia.com\" target=\"_blank\" rel=\"noopener\">✅ Apply Online (NALCO Official Website)</a><br />\r\n<a href=\"https://www.nalcoindia.com/careers\" target=\"_blank\" rel=\"noopener\">📥 Careers Section</a><br />\r\n<a href=\"notifications/nalco_non_executive_2026_notification.pdf\" target=\"_blank\" rel=\"noopener\">📄 Download Official Notification PDF</a><br />\r\n<a href=\"notifications/nalco_non_executive_2026_syllabus.pdf\" target=\"_blank\" rel=\"noopener\">📚 Download Syllabus PDF</a><br />\r\n<a href=\"https://www.nalcoindia.com/recruitment-status\" target=\"_blank\" rel=\"noopener\">🔍 Check Application Status</a></p>\r\n\r\n<p><strong>Tags:</strong> NALCO Recruitment 2026, NALCO Non Executive Vacancy, PSU Jobs 2026, NALCO Technician Recruitment, NALCO Operator Recruitment, NALCO Mining Mate, Government PSU Jobs, Odisha Jobs, NALCO Damanjodi, NALCO Navratna Company, Sarkari Result</p>', 'Total Vacancies: 268 Posts across 13 categories. Post-wise: Operator (HEMM) Gr.III-6, Mining Mate Gr.III-21, Jr. Foreman (Mines)-8, Jr. Foreman (Electrical)-3, SUPT(JOT)-Operator-55, Operator Gr.III-54, SUPT(JOT)-Fitter-12, Technician (Fitter) Gr.III-13, SUPT(JOT)-Electrical-35, Technician (Electrical) Gr.III-35, SUPT(JOT)-Laboratory-6, SUPT(JOT)-Instrumentation-10, Technician (Instrumentation) Gr.III-10. Location: M&R Complex, Damanjodi, Odisha. [citation:2][citation:4]', '2026-05-21', '2026-06-10', '2026-06-10', NULL, NULL, NULL, NULL, '2026-06-10', '₹ 100/-', '₹ 0/- (Exempted)', '₹ 100/-', 'Online (Debit Card, Credit Card, Net Banking, UPI)', 100.00, '18 Years', '40 Years', 'OBC (NCL): 3 years, SC/ST: 5 years, PwBD: 10 years', '18-40 years (Post wise: 18-27/35/40 years depending on post)', '268', 'Mines & Refinery (M&R) Complex, Damanjodi, Koraput District, Odisha', '10th pass with ITI NCVT/NCVET certificate in relevant trade OR Diploma in Engineering OR B.Sc. (Hons) in Chemistry (post wise). Read official notification for post-specific qualification details.', 'NCC Certificate, Computer proficiency, Knowledge of Odia language (preferred), Industrial safety certificates.', '2 years experience for Technician (Electrical & Instrumentation) posts, 1 year experience for Operator (HEMM) posts. Experience required in relevant trade from recognized organization. Freshers may apply for some posts as per notification.', 'Stage 1: Computer Based Test (CBT) - Technical/Domain (60%) + General Awareness (40%)\r\nStage 2: Trade Test / Skill Test - Qualifying in nature for select posts\r\nStage 3: Document Verification (DV) - Original certificates verification\r\nStage 4: Pre-Employment Medical Examination (PEME) - Medical fitness as per NALCO norms\r\nFinal Merit List based on CBT marks and successful completion of all stages [citation:2][citation:7]', 'Apply online through official NALCO website (www.nalcoindia.com) from 21 May 2026 to 10 June 2026. Complete One Time Registration (OTR), fill application form with personal, educational and contact details, upload scanned documents (photo, signature, certificates), pay application fee (₹ 100 for General/OBC, free for SC/ST/PwBD), submit form, and take printout for future reference. [citation:3][citation:5]', 'https://www.nalcoindia.com', 'https://www.nalcoindia.com', 'https://www.nalcoindia.com', 'https://www.nalcoindia.com', 'https://www.nalcoindia.com', 'https://www.nalcoindia.com', 'https://www.nalcoindia.com', 'https://www.nalcoindia.com', 'notifications/nalco_non_executive_2026_notification.pdf', 'notifications/nalco_non_executive_2026_short_notification.pdf', 'notifications/nalco_non_executive_2026_syllabus.pdf', 'NALCO Non Executive Recruitment 2026 - Apply Online for 268 Posts', 'National Aluminium Company Limited (NALCO) Non Executive Recruitment 2026 for 268 posts of Operator, Technician, Mining Mate, Foreman & more. Eligibility: 10th+ITI/Diploma/B.Sc. Age: 18-40 years. Fee: ₹100/- (SC/ST/PwBD free). Apply online from 21 May to 10 June 2026.', 'NALCO Recruitment 2026, NALCO Non Executive Vacancy, NALCO Technician, NALCO Operator, NALCO Mining Mate, PSU Jobs 2026, Government PSU Jobs, NALCO Damanjodi Recruitment, Navratna Company Jobs, Odisha Govt Jobs, NALCO Notification 2026, Sarkari Result', 1, 1, 88, '2026-05-28 08:27:45', '2026-07-12 15:19:46');
INSERT INTO `jobs` (`id`, `title`, `slug`, `category_id`, `short_description`, `description`, `vacancy_details`, `start_date`, `last_date`, `fee_last_date`, `correction_date`, `exam_date`, `admit_card_date`, `result_date`, `age_calculation_date`, `fee_general`, `fee_sc_st_female`, `fee_other`, `payment_mode`, `application_fee`, `min_age`, `max_age`, `age_relaxation`, `age_limit`, `total_post`, `job_location`, `qualification`, `additional_qualification`, `experience_required`, `selection_process`, `how_to_apply`, `application_link`, `registration_link`, `login_link`, `admit_card_link`, `result_link`, `answer_key_link`, `syllabus_link`, `official_website`, `notification_pdf`, `short_notification_pdf`, `syllabus_pdf`, `meta_title`, `meta_description`, `meta_keywords`, `is_active`, `is_featured`, `views`, `created_at`, `updated_at`) VALUES
(39, 'Allahabad High Court RO ARO Computer Assistant Recruitment 2026', 'allahabad-high-court-ro-aro-computer-assistant-2026', 1, 'Allahabad High Court has released notification for Review Officer (RO), Assistant Review Officer (ARO), and Computer Assistant posts. Apply online from 01 June to 21 June 2026.', '<p>The High Court of Judicature at Allahabad has released Advertisement No. 02/Review Officer/Assistant Review Officer/Computer Assistant/2026 for the recruitment of Review Officer (RO), Assistant Review Officer (ARO), and Computer Assistant posts. This is a great opportunity for graduates with computer qualifications to join the Allahabad High Court establishment. The selection process consists of a Single MCQ-Based Exam followed by a Skill Test/Typing Test.</p>\r\n\r\n<h3>Post Details</h3>\r\n<ul>\r\n<li><strong>Review Officer (RO):</strong> 138 vacancies</li>\r\n<li><strong>Assistant Review Officer (ARO):</strong> 380 vacancies</li>\r\n<li><strong>Computer Assistant:</strong> 25 vacancies</li>\r\n</ul>\r\n\r\n<h3>Salary Structure</h3>\r\n<ul>\r\n<li><strong>Review Officer (RO):</strong> Level 8 - Rs. 47,600 to Rs. 1,51,100</li>\r\n<li><strong>Assistant Review Officer (ARO):</strong> Level 7 - Rs. 44,900 to Rs. 1,42,400</li>\r\n<li><strong>Computer Assistant:</strong> Level 4 - Rs. 26,600 to Rs. 81,100</li>\r\n</ul>', '<strong>Total Vacancies:</strong> 543<br>\r\n<strong>Review Officer (RO):</strong> 138 posts<br>\r\n<strong>Assistant Review Officer (ARO):</strong> 380 posts<br>\r\n<strong>Computer Assistant:</strong> 25 posts', '2026-06-01', '2026-06-21', '2026-06-22', NULL, NULL, NULL, NULL, '2026-07-01', '1200.00', '1000.00', '1200.00', 'Online (Net Banking / Debit Card / Credit Card / UPI)', 1200.00, '21', '35', 'As per UP Govt Rules 1976 for SC/ST/OBC/EWS/PwD of Uttar Pradesh', '21-35 years (RO/ARO), 18-35 years (Computer Assistant)', '543', 'Prayagraj (Allahabad), Uttar Pradesh', '<strong>Bachelor Degree </strong> from a university established by law in India or equivalent.<br>\r\n- O Level certificate<br>\r\n- CCC Certificate<br>\r\n<strong>AND Typing Speed:</strong> Minimum 25 WPM in English on computer.<br>\r\n<strong>AND Computer Skills:</strong> Knowledge of Data Entry, Word Processing, and Computer Operation.', 'Experience in computer operations/data entry preferred but not mandatory.', 'No prior experience required for RO/ARO posts. For Computer Assistant, basic computer proficiency is mandatory.', '<strong>Stage 1:</strong> Single MCQ-Based Written Examination (200 questions, 200 marks, 3 hours)<br>\r\n<strong>Stage 2:</strong> Computer Typing Test / Skill Test (50 marks, 20 minutes, qualifying nature - minimum 25 marks required)<br>\r\n<strong>Subjects:</strong> General Science, History of India, Indian National Movement, Indian Polity, Economy, Culture, Agriculture, Commerce, Trade, Population, Ecology, Urbanisation, World Geography, Indian Geography, Current Affairs, General Aptitude, UP GK, General English & Hindi (Graduation Level), Elementary Computer Knowledge.<br>\r\n<strong>Marking Scheme:</strong> +1 mark per correct answer, No negative marking.', '<strong>Step 1:</strong> Visit the official website of Allahabad High Court at www.allahabadhighcourt.in or directly visit https://exams.nta.nic.in/allhcre<br>\r\n<strong>Step 2:</strong> Click on the \"Recruitments\" section and read the full notification<br>\r\n<strong>Step 3:</strong> Click on \"Apply Online for RO ARO 2026\"<br>\r\n<strong>Step 4:</strong> Complete the registration form with basic details (Name, Mother\'s Name, Father\'s Name, Email ID, Mobile No.)<br>\r\n<strong>Step 5:</strong> Fill out the online application form and note down the system-generated Registration Number<br>\r\n<strong>Step 6:</strong> Upload scanned photograph, left-hand thumb impression, and signature<br>\r\n<strong>Step 7:</strong> Pay the application fee online via Net Banking, Debit Card, Credit Card, or UPI<br>\r\n<strong>Step 8:</strong> Submit the form and download a printout for future reference.', 'https://exams.nta.nic.in/allhcre', 'https://exams.nta.nic.in/allhcre', 'https://exams.nta.nic.in/allhcre', NULL, NULL, NULL, 'https://www.allahabadhighcourt.in/recruitments.jsp', 'https://www.allahabadhighcourt.in', 'https://www.allahabadhighcourt.in/recruitments/RO_ARO_CA_2026_Notification.pdf', 'https://www.allahabadhighcourt.in/recruitments/RO_ARO_CA_2026_ShortNotice.pdf', 'https://www.allahabadhighcourt.in/recruitments/RO_ARO_CA_2026_Syllabus.pdf', 'Allahabad High Court RO ARO Computer Assistant Recruitment 2026 - 543 Vacancies | Apply Online', 'Apply online for Allahabad High Court Review Officer (RO), Assistant Review Officer (ARO), and Computer Assistant Recruitment 2026. 543 vacancies, Bachelor Degree with Computer Qualification required. Apply from 01-21 June 2026.', 'Allahabad High Court, RO Recruitment, ARO Recruitment, Computer Assistant, Allahabad High Court Vacancy 2026, UP Govt Jobs, High Court Jobs, AHC RO 2026, AHC ARO 2026, Sarkari Result', 1, 1, 75, '2026-06-01 07:39:17', '2026-07-12 00:05:25'),
(40, 'UP Police Constable Recruitment 2025', 'up-police-constable-recruitment-2025', 1, 'The Uttar Pradesh Police Recruitment and Promotion Board (UPPRPB) has released the exam city details (City Intimation Slip) for the UP Police Constable Recruitment 2025. Candidates who have applied for the 32,679 vacancies of Constable (Civil Police) and equivalent posts can now check their allotted exam city on the official website.', 'The Uttar Pradesh Police Recruitment and Promotion Board (UPPRPB) has released the exam city details (City Intimation Slip) for the UP Police Constable Recruitment 2025. Candidates who have applied for the 32,679 vacancies of Constable (Civil Police) and equivalent posts can now check their allotted exam city on the official website.', NULL, '2026-01-01', '2026-01-31', '2026-01-31', '2026-02-06', '2026-06-08', '2026-06-05', NULL, NULL, '₹ 600/-', '₹ 0/- (Exempted)', NULL, 'Debit Card, Credit Card, Net Banking', NULL, '18 Years', '27 Years', 'As per government rules', NULL, '32000', 'All India', NULL, NULL, NULL, NULL, NULL, 'https://uppbpb.gov.in', 'https://uppbpb.gov.in', 'https://uppbpb.gov.in', 'https://uppbpb.gov.in', 'https://uppbpb.gov.in', NULL, NULL, 'https://uppbpb.gov.in', NULL, NULL, NULL, NULL, NULL, NULL, 1, 0, 33, '2026-06-02 13:27:14', '2026-07-11 21:47:43'),
(41, 'IBPS PO MT XVI Online Form 2026', 'ibps-po-mt-xvi-online-form-2026', 10, 'Institute of Banking Personnel Selection (IBPS) has released notification for Probationary Officer (PO) Management Trainee XVI Recruitment 2026. Apply online for 4500+ vacancies.', '<h2>IBPS PO MT XVI Recruitment 2026</h2><p>Institute of Banking Personnel Selection (IBPS) invites online applications from eligible Indian citizens for appointment as Probationary Officer (PO) / Management Trainee in participating banks. The selection will be based on Preliminary Examination, Main Examination, and Interview.</p><h3>Important Dates:</h3><ul><li>Application Start: 01 July 2026</li><li>Last Date to Apply: 21 July 2026</li><li>Fee Payment Last Date: 21 July 2026</li><li>Pre Exam Date: August 2026</li></ul>', 'Total Vacancies: 4500+ (Approx)\n\nCategory-wise Breakup:\n- General: 1800\n- OBC: 1200\n- SC: 675\n- ST: 337\n- EWS: 488', '2026-07-01', '2026-08-30', '2026-07-21', '2026-07-25', '2026-08-15', '2026-08-10', '2026-09-15', '2026-07-01', '850', '175', '850', 'Online (Debit Card/Credit Card/Net Banking/UPI)', 850.00, '20', '30', 'SC/ST - 5 years, OBC - 3 years, PWD - 10 years', '20-30 Years (Relaxation as per govt rules)', '4500', 'All India', 'Graduation Degree in any discipline from recognized university. Must have valid Mark sheet/Degree Certificate.', 'Computer proficiency preferred. Knowledge of regional language will be an added advantage.', 'Freshers can apply. No prior experience required.', 'Preliminary Examination (Objective Type - 100 marks)\r\n Main Examination (Objective + Descriptive - 200 marks)\r\nInterview (50 marks)\r\nFinal Merit List', '<p>Candidates can apply online through IBPS official website www.ibps.in from 01 July 2026 to 21 July 2026.</p><ol><li>Visit IBPS official website</li><li>Click on \"CRP PO MT XVI\"</li><li>Register with valid email and mobile number</li><li>Fill personal and educational details</li><li>Upload scanned photo, signature, and documents</li><li>Pay application fee online</li><li>Submit and take printout</li></ol>', 'https://ibps.sifyitest.com/crppo16/', 'https://ibps.sifyitest.com/crppo16/', 'https://ibps.sifyitest.com/crppo16/', 'https://ibps.sifyitest.com/crppo16/admit.php', 'https://ibps.sifyitest.com/crppo16/result.php', 'https://ibps.sifyitest.com/crppo16/answerkey.php', 'https://ibps.sifyitest.com/crppo16/syllabus.php', 'https://www.ibps.in', 'https://www.ibps.in/wp-content/uploads/2026/06/CRP-PO-MT-XVI-Notification.pdf', 'https://www.ibps.in/wp-content/uploads/2026/06/CRP-PO-MT-XVI-Short-Notification.pdf', 'https://www.ibps.in/wp-content/uploads/2026/06/CRP-PO-MT-XVI-Syllabus.pdf', 'IBPS PO MT XVI Online Form 2026 - Apply for 4500+ Vacancies', 'Apply online for IBPS PO MT XVI Recruitment 2026. Check eligibility, important dates, application fee, selection process and apply online for 4500+ Probationary Officer vacancies.', 'IBPS PO 2026, IBPS PO MT XVI, IBPS Recruitment 2026, Bank PO Jobs 2026, Probationary Officer Jobs, IBPS Online Form 2026, Banking Jobs', 1, 0, 18, '2026-07-10 04:30:00', '2026-07-31 01:46:28'),
(42, 'IBPS SO XVI Online Form 2026', 'ibps-so-xvi-online-form-2026', 10, 'Institute of Banking Personnel Selection (IBPS) has released notification for Specialist Officer (SO) CRP SPL-XVI Recruitment 2026. Apply online for 745 vacancies in various specialist posts.', '<h2>IBPS SO XVI Recruitment 2026</h2><p>Institute of Banking Personnel Selection (IBPS) invites online applications from eligible Indian citizens for appointment as Specialist Officers (Scale I) in participating banks under the Common Recruitment Process (CRP SPL-XVI) for the 2027-28 cycle [citation:1][citation:3]. The selection will be based on Preliminary Examination, Main Examination, and Interview [citation:5][citation:11].</p><h3>Important Dates:</h3><ul><li>Application Start: 01 July 2026</li><li>Last Date to Apply: 21 July 2026</li><li>Fee Payment Last Date: 21 July 2026</li><li>Pre Exam Date: 29 August 2026</li><li>Main Exam Date: 01 November 2026</li></ul><p><strong>Note:</strong> Marketing Officer post has 0 vacancies in 2026 [citation:2][citation:3].</p>', 'Total Vacancies: 745\n\nPost-wise Breakup [citation:1][citation:2][citation:8]:\n- IT Officer: 301\n- Agricultural Field Officer (AFO): 190\n- Law Officer: 105\n- Rajbhasha Adhikari: 89\n- HR/Personnel Officer: 60\n- Marketing Officer: 0', '2026-07-01', '2026-08-30', '2026-07-21', '2026-07-22', '2026-08-29', '2026-08-25', '2026-10-15', '2026-07-01', '850', '175', '850', 'Online (Debit Card/Credit Card/Net Banking/UPI)', 850.00, '20', '30', 'SC/ST - 5 years, OBC - 3 years, PwBD - 10 years, Ex-Servicemen - 5 years', '20-30 Years (Relaxation as per govt rules)', '745', 'All India', 'Post-specific qualifications required:\n\nIT Officer: B.E./B.Tech in CS/IT/Electronics OR M.Sc./MCA in relevant field [citation:1][citation:9]\n\nAgricultural Field Officer: 4-year degree in Agriculture/Horticulture/Animal Husbandry/Forestry etc.', 'Computer proficiency preferred for all posts (except IT Officer). Knowledge of regional language will be an added advantage.', 'Freshers can apply.', '<ol><li>Preliminary Examination (Qualifying Stage)</li><li>Main Examination (Professional Knowledge - 200 marks)</li><li>Interview (Weightage as per IBPS norms)</li><li>Final Merit List based on Main Exam + Interview marks [citation:3][citation:5]</li></ol>', '<p>Candidates can apply online through IBPS official website www.ibps.in from 01 July 2026 to 21 July 2026 [citation:1][citation:5].</p><ol><li>Visit IBPS official website (www.ibps.in)</li><li>Click on \"CRP Specialist Officers (CRP-SPL-XVI)\"</li><li>Click on \"New Registration\" and fill basic details [citation:1]</li><li>Generate Provisional Registration Number and Password</li><li>Login with credentials and fill personal and educational details</li><li>Upload scanned photo, signature, and required documents [citation:8]</li><li>Pay application fee online via Debit Card/Credit Card/Net Banking/UPI</li><li>Preview and verify all details before final submission [citation:1]</li><li>Submit and take printout of confirmation page</li></ol>', 'https://ibps.sifyitest.com/crpspl16/', 'https://ibps.sifyitest.com/crpspl16/', 'https://ibps.sifyitest.com/crpspl16/', 'https://ibps.sifyitest.com/crpspl16/admit.php', 'https://ibps.sifyitest.com/crpspl16/result.php', 'https://ibps.sifyitest.com/crpspl16/answerkey.php', 'https://ibps.sifyitest.com/crpspl16/syllabus.php', 'https://www.ibps.in', 'https://www.ibps.in/wp-content/uploads/2026/06/CRP-SPL-XVI-Notification.pdf', 'https://www.ibps.in/wp-content/uploads/2026/06/CRP-SPL-XVI-Short-Notification.pdf', 'https://www.ibps.in/wp-content/uploads/2026/06/CRP-SPL-XVI-Syllabus.pdf', 'IBPS SO XVI Online Form 2026 - Apply for 745 Specialist Officer Vacancies', 'Apply online for IBPS SO XVI Recruitment 2026 (CRP SPL-XVI). Check eligibility, important dates, application fee, post-wise vacancies and apply for Specialist Officer posts.', 'IBPS SO 2026, IBPS SO XVI, CRP SPL-XVI, Specialist Officer Recruitment 2026, IT Officer Vacancy, Agriculture Field Officer, Law Officer, Rajbhasha Adhikari, HR Officer, Bank Jobs 2026', 1, 0, 13, '2026-07-10 04:30:00', '2026-07-31 01:46:28'),
(44, 'UPSC Civil Services CSE Preliminary Examination 2026 Online Form', 'upsc-civil-services-cse-preliminary-examination-2026-online-form', 4, 'Union Public Service Commission (UPSC) has published notification for Civil Services Prelims 2026. Eligible candidates can apply online.', 'Union Public Service Commission (UPSC) Civil Services (Preliminary) Examination 2026.\n\nTotal Posts: 1056\nAge Limit: 21-32 Years as on 01/08/2026.\nQualification: Bachelor Degree in Any Stream from Any Recognized University in India.', NULL, '2026-07-15', '2026-08-25', '2026-08-25', NULL, '2026-09-20', NULL, NULL, NULL, '100.00', '0.00', '100.00', 'Net Banking, Credit/Debit Card, UPI', NULL, '21', '32', 'As per government rules', NULL, '1056 Posts', 'All India', 'Bachelor Degree in Any Stream', NULL, NULL, 'Preliminary Exam, Main Exam, Interview', 'Visit upsc.gov.in and register in OTR platform to fill application.', 'https://upsconline.nic.in', NULL, NULL, NULL, NULL, NULL, NULL, 'https://upsc.gov.in', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1, 1, '2026-07-31 01:28:01', '2026-07-31 01:46:28'),
(45, 'SSC CGL Combined Graduate Level Examination 2026 Online Form', 'ssc-cgl-combined-graduate-level-examination-2026-online-form', 3, 'Staff Selection Commission (SSC) invites online applications for Combined Graduate Level CGL 2026 for 14,760 vacancies in various central departments.', 'Staff Selection Commission (SSC) CGL Recruitment 2026.\n\nTotal Posts: 14760\nAge Limit: 18-30 Years (Post wise).\nQualification: Graduate Degree in Any Stream.', NULL, '2026-07-15', '2026-08-25', '2026-08-31', NULL, '2026-10-05', NULL, NULL, NULL, '100.00', '0.00', '100.00', 'Online Fee Payment Mode Only', NULL, '18', '30', 'As per government rules', NULL, '14760 Posts', 'All India', 'Graduation Degree in Any Recognized University', NULL, NULL, 'Tier-I Computer Based Exam, Tier-II Computer Based Exam, Document Verification', 'Apply online through SSC official portal ssc.gov.in.', 'https://ssc.gov.in', NULL, NULL, NULL, NULL, NULL, NULL, 'https://ssc.gov.in', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1, 0, '2026-07-31 01:28:01', '2026-07-31 01:46:28'),
(46, 'RRB NTPC Non-Technical Popular Categories Recruitment 2026', 'rrb-ntpc-non-technical-popular-categories-recruitment-2026', 2, 'Railway Recruitment Boards (RRB) has released notification for 11,558 NTPC Graduate & Under Graduate Posts.', 'Railway Recruitment Board (RRB) NTPC Recruitment 2026.\n\nTotal Posts: 11558\nPosts: Station Master, Goods Guard, Senior Clerk, Junior Clerk, Commercial Apprentice.\nQualification: 12th Pass / Graduate Degree.', NULL, '2026-07-15', '2026-08-25', '2026-08-22', NULL, '2026-11-15', NULL, NULL, NULL, '500.00', '250.00', '500.00', 'Debit Card, Credit Card, Net Banking, E-Challan', NULL, '18', '33', 'As per government rules', NULL, '11558 Posts', 'Across India (All RRB Zones)', '10+2 Intermediate OR Graduate Degree', NULL, NULL, 'CBT 1, CBT 2, Typing Skill Test / CBAT, Document Verification', 'Select your RRB zone portal and complete online registration.', 'https://rrbapply.gov.in', NULL, NULL, NULL, NULL, NULL, NULL, 'https://indianrailways.gov.in', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1, 0, '2026-07-31 01:28:01', '2026-07-31 01:46:28'),
(47, 'IBPS Probationary Officer PO / MT XV Recruitment 2026 (4455 Posts)', 'ibps-probationary-officer-po-mt-xv-recruitment-2026-4455-posts', 10, 'Institute of Banking Personnel Selection (IBPS) invites applications for 4455 PO / Management Trainee posts in participating public sector banks.', 'IBPS PO / MT XV Recruitment 2026.\n\nTotal Vacancies: 4455\nParticipating Banks: Bank of Baroda, Canara Bank, Punjab National Bank, Union Bank of India & others.\nAge Limit: 20-30 Years.', NULL, '2026-07-15', '2026-08-25', '2026-08-28', NULL, '2026-10-18', NULL, NULL, NULL, '850.00', '175.00', '850.00', 'Debit Card, Credit Card, Net Banking, Mobile Wallet', NULL, '20', '30', 'As per government rules', NULL, '4455 Posts', 'All India', 'Bachelor Degree in Any Stream from Any Recognized University', NULL, NULL, 'Preliminary Examination, Main Examination, Interview', 'Apply online via ibps.in portal.', 'https://ibps.in', NULL, NULL, NULL, NULL, NULL, NULL, 'https://ibps.in', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1, 0, '2026-07-31 01:28:01', '2026-07-31 01:46:28'),
(48, 'UP Police Sub Inspector SI & Platoon Commander Recruitment 2026 (4547 Posts)', 'up-police-sub-inspector-si-platoon-commander-recruitment-2026-4547-posts', 1, 'Uttar Pradesh Police Recruitment and Promotion Board (UPPRPB) invites online forms for 4547 Sub Inspector SI Civil Police posts.', 'UP Police Sub Inspector Recruitment 2026.\n\nTotal Posts: 4547\nAge Limit: 21-28 Years as on 01/07/2026.\nQualification: Graduation Degree in Any Stream.', NULL, '2026-07-15', '2026-08-25', '2026-08-15', NULL, '2026-10-25', NULL, NULL, NULL, '400.00', '400.00', '400.00', 'E-Challan OR Online Payment', NULL, '21', '28', 'As per government rules', NULL, '4547 Posts', 'Uttar Pradesh', 'Bachelor Degree in Any Stream', NULL, NULL, 'Written Exam, PST / PET Physical Test, Document Verification', 'Apply online on UPPRPB official website uppbpb.gov.in.', 'https://uppbpb.gov.in', NULL, NULL, NULL, NULL, NULL, NULL, 'https://uppbpb.gov.in', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1, 0, '2026-07-31 01:28:01', '2026-07-31 01:46:28'),
(49, 'Bihar Police Constable Recruitment 2026 Online Form (21391 Posts)', 'bihar-police-constable-recruitment-2026-online-form-21391-posts', 5, 'Central Selection Board of Constable (CSBC) Bihar invites online application for 21,391 Constable vacancies in Bihar Police.', 'Bihar Police Constable Recruitment 2026.\n\nTotal Posts: 21391\nQualification: 10+2 Intermediate Exam Passed from Any Recognized Board in India.\nAge Limit: 18-25 Years.', NULL, '2026-07-12', '2026-08-22', '2026-08-22', NULL, '2026-10-12', NULL, NULL, NULL, '675.00', '180.00', '675.00', 'Online Payment Gateway', NULL, '18', '25', 'As per government rules', NULL, '21391 Posts', 'Bihar', '10+2 Intermediate Passed', NULL, NULL, 'Written Examination, Physical Efficiency Test (PET), Medical Exam', 'Apply online via csbc.bih.nic.in portal.', 'https://csbc.bih.nic.in', NULL, NULL, NULL, NULL, NULL, NULL, 'https://csbc.bih.nic.in', NULL, NULL, NULL, NULL, NULL, NULL, 1, 0, 0, '2026-07-31 01:28:01', '2026-07-31 01:46:28'),
(50, 'Indian Navy Agniveer SSR & MR 02/2026 Batch Online Form', 'indian-navy-agniveer-ssr-mr-022026-batch-online-form', 7, 'Join Indian Navy Agnipath Scheme 2026. Online applications invited for Agniveer SSR & MR 02/2026 Batch for 4000 Vacancies.', 'Indian Navy Agniveer SSR & MR 02/2026 Entry.\n\nTotal Posts: 4000\nAge Limit: Born between 01/11/2005 to 30/04/2009.\nQualifications:\n- SSR: 10+2 Intermediate with Maths, Physics & Chemistry/Biology/CS.\n- MR: 10th Class Passed.', NULL, '2026-07-18', '2026-08-18', '2026-08-18', NULL, '2026-09-28', NULL, NULL, NULL, '550.00', '550.00', '550.00', 'Debit Card, Credit Card, Net Banking', NULL, '17', '21', 'As per government rules', NULL, '4000 Posts', 'All India', '10th Pass (MR) / 10+2 Pass with PCM (SSR)', NULL, NULL, 'INET Computer Based Exam, PFT Physical Fitness Test, Medical Test', 'Apply online at agniveernavy.cdac.in.', 'https://agniveernavy.cdac.in', NULL, NULL, NULL, NULL, NULL, NULL, 'https://joinindiannavy.gov.in', NULL, NULL, NULL, NULL, NULL, NULL, 1, 0, 0, '2026-07-31 01:28:01', '2026-07-31 01:46:28'),
(51, 'DSSSB TGT / PGT Teacher Recruitment 2026 (5118 Posts)', 'dsssb-tgt-pgt-teacher-recruitment-2026-5118-posts', 8, 'Delhi Subordinate Services Selection Board (DSSSB) has released notification for 5,118 Trained Graduate Teacher TGT & PGT posts.', 'DSSSB TGT / PGT Teacher Recruitment 2026.\n\nTotal Vacancies: 5118\nQualification: Graduate Degree in Related Subject + B.Ed + CTET Passed.\nAge Limit: Below 32 Years.', NULL, '2026-07-05', '2026-08-12', '2026-08-12', NULL, '2026-10-30', NULL, NULL, NULL, '100.00', '0.00', '100.00', 'SBI e-Pay Mode', NULL, '18', '32', 'As per government rules', NULL, '5118 Posts', 'Delhi (NCR)', 'Bachelor Degree in Relevant Field + B.Ed & CTET Paper II', NULL, NULL, 'One Tier Examination, Document Verification', 'Apply online via dsssbonline.nic.in.', 'https://dsssbonline.nic.in', NULL, NULL, NULL, NULL, NULL, NULL, 'https://dsssb.delhi.gov.in', NULL, NULL, NULL, NULL, NULL, NULL, 1, 0, 0, '2026-07-31 01:28:01', '2026-07-31 01:46:28'),
