(1, 'Delhi DSSSB Latest Result 2026', 'delhi-dsssb-latest-result-2026', 11, NULL, 'Candidates who qualify in the DSSSB examination may be required to fill the E-Dossier Form. Complete details will be available in the official result or cutoff notice.', '2026-04-02', NULL, 'https://dsssbonline.nic.in/', 'results/1775138573_delhi-dsssb-latest-result-2026.pdf', 1, 0, NULL, NULL, NULL, 0, 0, '2026-04-02 08:32:53', '2026-07-12 15:19:49', 254),
(2, 'SSC CGL Final Result 2026', 'ssc-cgl-final-result-2026', 17, NULL, NULL, '2026-04-08', NULL, 'https://ssc.gov.in/home/candidate-result', 'results/1775669645_ssc-cgl-final-result-2026.pdf', 1, 0, NULL, NULL, NULL, 0, 0, '2026-04-08 12:04:06', '2026-07-12 21:25:25', 243),
(54, 'Bihar Police CSBC Constable Final Result 2026 Declared', 'bihar-police-csbc-constable-final-result-2026-declared', 37, NULL, 'Bihar Police Constable Final Result 2026 declared on 27 May 2026. 19,838 candidates selected. Check your roll number in the selection list PDF.\r\nBihar Police Constable Final Result 2026 - 19,838 Selected | Sarkari Result. CSBC Bihar Police Constable Final Result 2026 declared on 27 May 2026. 19,838 candidates selected. Download selection list PDF and check your roll number. Bihar Police Result, CSBC Constable Result, Bihar Police Final Result, Constable Selection List 2026.', '2026-05-27', '2026-05-27', 'https://csbc.bihar.gov.in/Result/Final_Selection_Constable_Advt_01_2025.pdf', NULL, 1, 0, NULL, NULL, NULL, 0, 0, '2026-05-28 03:24:32', '2026-07-12 15:36:39', 101),
(55, 'RRB NTPC 10+2 Inter Level Final Result 2026 Declared', 'rrb-ntpc-10-2-inter-level-final-result-2026-declared', NULL, 'RRB NTPC 10+2 Inter Level Final Result 2026 declared on 26 May 2026. Total 3,445 candidates selected. Download zone-wise merit list PDF and check your selection status.', '<h2>RRB NTPC 10+2 Inter Level Final Result 2026 Declared</h2>\r\n<p>The <strong>Railway Recruitment Board (RRB)</strong> has officially declared the <strong>Final Result for Non-Technical Popular Categories (NTPC) 10+2 Undergraduate Level Posts</strong> under Advertisement No. <strong>CEN 06/2024</strong> on <strong>26 May 2026</strong>[citation:1][citation:2][citation:3].</p>\r\n\r\n<h3>Important Dates</h3>\r\n<ul>\r\n<li><strong>Application Start Date:</strong> 21 September 2024</li>\r\n<li><strong>Last Date to Apply:</strong> 27 October 2024</li>\r\n<li><strong>CBT-1 Exam Date:</strong> 07 August to 08 September 2025</li>\r\n<li><strong>CBT-1 Result:</strong> 21 November 2025</li>\r\n<li><strong>CBT-2 Exam Date:</strong> 20 December 2025</li>\r\n<li><strong>CBT-2 Result:</strong> 23 January 2026</li>\r\n<li><strong>Typing Test (CBTST) Date:</strong> 13 February 2026[citation:2][citation:6]</li>\r\n<li><strong>Final Result Declaration Date:</strong> <strong>26 May 2026</strong>[citation:1][citation:4]</li>\r\n</ul>\r\n\r\n<h3>Result Summary</h3>\r\n<ul>\r\n<li><strong>Total Vacancies:</strong> 3,445 Posts[citation:1][citation:2][citation:8]</li>\r\n<li><strong>Post Names:</strong> Junior Clerk cum Typist, Accounts Clerk cum Typist, Commercial cum Ticket Clerk, Trains Clerk[citation:3][citation:5][citation:8]</li>\r\n<li><strong>Total Applications Received:</strong> ~21 Lakh</li>\r\n<li><strong>Candidates Qualified for CBT-2:</strong> 52,008</li>\r\n<li><strong>Candidates Qualified for Typing Test:</strong> 14,947[citation:6]</li>\r\n<li><strong>Final Selected Candidates:</strong> 3,445[citation:1]</li>\r\n</ul>\r\n\r\n<h3>Category-wise Cutoff Marks (Final)</h3>\r\n<table border=\"1\" cellpadding=\"8\" cellspacing=\"0\" style=\"border-collapse: collapse; width: 100%;\">\r\n<thead style=\"background-color: #f2f2f2;\">\r\n<th>Category</th>\r\n<th>Cutoff Marks (Category 1)</th>\r\n<th>Cutoff Marks (Category 4)</th>\r\n</thead>\r\n<tbody>\r\n<td>General (UR)</td>\r\n<td>84.79533</td>\r\n<td>85.38012</td>\r\n</tr>\r\n<td>OBC</td>\r\n<td>83.48083</td>\r\n<td>84.07080</td>\r\n</tr>\r\n<td>SC</td>\r\n<td>81.54762</td>\r\n<td>80.70176</td>\r\n</tr>\r\n<td>ST</td>\r\n<td>80.23599</td>\r\n<td>81.41593</td>\r\n</tr>\r\n<td>EWS</td>\r\n<td>82.89086</td>\r\n<td>82.74853</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><em>Source: Official RRB cutoff notification[citation:7]</em></p>\r\n\r\n<h3>Zone-wise Cutoff Marks</h3>\r\n<table border=\"1\" cellpadding=\"8\" cellspacing=\"0\" style=\"border-collapse: collapse; width: 100%;\">\r\n<thead style=\"background-color: #f2f2f2;\">\r\n<th>RRB Zone</th>\r\n<th>UR Cutoff</th>\r\n<th>OBC Cutoff</th>\r\n<th>SC Cutoff</th>\r\n<th>ST Cutoff</th>\r\n<th>EWS Cutoff</th>\r\n</thead>\r\n<tbody>\r\n<td>RRB Chennai (Cat 1)</td>\r\n<td>84.21053</td>\r\n<td>84.21053</td>\r\n<td>81.87134</td>\r\n<td>78.46608</td>\r\n<td>82.74853</td>\r\n</tr>\r\n<td>RRB Chennai (Cat 4)</td>\r\n<td>86.84211</td>\r\n<td>-</td>\r\n<td>-</td>\r\n<td>-</td>\r\n<td>-</td>\r\n</tr>\r\n<td>RRB Ahmedabad (Cat 1)</td>\r\n<td>84.07</td>\r\n<td>82.89</td>\r\n<td>79.76</td>\r\n<td>78.57</td>\r\n<td>82.89</td>\r\n</tr>\r\n<td>RRB Ahmedabad (Cat 4)</td>\r\n<td>85.67</td>\r\n<td>84.66</td>\r\n<td>84.22</td>\r\n<td>81.25</td>\r\n<td>67.55</td>\r\n</tr>\r\n<td>RRB Ajmer (Cat 1)</td>\r\n<td>84.79</td>\r\n<td>84.21</td>\r\n<td>79.64</td>\r\n<td>82.14</td>\r\n<td>67.54</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><em>Source: Official RRB zone-wise cutoff[citation:9][citation:10]</em></p>\r\n\r\n<h3>How to Check RRB NTPC 10+2 Final Result 2026</h3>\r\n<ol>\r\n<li>Visit the official website of your respective RRB zone (e.g., rrbcdg.gov.in, rrbahmedabad.gov.in, rrbajmer.gov.in, rrbchennai.gov.in, etc.)</li>\r\n<li>Click on the <strong>\"Results\"</strong> or <strong>\"CEN 06/2024\"</strong> section on the homepage</li>\r\n<li>Find and click on the link for <strong>\"RRB NTPC 10+2 Inter Level Final Result 2026\"</strong> or <strong>\"NTPC UG Final Merit List\"</strong></li>\r\n<li>You will be redirected to a login page</li>\r\n<li>Enter your <strong>Registration Number / Roll Number</strong> and <strong>Date of Birth / Password</strong></li>\r\n<li>Submit the details to view your result</li>\r\n<li>Download the result PDF and save it for future reference</li>\r\n<li>Use <strong>Ctrl + F</strong> to search for your Roll Number in the merit list PDF</li>\r\n</ol>\r\n\r\n<h3>Zone-wise Result PDF Links</h3>\r\n<p>Download your respective zone-wise final result PDF from the links below:</p>\r\n<ul>\r\n<li><strong>RRB Ahmedabad:</strong> <a href=\"https://rrbahmedabad.gov.in/result/ntpc_ug_final_2026.pdf\" target=\"_blank\">Click Here</a></li>\r\n<li><strong>RRB Ajmer:</strong> <a href=\"https://rbbajmer.gov.in/result/ntpc_ug_final_2026.pdf\" target=\"_blank\">Click Here</a></li>\r\n<li><strong>RRB Prayagraj (Allahabad):</strong> <a href=\"https://rrbald.gov.in/result/ntpc_ug_final_2026.pdf\" target=\"_blank\">Click Here</a></li>\r\n<li><strong>RRB Bangalore:</strong> <a href=\"https://rrbbnc.gov.in/result/ntpc_ug_final_2026.pdf\" target=\"_blank\">Click Here</a></li>\r\n<li><strong>RRB Bhopal:</strong> <a href=\"https://rrbbpl.gov.in/result/ntpc_ug_final_2026.pdf\" target=\"_blank\">Click Here</a></li>\r\n<li><strong>RRB Bhubaneswar:</strong> <a href=\"https://rbbbs.gov.in/result/ntpc_ug_final_2026.pdf\" target=\"_blank\">Click Here</a></li>\r\n<li><strong>RRB Bilaspur:</strong> <a href=\"https://rbbilaspur.gov.in/result/ntpc_ug_final_2026.pdf\" target=\"_blank\">Click Here</a></li>\r\n<li><strong>RRB Chandigarh:</strong> <a href=\"https://rrbcdg.gov.in/result/ntpc_ug_final_2026.pdf\" target=\"_blank\">Click Here</a></li>\r\n<li><strong>RRB Chennai:</strong> <a href=\"https://rrbchennai.gov.in/result/ntpc_ug_final_2026.pdf\" target=\"_blank\">Click Here</a></li>\r\n<li><strong>RRB Gorakhpur:</strong> <a href=\"https://rrbgkp.gov.in/result/ntpc_ug_final_2026.pdf\" target=\"_blank\">Click Here</a></li>\r\n<li><strong>RRB Guwahati:</strong> <a href=\"https://rrbguwahati.gov.in/result/ntpc_ug_final_2026.pdf\" target=\"_blank\">Click Here</a></li>\r\n<li><strong>RRB Jammu & Srinagar:</strong> <a href=\"https://rrbjammu.gov.in/result/ntpc_ug_final_2026.pdf\" target=\"_blank\">Click Here</a></li>\r\n<li><strong>RRB Kolkata:</strong> <a href=\"https://rrbkolkata.gov.in/result/ntpc_ug_final_2026.pdf\" target=\"_blank\">Click Here</a></li>\r\n<li><strong>RRB Malda:</strong> <a href=\"https://rbbmalda.gov.in/result/ntpc_ug_final_2026.pdf\" target=\"_blank\">Click Here</a></li>\r\n<li><strong>RRB Mumbai:</strong> <a href=\"https://rbbmumbai.gov.in/result/ntpc_ug_final_2026.pdf\" target=\"_blank\">Click Here</a></li>\r\n<li><strong>RRB Patna:</strong> <a href=\"https://rrbpatna.gov.in/result/ntpc_ug_final_2026.pdf\" target=\"_blank\">Click Here</a></li>\r\n<li><strong>RRB Ranchi:</strong> <a href=\"https://rrbranchi.gov.in/result/ntpc_ug_final_2026.pdf\" target=\"_blank\">Click Here</a></li>\r\n<li><strong>RRB Secunderabad:</strong> <a href=\"https://rrbsecunderabad.gov.in/result/ntpc_ug_final_2026.pdf\" target=\"_blank\">Click Here</a></li>\r\n<li><strong>RRB Siliguri:</strong> <a href=\"https://rrbsiliguri.gov.in/result/ntpc_ug_final_2026.pdf\" target=\"_blank\">Click Here</a></li>\r\n<li><strong>RRB Thiruvananthapuram:</strong> <a href=\"https://rrbthiruvananthapuram.gov.in/result/ntpc_ug_final_2026.pdf\" target=\"_blank\">Click Here</a></li>\r\n</ul>\r\n\r\n<h3>Post-wise Vacancy Details</h3>\r\n<ul>\r\n<li><strong>Commercial cum Ticket Clerk:</strong> 2,022 Posts[citation:8]</li>\r\n<li><strong>Junior Clerk cum Typist:</strong> 990 Posts[citation:8]</li>\r\n<li><strong>Accounts Clerk cum Typist:</strong> 361 Posts[citation:8]</li>\r\n<li><strong>Trains Clerk:</strong> 72 Posts[citation:8]</li>\r\n<li><strong>Total:</strong> 3,445 Posts</li>\r\n</ul>\r\n\r\n<h3>Selection Process</h3>\r\n<p>The selection was based on the following stages:</p>\r\n<ol>\r\n<li><strong>CBT-1 (Computer Based Test):</strong> 100 marks screening test</li>\r\n<li><strong>CBT-2 (Computer Based Test):</strong> 240 marks main examination</li>\r\n<li><strong>CBAT/CBTST (Typing Test):</strong> Qualifying in nature - 30 WPM English or 25 WPM Hindi[citation:8]</li>\r\n<li><strong>Document Verification (DV):</strong> Verification of original certificates</li>\r\n<li><strong>Medical Examination:</strong> As per Railway medical standards</li>\r\n<li><strong>Final Merit List:</strong> Based on CBT-2 marks + Typing Test qualification</li>\r\n</ol>\r\n\r\n<h3>What After Result?</h3>\r\n<p>Candidates whose roll numbers appear in the final merit list will be called for:</p>\r\n<ul>\r\n<li><strong>Document Verification (DV):</strong> Shortlisted candidates must appear with original documents</li>\r\n<li><strong>Medical Examination:</strong> Medical fitness as per Railway standards</li>\r\n<li><strong>Appointment Letter:</strong> Will be issued by the respective Railway Zone after successful completion of all stages[citation:4]</li>\r\n</ul>\r\n\r\n<h3>Documents Required for Document Verification</h3>\r\n<ul>\r\n<li>10th Mark Sheet & Certificate (Date of Birth Proof)</li>\r\n<li>10+2 (Intermediate) Mark Sheet & Certificate</li>\r\n<li>Caste Certificate (if applicable) - OBC/SC/ST/EWS</li>\r\n<li>Domicile Certificate</li>\r\n<li>PwD Certificate (if applicable)</li>\r\n<li>Recent Passport Size Photographs</li>\r\n<li>Aadhar Card/Voter ID/PAN Card (ID Proof)</li>\r\n</ul>\r\n\r\n<h3>Important Information</h3>\r\n<ul>\r\n<li><strong>Advertisement No.:</strong> CEN 06/2024[citation:1][citation:6]</li>\r\n<li><strong>Conducting Body:</strong> Railway Recruitment Board (RRB)</li>\r\n<li><strong>Result Status:</strong> FINAL RESULT DECLARED</li>\r\n<li><strong>Result Format:</strong> Zone-wise PDF Merit List[citation:1]</li>\r\n<li><strong>Official Website:</strong> <a href=\"https://indianrailways.gov.in\" target=\"_blank\">https://indianrailways.gov.in</a>[citation:1]</li>\r\n</ul>\r\n\r\n<p><strong>Important Links:</strong><br />\r\n<a href=\"https://indianrailways.gov.in\" target=\"_blank\" rel=\"noopener\">✅ RRB Official Website</a><br />\r\n<a href=\"https://rrbcdg.gov.in\" target=\"_blank\" rel=\"noopener\">✅ RRB CDG Official Portal</a><br />\r\n<a href=\"https://rrbapply.gov.in\" target=\"_blank\" rel=\"noopener\">✅ RRB Common Application Portal</a><br />\r\n<a href=\"notifications/rrb_ntpc_10_2_final_result_2026.pdf\" target=\"_blank\" rel=\"noopener\">📄 Download Official Result Notification PDF</a><br />\r\n<a href=\"notifications/rrb_ntpc_10_2_cutoff_2026.pdf\" target=\"_blank\" rel=\"noopener\">📊 Download Category-wise Cutoff PDF</a></p>\r\n\r\n<p><strong>Tags:</strong> RRB NTPC Result 2026, RRB NTPC 10+2 Final Result, Railway Recruitment Board, NTPC UG Merit List, RRB CEN 06/2024, Railway Jobs, NTPC Selection List, Sarkari Result</p>', '2026-05-26', '2026-05-26', 'https://rrbcdg.gov.in/result/ntpc_ug_final_2026.pdf', 'uploads/results/rrb_ntpc_10_2_result_2026.pdf', 1, 1, 'RRB NTPC 10+2 Inter Level Final Result 2026 Declared - 3,445 Selected | Sarkari Result', 'RRB NTPC 10+2 Inter Level Final Result 2026 declared on 26 May 2026. Total 3,445 candidates selected for Junior Clerk, Accounts Clerk, Commercial cum Ticket Clerk posts. Download zone-wise merit list PDF and check category-wise cutoff marks.', 'RRB NTPC Result 2026, RRB NTPC 10+2 Final Result, Railway Recruitment Board, NTPC UG Merit List, RRB CEN 06/2024, Railway Jobs, NTPC Selection List, RRB Result, NTPC Cutoff 2026, Sarkari Result', 25000, 18500, '2026-05-26 06:00:00', '2026-07-12 15:19:48', 25099),
(56, 'MPPSC Prelims Result 2026 Declared', 'mppsc-prelims-result-2026-declared', NULL, 'MPPSC State Service and State Forest Service Preliminary Exam 2026 result declared on 22 May 2026. Total 3,775 candidates qualified for Mains exam. Check category-wise cutoff and download result PDF.', '<h2>MPPSC Prelims Result 2026 Declared</h2>\r\n<p>The <strong>Madhya Pradesh Public Service Commission (MPPSC)</strong> has officially declared the <strong>State Service and State Forest Service Preliminary Examination 2026 Result</strong> on <strong>22 May 2026</strong> [citation:8]. Candidates who appeared for the preliminary exam conducted on <strong>26 April 2026</strong> can now check their qualifying status and download the result PDF from the official website [citation:2][citation:8].</p>\r\n\r\n<h3>Important Dates</h3>\r\n<ul>\r\n<li><strong>Exam Date:</strong> 26 April 2026 [citation:2][citation:8]</li>\r\n<li><strong>Result Declaration Date:</strong> 22 May 2026 [citation:8]</li>\r\n<li><strong>Mains Application Start Date:</strong> 25 May 2026 [citation:6]</li>\r\n<li><strong>Mains Application Last Date:</strong> 15 June 2026 [citation:6]</li>\r\n<li><strong>Mains Exam Date:</strong> 7-12 September 2026 [citation:6]</li>\r\n</ul>\r\n\r\n<h3>Result Summary</h3>\r\n<ul>\r\n<li><strong>Total Vacancies:</strong> 155 Posts (State Service + Forest Service) [citation:8]</li>\r\n<li><strong>Total Applications Received:</strong> ~1,35,000 [citation:6]</li>\r\n<li><strong>Exam Attendance:</strong> ~72% [citation:6]</li>\r\n<li><strong>Candidates Qualified for Mains:</strong> 3,775 [citation:6]</li>\r\n<li>• Main Category Segment: 3,044 candidates [citation:6]</li>\r\n<li>• Provisional 13% Reservation Segment: 731 candidates [citation:6]</li>\r\n</ul>\r\n\r\n<h3>Selection Process</h3>\r\n<ol>\r\n<li><strong>Preliminary Examination (Objective Type):</strong> Screening test - 200 marks [citation:8]</li>\r\n<li><strong>Mains Examination (Descriptive Type):</strong> Written examination</li>\r\n<li><strong>Interview (Personality Test):</strong> For final selection</li>\r\n</ol>\r\n\r\n<h3>Category-wise Expected Cutoff Marks (Prelims)</h3>\r\n<p><em>Note: Based on exam analysis. Official cutoff to be confirmed with result PDF.</em> [citation:8]</p>\r\n<table border=\"1\" cellpadding=\"8\" cellspacing=\"0\" style=\"border-collapse: collapse; width: 100%;\">\r\n<thead style=\"background-color: #f2f2f2;\">\r\n<th>Category</th>\r\n<th>Expected Cutoff Marks (Out of 200)</th>\r\n</thead>\r\n<tbody>\r\n<td>General (UR)</td>\r\n<td>145-151</td>\r\n</tr>\r\n<tr style=\"background-color: #f9f9f9;\"><td>OBC</td>\r\n<td>140-148</td>\r\n</tr>\r\n<tr>\r\n\r\n\r\n<td>EWS</td>\r\n<td>142-150</td>\r\n</tr>\r\n<tr style=\"background-color: #f9f9f9;\"><td>SC</td>\r\n<td>130-138</td>\r\n</tr>\r\n<tr>\r\n\r\n\r\n<td>ST</td>\r\n<td>120-130</td>\r\n</tr>\r\n<tr style=\"background-color: #f9f9f9;\"><td>PwBD</td>\r\n<td>100-115</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n\r\n<h3>How to Check MPPSC Prelims Result 2026</h3>\r\n<ol>\r\n<li>Visit the official MPPSC website: <strong>https://mppsc.nic.in</strong> [citation:8]</li>\r\n<li>Click on the <strong>\"Result\"</strong> section on the homepage [citation:8]</li>\r\n<li>Look for the link titled <strong>\"State Service and State Forest Service Prelims Exam 2026 - Written Exam Result\"</strong> [citation:8]</li>\r\n<li>Click on the link to open the result PDF</li>\r\n<li>Download the PDF file and search for your roll number using <strong>Ctrl + F</strong> [citation:8]</li>\r\n<li>If your roll number appears in the PDF, you have qualified for the Mains examination</li>\r\n</ol>\r\n\r\n<h3>What After Result?</h3>\r\n<p>Candidates who have qualified the Prelims examination can now apply for the <strong>MPPSC Mains Examination 2026</strong> [citation:6]:</p>\r\n<ul>\r\n<li><strong>Mains Application Start Date:</strong> 25 May 2026</li>\r\n<li><strong>Mains Application Last Date (without late fee):</strong> 15 June 2026</li>\r\n<li><strong>Mains Application with late fee of ₹3,000:</strong> Till 22 June 2026</li>\r\n<li><strong>Mains Application with late fee of ₹25,000:</strong> Till 16 August 2026</li>\r\n<li><strong>Application Correction Window:</strong> 30 May to 17 June 2026 [citation:6]</li>\r\n<li><strong>Mains Exam Dates:</strong> 7-12 September 2026 [citation:6]</li>\r\n</ul>\r\n\r\n<h3>MPPSC Mains Exam Centers</h3>\r\n<p>The Mains examination will be conducted in 12 cities across Madhya Pradesh [citation:6]:</p>\r\n<ul>\r\n<li>Indore</li>\r\n<li>Bhopal</li>\r\n<li>Gwalior</li>\r\n<li>Jabalpur</li>\r\n<li>Ujjain</li>\r\n<li>Sagar</li>\r\n<li>And other major cities</li>\r\n</ul>\r\n\r\n<h3>Documents Required for Mains Application</h3>\r\n<ul>\r\n<li>Prelims Roll Number</li>\r\n<li>Registration Number</li>\r\n<li>Personal Details (Name, Date of Birth, Category)</li>\r\n<li>Educational Qualification Certificates</li>\r\n<li>Recent Passport Size Photograph</li>\r\n<li>Signature</li>\r\n<li>Caste Certificate (if applicable)</li>\r\n<li>EWS Certificate (if applicable)</li>\r\n<li>PwD Certificate (if applicable)</li>\r\n</ul>\r\n\r\n<h3>Important Information</h3>\r\n<ul>\r\n<li><strong>Conducting Body:</strong> Madhya Pradesh Public Service Commission (MPPSC) [citation:8]</li>\r\n<li><strong>Exam Name:</strong> State Service and State Forest Service Preliminary Examination 2026 [citation:8]</li>\r\n<li><strong>Result Status:</strong> PRELIMS RESULT DECLARED [citation:8]</li>\r\n<li><strong>Vacancies:</strong> 156 Posts (including Forest Service) [citation:6]</li>\r\n<li><strong>Result Format:</strong> PDF containing roll numbers of qualified candidates [citation:8]</li>\r\n<li><strong>Official Website:</strong> <a href=\"https://mppsc.nic.in\" target=\"_blank\">https://mppsc.nic.in</a> [citation:8]</li>\r\n</ul>\r\n\r\n<h3>Important Links</h3>\r\n<p>\r\n<a href=\"https://mppsc.nic.in\" target=\"_blank\" rel=\"noopener\">✅ MPPSC Official Website</a><br>\r\n<a href=\"https://mppsc.nic.in/result/state_service_prelims_2026.pdf\" target=\"_blank\" rel=\"noopener\">📥 Download MPPSC Prelims Result 2026 PDF</a><br>\r\n<a href=\"https://mppsc.nic.in/notice/mains_application_2026.pdf\" target=\"_blank\" rel=\"noopener\">📄 Download Mains Application Notification</a><br>\r\n<a href=\"notifications/mppsc_prelims_cutoff_2026.pdf\" target=\"_blank\" rel=\"noopener\">📊 Download Category-wise Cutoff PDF</a>\r\n</p>\r\n\r\n<p><strong>Tags:</strong> MPPSC Prelims Result 2026, MPPSC State Service Result, MP PSC Result, MPPSC Forest Service Result, Madhya Pradesh PSC, Rajya Sewa Pariksha Result, MPPSC Mains 2026, MPPSC Cutoff 2026, MPPSC Merit List, Sarkari Result</p>', '2026-05-22', '2026-05-22', 'https://mppsc.nic.in/result/state_service_prelims_2026.pdf', 'uploads/results/mppsc_prelims_result_2026.pdf', 1, 1, 'MPPSC Prelims Result 2026 Declared - 3,775 Qualified | Sarkari Result', 'MPPSC State Service and State Forest Service Preliminary Exam 2026 Result declared on 22 May 2026. Total 3,775 candidates qualified for Mains exam. Download result PDF and check category-wise expected cutoff marks.', 'MPPSC Prelims Result 2026, MPPSC State Service Result, MP PSC Result, Rajya Sewa Pariksha, MPPSC Forest Service, MPPSC Mains 2026, MPPSC Cutoff, Sarkari Result', 18500, 14200, '2026-05-22 09:00:00', '2026-07-12 20:21:38', 18598),
(57, 'BSF HC RO / RM PET / PST Result 2026 Declared', 'bsf-hc-ro-rm-pet-pst-result-2026-declared', NULL, 'BSF Head Constable Radio Operator & Radio Mechanic PET/PST Phase 1 Result 2026 declared. 48,511 candidates qualified for CBT exam. Download result PDF from BSF official website.', '<h2>BSF HC RO / RM PET / PST Result 2026 Declared</h2>\r\n<p>The <strong>Border Security Force (BSF)</strong> has officially declared the <strong>PET / PST Result for Head Constable Radio Operator (RO) & Radio Mechanic (RM) Recruitment 2025-26</strong> on <strong>25 May 2026</strong>. Candidates who appeared for the Physical Efficiency Test (PET) and Physical Standard Test (PST) conducted between December 2025 and April 2026 can now check their qualifying status on the official BSF recruitment portal.</p>\r\n\r\n<h3>Important Dates</h3>\r\n<ul>\r\n<li><strong>Notification Release Date:</strong> 18 August 2025</li>\r\n<li><strong>Application Start Date:</strong> 24 August 2025</li>\r\n<li><strong>Last Date to Apply Online:</strong> 23 September 2025</li>\r\n<li><strong>Application Correction Date:</strong> 24-26 September 2025</li>\r\n<li><strong>PET/PST Exam Dates:</strong> 26 December 2025 to 02 April 2026 [citation:4]</li>\r\n<li><strong>PET/PST Admit Card:</strong> 17 December 2025 [citation:2]</li>\r\n<li><strong>PET/PST Result Date:</strong> 25 May 2026 [citation:2][citation:4][citation:7]</li>\r\n</ul>\r\n\r\n<h3>Result Summary</h3>\r\n<ul>\r\n<li><strong>Total Vacancies:</strong> 1,121 Posts [citation:3][citation:7][citation:9]</li>\r\n<li>• Head Constable (Radio Operator): 910 Posts [citation:6][citation:7]</li>\r\n<li>• Head Constable (Radio Mechanic): 211 Posts [citation:6][citation:7]</li>\r\n<li><strong>Total Qualified Candidates for CBT:</strong> 48,511 [citation:4]</li>\r\n<li><strong>PET/PST Examination Centers:</strong> 21 centers across India [citation:4]</li>\r\n<li><strong>PET/PST Duration:</strong> 26 December 2025 to 02 April 2026 [citation:4]</li>\r\n</ul>\r\n\r\n<h3>Educational Qualification</h3>\r\n<table border=\"1\" cellpadding=\"8\" cellspacing=\"0\" style=\"border-collapse: collapse; width: 100%;\">\r\n<thead style=\"background-color: #f2f2f2;\">\r\n<th>Post</th>\r\n<th>Qualification</th>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td><strong>HC (RO)</strong></td>\r\n<td>12th with PCM (60% marks) OR 10th pass + 2 Years ITI in Electronics/Radio & TV/Computer Operator [citation:7]</td>\r\n</tr>\r\n<tr style=\"background-color: #f9f9f9;\">\r\n<td><strong>HC (RM)</strong></td>\r\n<td>12th with PCM (60% marks) OR 10th pass + 2 Years ITI in Electronics/Radio & TV/Computer Operator [citation:7]</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n\r\n<h3>Selection Process</h3>\r\n<ol>\r\n<li><strong>Physical Standard Test (PST) / Physical Efficiency Test (PET):</strong> Phase 1 - Completed</li>\r\n<li><strong>Computer Based Test (CBT):</strong> Phase 2 - Upcoming [citation:4][citation:8]</li>\r\n<li><strong>Document Verification (DV):</strong> Verification of original certificates</li>\r\n<li><strong>Medical Examination:</strong> Medical fitness as per BSF standards</li>\r\n</ol>\r\n\r\n<h3>How to Check BSF HC RO / RM PET / PST Result 2026</h3>\r\n<ol>\r\n<li>Visit the official BSF recruitment website: <strong>https://rectt.bsf.gov.in</strong> [citation:5][citation:7]</li>\r\n<li>Click on the <strong>\"Results\"</strong> or <strong>\"Latest Notices\"</strong> section</li>\r\n<li>Look for the link <strong>\"BSF HC RO/RM PET/PST Result 2026\"</strong> [citation:2][citation:6]</li>\r\n<li>Click on the link to open the login page</li>\r\n<li>Enter your <strong>Registration Number / Roll Number</strong> [citation:2][citation:6]</li>\r\n<li>Enter your <strong>Date of Birth / Password</strong> [citation:2][citation:6]</li>\r\n<li>Enter the captcha code and click <strong>Submit / Login</strong></li>\r\n<li>Your PET/PST result will appear on the screen [citation:5][citation:6]</li>\r\n<li>Download and save the result for future reference</li>\r\n</ol>\r\n\r\n<h3>Alternative Method - Check via PDF</h3>\r\n<p>BSF has also released the result in PDF format containing roll numbers of qualified candidates [citation:1][citation:3]. Candidates can:</p>\r\n<ol>\r\n<li>Download the <strong>BSF HC RO/RM PET/PST Result PDF</strong> from the official website</li>\r\n<li>Press <strong>Ctrl + F</strong> to open the search box</li>\r\n<li>Enter your <strong>Roll Number</strong> and press Enter</li>\r\n<li>If your roll number is highlighted in the PDF, you have qualified for the CBT exam [citation:3][citation:4]</li>\r\n</ol>\r\n\r\n<h3>What After Result?</h3>\r\n<p>Candidates who have qualified the PET/PST stage will now be eligible for the <strong>Computer Based Test (CBT)</strong> [citation:4][citation:8]:</p>\r\n<ul>\r\n<li><strong>CBT Admit Card:</strong> Will be released separately on the official website [citation:3]</li>\r\n<li><strong>CBT Exam Date:</strong> To be announced by BSF</li>\r\n<li><strong>CBT Syllabus:</strong> Will be available on the official website</li>\r\n<li><strong>Document Verification:</strong> For candidates who qualify the CBT [citation:8]</li>\r\n<li><strong>Medical Examination:</strong> Final stage of selection [citation:6][citation:8]</li>\r\n</ul>\r\n\r\n<h3>Documents Required for Next Stages</h3>\r\n<ul>\r\n<li>10th Mark Sheet & Certificate (Date of Birth Proof)</li>\r\n<li>12th Mark Sheet & Certificate (with PCM subjects, 60% marks if applicable)</li>\r\n<li>ITI Certificate & Mark Sheet (if applicable)</li>\r\n<li>Caste Certificate (OBC/SC/ST/EWS, if applicable)</li>\r\n<li>Domicile Certificate</li>\r\n<li>Recent Passport Size Photographs</li>\r\n<li>Aadhar Card / Voter ID / PAN Card (ID Proof)</li>\r\n</ul>\r\n\r\n<h3>Important Information</h3>\r\n<ul>\r\n<li><strong>Conducting Body:</strong> Border Security Force (BSF)</li>\r\n<li><strong>Post Name:</strong> Head Constable (Radio Operator & Radio Mechanic) [citation:4][citation:7]</li>\r\n<li><strong>Recruitment Year:</strong> 2025-26</li>\r\n<li><strong>Result Mode:</strong> Online (Login Portal + PDF) [citation:1][citation:5]</li>\r\n<li><strong>Official Website:</strong> <a href=\"https://rectt.bsf.gov.in\" target=\"_blank\">https://rectt.bsf.gov.in</a> [citation:7]</li>\r\n<li><strong>Alternate Website:</strong> <a href=\"https://bsf.gov.in\" target=\"_blank\">https://bsf.gov.in</a> [citation:8][citation:9]</li>\r\n</ul>\r\n\r\n<h3>Important Links</h3>\r\n<p>\r\n<a href=\"https://rectt.bsf.gov.in\" target=\"_blank\" rel=\"noopener\">✅ BSF Recruitment Official Website</a><br>\r\n<a href=\"https://rectt.bsf.gov.in/result/BSF_HC_RO_RM_PET_PST_2026.pdf\" target=\"_blank\" rel=\"noopener\">📥 Download BSF HC RO/RM PET/PST Result PDF (Part-1)</a><br>\r\n<a href=\"https://rectt.bsf.gov.in/result/BSF_HC_RO_RM_PET_PST_2026_Part2.pdf\" target=\"_blank\" rel=\"noopener\">📥 Download BSF HC RO/RM PET/PST Result PDF (Part-2)</a><br>\r\n<a href=\"notifications/bsf_hc_ro_rm_cutoff_2026.pdf\" target=\"_blank\" rel=\"noopener\">📊 Download Category-wise Cutoff PDF</a>\r\n</p>\r\n\r\n<p><strong>Tags:</strong> BSF Result 2026, BSF Head Constable Result, BSF HC RO RM Result, BSF PET PST Result, Border Security Force Recruitment, BSF Phase 1 Result, BSF CBT Exam 2026, Police Jobs, Central Armed Police Forces, Sarkari Result</p>', '2026-05-25', '2026-05-26', 'https://rectt.bsf.gov.in/result/BSF_HC_RO_RM_PET_PST_2026.pdf', 'uploads/results/bsf_hc_ro_rm_result_2026.pdf', 1, 1, 'BSF HC RO / RM PET / PST Result 2026 Declared - 48,511 Qualified | Sarkari Result', 'BSF Head Constable Radio Operator & Radio Mechanic PET/PST Phase 1 Result 2026 declared on 25 May 2026. 48,511 candidates qualified for CBT exam. Download result PDF and check your roll number on official BSF website rectt.bsf.gov.in.', 'BSF Result 2026, BSF Head Constable Result, BSF HC RO RM Result, BSF PET PST Result, Border Security Force Recruitment, BSF Phase 1 Result, BSF CBT Exam 2026, Police Jobs, CAPF Recruitment, Sarkari Result', 28500, 22400, '2026-05-25 13:00:00', '2026-07-12 15:19:47', 28597),
(58, 'SSC Delhi Police HC (AWO/TPO) Result 2026', 'ssc-delhi-police-hc-awo-tpo-result-2026', 1, 'SSC Delhi Police Head Constable (AWO/TPO) Result 2026 has been declared. Check your result online.', 'The Staff Selection Commission (SSC) has released the result for Delhi Police Head Constable (AWO/TPO) Examination 2026. Candidates can download their scorecards and check selection status using the link below.', '2026-02-15', '2026-02-10', 'https://ssc.nic.in/result/delhi-police-hc-awo-tpo-2026', 'uploads/results/ssc_delhi_police_hc_result_2026.pdf', 1, 0, 'SSC Delhi Police HC (AWO/TPO) Result 2026 - Check Online', 'Download SSC Delhi Police Head Constable AWO/TPO Result 2026. Direct link to check merit list and scorecard.', 'SSC Result 2026, Delhi Police HC Result, AWO TPO Result', 0, 0, '2026-05-30 20:12:12', '2026-07-12 17:57:46', 91),
(59, 'RRB Technician Gr-III Result 2026', 'rrb-technician-gr-iii-result-2026', 2, 'RRB Technician Grade 3 Result 2026 declared on May 29, 2026. Check zone-wise merit list and cutoff marks.', '<h2>RRB Technician Gr-III Result 2026</h2>\r\n    <p>The Railway Recruitment Board (RRB) has officially announced the <strong>RRB Technician Grade 3 Result 2026</strong> on <strong>May 29, 2026</strong>. Candidates who appeared for the Computer-Based Test (CBT) held in March 2026 can now check their results, merit list, zone-wise cutoffs, and scorecards online.</p>\r\n    \r\n    <h3>Overview</h3>\r\n    <ul>\r\n        <li><strong>Exam Name:</strong> RRB Technician Grade 3 Recruitment 2026</li>\r\n        <li><strong>CEN No.:</strong> 02/2025</li>\r\n        <li><strong>Result Declaration Date:</strong> May 29, 2026</li>\r\n        <li><strong>Exam Dates:</strong> March 6, 9, 10, 2026</li>\r\n        <li><strong>Total Vacancies:</strong> 6,055 posts</li>\r\n        <li><strong>Total Candidates:</strong> Over 15 lakh</li>\r\n    </ul>\r\n    \r\n    <h3>Minimum Qualifying Marks (Out of 100)</h3>\r\n    <ul>\r\n        <li><strong>General (UR):</strong> 40%</li>\r\n        <li><strong>OBC:</strong> 30%</li>\r\n        <li><strong>SC:</strong> 30%</li>\r\n        <li><strong>ST:</strong> 25%</li>\r\n    </ul>\r\n    \r\n    <h3>How to Check Result</h3>\r\n    <ol>\r\n        <li>Visit the official website of your respective RRB zone</li>\r\n        <li>Click on \"Technician Grade III Result 2026\" link</li>\r\n        <li>Download the merit list PDF</li>\r\n        <li>Search your roll number using Ctrl+F</li>\r\n    </ol>', '2026-05-29', '2026-05-29', 'https://rrb.digialm.com/result/technician-gr-iii-2026', 'uploads/results/rrb_technician_gr3_result_2026.pdf', 1, 1, 'RRB Technician Gr-III Result 2026 - Check Cutoff & Merit List', 'Download RRB Technician Grade 3 Result 2026. Check zone-wise cutoff marks, merit list PDF, and scorecard. 6,055 vacancies declared on May 29, 2026.', 'RRB Result 2026, Technician Grade 3, RRB Technician Result, Railway Technician Cutoff, RRB Gr-III Merit List', 12500, 3400, '2026-05-30 20:13:35', '2026-07-12 15:32:41', 12594),
